package com.wintertodtautopilot;

import java.util.Arrays;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.itemstats.Effect;
import net.runelite.client.plugins.itemstats.ItemStatChanges;
import net.runelite.client.plugins.itemstats.StatChange;
import net.runelite.client.plugins.itemstats.stats.Stats;

@Singleton
public class WintertodtInventoryTracker
{
    @Inject private Client client;
    @Inject private ItemStatChanges itemStats;
    private Item[] previous = new Item[0];

    /** Inventory has only 28 slots; equipment and food effects are sampled once per tick. */
    public void fill(WintertodtSnapshot.WintertodtSnapshotBuilder b)
    {
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        Item[] observedItems = inventory == null ? null : inventory.getItems();
        Item[] wornItems = equipment == null ? null : equipment.getItems();
        boolean inventoryKnown = observedItems != null;
        boolean equipmentKnown = wornItems != null;
        Item[] items = inventoryKnown ? observedItems : new Item[0];
        int roots = 0, kindling = 0, food = 0, doses = 0, herbs = 0, unfinished = 0, occupied = 0;
        int bestFood = -1, potion = -1, smallestDose = 5;
        boolean knife = false, fletchingKnife = false, hammer = false, tinder = false, torch = false, axe = false;
        for (Item item : items)
        {
            int id = item.getId();
            if (id < 0 || item.getQuantity() <= 0) { continue; }
            occupied++;
            int q = item.getQuantity();
            if (id == ItemID.WINT_BRUMA_ROOT) { roots += q; }
            if (id == ItemID.WINT_BRUMA_KINDLING) { kindling += q; }
            if (id == ItemID.WINT_HERB) { herbs += q; }
            if (id == ItemID.WINT_VIAL) { unfinished += q; }
            int d = WintertodtConstants.doses(id);
            doses += d * q;
            if (d > 0 && d < smallestDose) { potion = id; smallestDose = d; }
            if (validFood(id)) { food += q; if (bestFood < 0) { bestFood = id; } }
            knife |= knife(id);
            fletchingKnife |= id == ItemID.FLETCHING_KNIFE;
            hammer |= hammer(id);
            tinder |= id == ItemID.TINDERBOX;
            torch |= torch(id);
            axe |= axe(id);
        }
        int warmItems = equipmentKnown ? 0 : -1;
        if (equipmentKnown)
        {
            for (Item item : wornItems)
            {
                if (item.getId() < 0) { continue; }
                fletchingKnife |= item.getId() == ItemID.FLETCHING_KNIFE;
                hammer |= hammer(item.getId());
                torch |= torch(item.getId());
                axe |= axe(item.getId());
                if (WintertodtWarmClothing.isWarm(client.getItemDefinition(item.getId()).getName())) { warmItems++; }
            }
        }
        b.inventoryKnown(inventoryKnown).equipmentKnown(equipmentKnown)
            .brumaRoots(roots).brumaKindling(kindling).foodCount(food).rejuvenationDoses(doses)
            .unfinishedPotionCount(unfinished).brumaHerbCount(herbs).freeSlots(inventoryKnown ? 28 - occupied : 0)
            .warmthItem(potion >= 0 ? potion : bestFood).potionItem(potion)
            .hasKnife(knife).hasFletchingKnife(fletchingKnife).hasHammer(hammer).hasTinderbox(tinder).hasBrumaTorch(torch).hasAxe(axe)
            .warmClothingCount(warmItems < 0 ? -1 : Math.min(4, warmItems));
    }

    private boolean validFood(int id)
    {
        if (id == ItemID.TRIANGLE_SANDWICH || id == ItemID.RAG_BOTTLE_WINE) { return false; }
        ItemComposition item = client.getItemDefinition(id);
        if (item.getNote() != -1 || item.getInventoryActions() == null
            || !Arrays.asList(item.getInventoryActions()).contains("Eat")) { return false; }
        Effect effect = itemStats.get(id);
        if (effect == null) { return false; }
        for (StatChange change : effect.calculate(client).getStatChanges())
        {
            // Theoretical healing is important: food still warms at full Hitpoints.
            if (change != null && change.getStat() == Stats.HITPOINTS && change.getTheoretical() >= 4)
            {
                return true;
            }
        }
        return false;
    }
    private boolean axe(int id)
    {
        ItemComposition item = client.getItemDefinition(id);
        if (item.getNote() != -1) { return false; }
        String name = item.getName().toLowerCase(Locale.ROOT);
        // Names cover cosmetic variants; exclude pickaxes, battleaxes and thrownaxes.
        return name.contains(" axe") && !name.contains("battleaxe") && !name.contains("pickaxe")
            && !name.contains("thrownaxe") && !name.contains("broken") && !name.contains("head");
    }
    // Inventory only: a wielded fletching knife still needs a knife in the inventory to start fletching.
    private static boolean knife(int id) { return id == ItemID.KNIFE || id == ItemID.FLETCHING_KNIFE; }
    private static boolean hammer(int id)
    {
        return id == ItemID.HAMMER || id == ItemID.IMCANDO_HAMMER || id == ItemID.IMCANDO_HAMMER_OFFHAND;
    }
    private static boolean torch(int id) { return id == ItemID.WINT_TORCH || id == ItemID.WINT_TORCH_OFFHAND; }

    public boolean changed()
    {
        ItemContainer container = client.getItemContainer(InventoryID.INV);
        Item[] current = container == null ? null : container.getItems();
        if (current == null) { previous = new Item[0]; return false; }
        boolean changed = !Arrays.equals(previous, current);
        previous = current.clone();
        return changed;
    }
    /** Called before changed() advances the previous inventory. Covers partial food transformations. */
    public boolean quantityDecreased(int itemId)
    {
        if (itemId < 0) { return false; }
        ItemContainer container = client.getItemContainer(InventoryID.INV);
        Item[] current = container == null ? null : container.getItems();
        if (current == null) { return false; }
        return quantity(previous, itemId) > quantity(current, itemId);
    }
    private static int quantity(Item[] items, int itemId)
    {
        int count = 0;
        for (Item item : items) { if (item.getId() == itemId) { count += item.getQuantity(); } }
        return count;
    }
    public void reset() { previous = new Item[0]; }
}

package com.wintertodtautopilot;

/** One eligibility rule for every Solo action that can restore drain. No timing prediction. */
final class WintertodtMaintenancePolicy
{
    enum Verdict { ALLOW, RECOVERY, COVERAGE, REMOTE_FIRE, UNOBSERVED }
    static Verdict evaluate(WintertodtSnapshot s, WorkingCorner destination, ObjectiveType action,
        boolean finishing, boolean recovering, boolean multipleFires, WorkingCorner home)
    {
        CornerObservation c = s.corner(destination);
        int tick = s.getObservationTick();
        if (c == null || !c.brazierFresh(tick) || c.getBrazierState() == BrazierState.UNKNOWN
            || c.getBrazierState() == BrazierState.UNAVAILABLE || !c.isPyromancerVisible()
            || !c.pyromancerFresh(tick) || c.getPyromancerState() == CornerObservation.PyromancerState.UNKNOWN)
        { return Verdict.UNOBSERVED; }
        boolean recovery = !finishing && (recovering || s.getWintertodtEnergy() <= WintertodtSoloEnergyModel.RECOVERY_TRIGGER);
        boolean inactiveFire = c.getBrazierState() == BrazierState.UNLIT || c.getBrazierState() == BrazierState.BROKEN;
        // Healing at a known extinguished fire cannot restart drain. During recovery
        // even standing-pyromancer healing requires this evidence.
        if (action == ObjectiveType.HEAL_PYROMANCER && inactiveFire) { return Verdict.ALLOW; }
        if (action == ObjectiveType.HEAL_PYROMANCER && c.getPyromancerState() == CornerObservation.PyromancerState.ALIVE && !recovery)
        { return Verdict.ALLOW; }
        if (recovery) { return Verdict.RECOVERY; }
        if (s.getWintertodtEnergy() < 1 || s.getWintertodtEnergy() > 100 || s.observedGlobalLitBraziers() < 0)
        { return Verdict.COVERAGE; }
        if (!multipleFires)
        {
            for (CornerObservation other : s.getCorners())
            {
                if (other.getCorner() != home && other.getBrazierState() == BrazierState.LIT)
                { return Verdict.REMOTE_FIRE; }
            }
        }
        return Verdict.ALLOW;
    }
}

