package com.wintertodtautopilot;

import java.util.ArrayDeque;
import java.util.Deque;

/** Recent energy drain, with blended windows to avoid chasing individual HUD drops. */
public final class WintertodtRoundForecast
{
    private final Deque<int[]> samples = new ArrayDeque<>();
    private double smoothedRate;
    private int lastDropTick = -1;
    private int secondsLeft = -1;

    public int getSecondsLeft() { return secondsLeft; }
    public int getBudgetSeconds() { return secondsLeft < 0 ? -1 : Math.max(0, (int) (secondsLeft * .9) - 3); }
    public void reset()
    {
        samples.clear(); smoothedRate = 0; lastDropTick = -1; secondsLeft = -1;
    }
    public void observe(int energy, int tick, int lit)
    {
        if (energy <= 0 || energy > 100 || lit <= 0) { reset(); return; }
        if (!samples.isEmpty() && (energy > samples.getLast()[1] || tick <= samples.getLast()[0]))
        { reset(); }
        boolean dropped = !samples.isEmpty() && energy < samples.getLast()[1];
        if (samples.isEmpty() || dropped) { lastDropTick = tick; }
        samples.addLast(new int[]{tick, energy});
        while (!samples.isEmpty() && tick - samples.getFirst()[0] > 150) { samples.removeFirst(); }
        secondsLeft = -1;
        // A stopped drain must not leave a convincing but stale countdown.
        if (tick - lastDropTick > 20) { return; }
        double longRate = rate(tick, 150), recentRate = rate(tick, 60);
        if (longRate <= 0) { return; }
        double rate = recentRate > 0 ? longRate * .65 + recentRate * .35 : longRate;
        if (smoothedRate == 0) { smoothedRate = rate; }
        else if (dropped) { smoothedRate = smoothedRate * .6 + rate * .4; }
        secondsLeft = (int) Math.ceil(energy * .6 / smoothedRate);
    }
    private double rate(int tick, int window)
    {
        int count = 0, changes = 0, firstTick = -1, firstEnergy = -1, lastEnergy = -1;
        double sumT = 0, sumE = 0, sumTT = 0, sumTE = 0;
        for (int[] sample : samples)
        {
            if (tick - sample[0] > window) { continue; }
            if (firstTick < 0) { firstTick = sample[0]; firstEnergy = sample[1]; }
            double t = sample[0] - tick;
            double e = sample[1];
            ++count; sumT += t; sumE += e; sumTT += t * t; sumTE += t * e;
            if (lastEnergy >= 0 && sample[1] < lastEnergy) { ++changes; }
            lastEnergy = sample[1];
        }
        // Thirty ticks and three separate drops prevent a single burst becoming a forecast.
        if (count < 4 || changes < 3 || tick - firstTick < 30 || firstEnergy - lastEnergy < 3) { return 0; }
        double denominator = count * sumTT - sumT * sumT;
        return denominator <= 0 ? 0 : Math.max(0, -(count * sumTE - sumT * sumE) / denominator);
    }
}

package com.wintertodtautopilot;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Singleton
public class WintertodtRoundTracker
{
    private static final Pattern NUMBER = Pattern.compile("([0-9][0-9,]*)");
    @Inject private Client client;
    private RoundState previous = RoundState.OUTSIDE;
    private final WintertodtRoundForecast forecast = new WintertodtRoundForecast();
    private int completedAt = -1;
    private int finalPoints = -1;

    public void reset()
    {
        previous = RoundState.OUTSIDE;
        forecast.reset();
        completedAt = -1;
        finalPoints = -1;
    }
    public void fill(WintertodtSnapshot.WintertodtSnapshotBuilder b, boolean insidePrison, int lit)
    {
        int tick = client.getTickCount();
        // The current HUD puts "Wintertodt's Energy: 70%" in the bar title.
        // ENERGY is a legacy widget and can be hidden/empty in the live interface.
        String titleText = visibleText(client.getWidget(InterfaceID.WintStatus.ENERGY_TITLE));
        String legacyText = visibleText(client.getWidget(InterfaceID.WintStatus.ENERGY));
        String scoreText = visibleText(client.getWidget(InterfaceID.WintStatus.POINTS));
        b.energyTitleText(titleText).energyText(legacyText).pointsText(scoreText);
        int energy = parseNumber(titleText);
        if (energy < 0 || energy > 100)
        {
            energy = parseNumber(legacyText);
        }
        if (energy > 100) { energy = -1; }
        int points = parseNumber(scoreText);
        int seconds = client.getVarbitValue(VarbitID.WINT_TRANSMIT_RESPAWNDELAY) * 30 / 50;
        RoundState state;
        if (!insidePrison) { state = RoundState.LOBBY; }
        else if (seconds > 0) { state = RoundState.COUNTDOWN; }
        else if (energy > 0) { state = RoundState.ACTIVE; }
        else { state = RoundState.COUNTDOWN; }
        boolean wasActive = previous == RoundState.ACTIVE || previous == RoundState.ENDING;
        if (insidePrison && wasActive && (energy == 0 || seconds > 0))
        {
            completedAt = tick;
            state = RoundState.COMPLETE;
        }
        if (insidePrison && completedAt >= 0 && tick - completedAt < 5 && energy <= 0)
        {
            state = RoundState.COMPLETE;
        }
        if (state == RoundState.ACTIVE && !wasActive)
        {
            forecast.reset(); completedAt = -1; finalPoints = -1;
        }
        EndUrgency urgency = EndUrgency.NORMAL;
        if (state == RoundState.ACTIVE)
        {
            if (points >= 0) { finalPoints = points; }
            urgency = classify(energy, tick, lit);
            if (urgency != EndUrgency.NORMAL) { state = RoundState.ENDING; }
        }
        else { forecast.reset(); }
        if (state == RoundState.COMPLETE && finalPoints >= 0)
        {
            finalPoints = Math.max(points, finalPoints);
            points = finalPoints;
        }
        b.roundState(state).wintertodtEnergy(energy).points(points).secondsToStart(seconds)
            .endUrgency(urgency).litBraziers(lit)
            .estimatedSecondsLeft(forecast.getSecondsLeft()).roundBudgetSeconds(forecast.getBudgetSeconds());
        previous = state;
    }
    EndUrgency classify(int energy, int tick, int lit)
    {
        forecast.observe(energy, tick, lit);
        double secondsLeft = forecast.getSecondsLeft() < 0 ? Double.POSITIVE_INFINITY : forecast.getSecondsLeft();
        // Energy cutoffs are conservative categories, not promises of an exact finish time.
        if (energy <= 3 || secondsLeft <= 10) { return EndUrgency.IMMINENT; }
        if (energy <= 12 && lit > 0 || secondsLeft <= 35) { return EndUrgency.ENDING_SOON; }
        return EndUrgency.NORMAL;
    }
    static int readNumber(Widget widget)
    {
        return parseNumber(visibleText(widget));
    }
    private static String visibleText(Widget widget)
    { return widget == null || widget.isHidden() || widget.getText() == null ? "" : widget.getText(); }
    static int parseNumber(String text)
    {
        if (text == null) { return -1; }
        Matcher matcher = NUMBER.matcher(Text.removeTags(text));
        if (!matcher.find()) { return -1; }
        try { return Integer.parseInt(matcher.group(1).replace(",", "")); }
        catch (NumberFormatException e) { return -1; }
    }
}

package com.wintertodtautopilot;

/** Shared safety priority for both planners. */
final class WintertodtSafety
{
    private WintertodtSafety() { }
    static WintertodtObjective objective(WintertodtSnapshot s, PlannerSettings settings)
    {
        if (settings.isIgnoreWarmthSupplies() || s.getRoundState() == RoundState.OUTSIDE || s.getRoundState() == RoundState.LOBBY
            || s.getWarmth() < 0 || s.getWarmth() >= 100 || s.getWarmth() > settings.getRestoreWarmth()) { return null; }
        boolean emergency = s.getWarmth() <= settings.getEmergencyWarmth();
        if (!s.isInventoryKnown())
        {
            return new WintertodtObjective(ObjectiveType.RESTORE_WARMTH,
                "LOW WARMTH - check supplies or move to the safe lobby", "warmth_supplies_unknown", TargetKind.DOOR, 0, true);
        }
        if (s.getWarmthItem() >= 0)
        {
            return new WintertodtObjective(ObjectiveType.RESTORE_WARMTH,
                (emergency ? "LOW WARMTH - " : "") + (WintertodtConstants.doses(s.getWarmthItem()) > 0
                    ? "Drink rejuvenation potion" : "Eat food to restore warmth"),
                "warmth_low", TargetKind.NONE, 1, emergency, s.getWarmthItem());
        }
        return new WintertodtObjective(ObjectiveType.RESTORE_WARMTH,
            "Move to the safe lobby - no warmth supplies", "no_warmth_supplies", TargetKind.DOOR, 0, true);
    }

    static WintertodtObjective missingSupplies(WintertodtSnapshot s)
    {
        if (s.getRoundState() == RoundState.OUTSIDE || s.getRoundState() == RoundState.LOBBY
            || s.isInventoryKnown() && s.isEquipmentKnown()) { return null; }
        return new WintertodtObjective(ObjectiveType.WAIT, "Waiting for inventory and equipment observations",
            "supplies_unobserved", TargetKind.NONE, 0, false);
    }
}

package com.wintertodtautopilot;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class WintertodtSceneOverlay extends Overlay
{
    private final Client client;
    private final WintertodtAutopilotPlugin plugin;
    private final WintertodtAutopilotConfig config;
    private final ModelOutlineRenderer outlines;
    @Inject
    WintertodtSceneOverlay(Client client, WintertodtAutopilotPlugin plugin,
        WintertodtAutopilotConfig config, ModelOutlineRenderer outlines)
    {
        this.client = client; this.plugin = plugin; this.config = config; this.outlines = outlines;
        setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_SCENE);
    }
    @Override
    public Dimension render(Graphics2D graphics)
    {
        WintertodtObjective o = plugin.getObjective();
        WintertodtSnapshot s = plugin.getSnapshot();
        if (plugin.isPaused() || o == null || s.getRoundState() == RoundState.OUTSIDE
            || WintertodtGuidance.performing(s, o)) { return null; }
        Color color = WintertodtOverlay.color(o);
        float strength = WintertodtHighlight.strength(s, o, config.pulseInterruptions());
        if (config.highlightTarget())
        {
            NPC npc = plugin.getTargetNpc(); TileObject object = plugin.getTargetObject();
            int width = Math.max(1, Math.min(4, config.highlightBorderWidth()));
            Color outline = WintertodtHighlight.alpha(color, (int) (255 * strength));
            if (npc != null) { outlines.drawOutline(npc, width, outline, 1); }
            else if (object != null) { outlines.drawOutline(object, width, outline, 1); }
        }
        if (!config.showPath() && !config.highlightStandingTiles()) { return null; }
        // Isolate the clip: paths and floor markers must never paint over the UI.
        Graphics2D floor = (Graphics2D) graphics.create();
        try
        {
            floor.clip(new java.awt.Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
                client.getViewportWidth(), client.getViewportHeight()));
            List<WorldPoint> path = plugin.getPath();
            if (config.showPath())
            {
                Point previous = null;
                // Only join validated tile edges; do not bridge missing projections.
                for (WorldPoint step : path)
                {
                    LocalPoint local = LocalPoint.fromWorld(client, step);
                    Point next = local == null ? null : Perspective.localToCanvas(client, local, step.getPlane());
                    if (previous != null && next != null) { WintertodtHighlight.routeEdge(floor, previous, next, color, strength); }
                    previous = next;
                }
            }
            if (config.highlightStandingTiles())
            {
                WorldPoint destination = standingPoint(s, o, path);
                Polygon tile = destination == null ? null : tile(destination);
                if (tile != null)
                {
                    WintertodtHighlight.tile(floor, tile, color, strength, true);
                }
            }
        }
        finally { floor.dispose(); }
        return null;
    }
    private Polygon tile(WorldPoint point)
    {
        LocalPoint local = LocalPoint.fromWorld(client, point);
        return local == null ? null : Perspective.getCanvasTilePoly(client, local);
    }
    static WorldPoint standingPoint(WintertodtSnapshot s, WintertodtObjective o, List<WorldPoint> path)
    {
        if (o.getTarget() == TargetKind.NONE && s.getCurrentActivity() != PlayerActivity.MOVING
            && (o.getType() == ObjectiveType.FLETCH || o.getType() == ObjectiveType.MAKE_REJUVENATION))
        { return s.getPlayerLocation(); }
        return path.isEmpty() ? null : path.get(path.size() - 1);
    }
}

package com.wintertodtautopilot;

import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** One immutable observation. -1 denotes an unavailable numeric server/widget signal. */
@Value
@Builder(toBuilder = true)
public class WintertodtSnapshot
{
    @Builder.Default int observationTick = -1;
    @lombok.Singular private java.util.List<CornerObservation> corners;
    @lombok.Singular private java.util.List<BrazierRoute> brazierRoutes;
    @Builder.Default RoundState roundState = RoundState.OUTSIDE;
    @Builder.Default int wintertodtEnergy = -1;
    @Builder.Default int warmth = -1;
    @Builder.Default int rawWarmth = -1;
    @Builder.Default int points = -1;
    @Builder.Default int secondsToStart = -1;
    /** Unavailable containers are not empty inventories. Fixtures must declare their evidence too. */
    boolean inventoryKnown;
    boolean equipmentKnown;
    @Builder.Default String energyTitleText = "";
    @Builder.Default String energyText = "";
    @Builder.Default String pointsText = "";
    @Builder.Default WarmthAction warmthAction = WarmthAction.NONE;
    public enum WarmthAction { NONE, REQUESTED, CONFIRMED, UNCONFIRMED }
    @Builder.Default ActionState actionState = ActionState.NONE;
    @Builder.Default PlayerActivity actionActivity = PlayerActivity.IDLE;
    @Builder.Default WorkingCorner actionCorner = WorkingCorner.AUTOMATIC;
    public enum ActionState { NONE, REQUESTED, IN_PROGRESS, CONFIRMED, INTERRUPTED, UNCONFIRMED }
    /** Per-observation attributed consumption, never inferred from a bare inventory loss. */
    int personalDosesUsed;
    int healingDosesUsed;
    int brumaRoots;
    int brumaKindling;
    @Builder.Default int firemakingLevel = 50;
    @Builder.Default int warmClothingCount = -1;
    int foodCount;
    int rejuvenationDoses;
    int unfinishedPotionCount;
    int brumaHerbCount;
    int freeSlots;
    @Builder.Default int runEnergyPercent = -1;
    @Builder.Default int warmthItem = -1;
    @Builder.Default int potionItem = -1;
    boolean hasKnife;
    boolean hasFletchingKnife;
    boolean hasHammer;
    boolean hasTinderbox;
    boolean hasBrumaTorch;
    boolean hasAxe;
    boolean canMixPotion;
    boolean localPyromancerKnown;
    boolean localPyromancerIncapacitated;
    @Builder.Default BrazierState localBrazierState = BrazierState.UNKNOWN;
    @Builder.Default PlayerActivity currentActivity = PlayerActivity.IDLE;
    boolean playerIdle;
    boolean interrupted;
    int inactiveTicks;
    WorldPoint playerLocation;
    @Builder.Default WorkingCorner workingCorner = WorkingCorner.AUTOMATIC;
    @Builder.Default EndUrgency endUrgency = EndUrgency.NORMAL;
    int litBraziers;
    @Builder.Default int estimatedSecondsLeft = -1;
    @Builder.Default int roundBudgetSeconds = -1;
    /** Walking tile distance to a usable adjacent tile; -1 if not observed. */
    @Builder.Default int brazierDistance = -1;
    @Builder.Default String interaction = "None";
    /** -1 means incomplete evidence; a loaded-object count is not global coverage. */
    public int observedGlobalLitBraziers()
    {
        java.util.EnumSet<WorkingCorner> seen = java.util.EnumSet.noneOf(WorkingCorner.class);
        int lit = 0;
        for (CornerObservation c : corners)
        {
            if (c.getCorner() == WorkingCorner.AUTOMATIC || !seen.add(c.getCorner())
                || c.getBrazierSource() == CornerObservation.Source.NONE || !c.brazierFresh(observationTick)
                || c.getBrazierState() == BrazierState.UNKNOWN || c.getBrazierState() == BrazierState.UNAVAILABLE)
            { return -1; }
            if (c.getBrazierState() == BrazierState.LIT) { ++lit; }
        }
        return seen.size() == 4 ? lit : -1;
    }
    /** Count standing pyromancers at lit fires. This does not observe the random restart delay. */
    public int observedFunctionalBraziers()
    {
        if (observedGlobalLitBraziers() < 0) { return -1; }
        int active = 0;
        for (CornerObservation c : corners)
        {
            if (c.getBrazierState() != BrazierState.LIT) { continue; }
            if (!c.isPyromancerVisible() || !c.pyromancerFresh(observationTick)
                || c.getPyromancerState() == CornerObservation.PyromancerState.UNKNOWN) { return -1; }
            if (c.getPyromancerState() == CornerObservation.PyromancerState.ALIVE) { active++; }
        }
        return active;
    }
    public CornerObservation corner(WorkingCorner corner)
    {
        for (CornerObservation c : corners) { if (c.getCorner() == corner) { return c; } }
        return null;
    }
    public BrazierRoute routeTo(WorkingCorner corner)
    {
        for (BrazierRoute route : brazierRoutes) { if (route.getDestination() == corner) { return route; } }
        return null;
    }
    public int inventoryPoints() { return brumaRoots * WintertodtConstants.ROOT_POINTS + brumaKindling * WintertodtConstants.KINDLING_POINTS; }
    public int potentialPointsIfFletched() { return (brumaRoots + brumaKindling) * WintertodtConstants.KINDLING_POINTS; }
    public int projectedPoints() { return points < 0 ? -1 : points + inventoryPoints(); }
    public boolean rewardThresholdReached() { return points >= 500; }
    public boolean active() { return roundState == RoundState.ACTIVE || roundState == RoundState.ENDING; }
}

package com.wintertodtautopilot;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/** Opt-in diagnostic format. No chat, account identifiers, scene handles or unbounded history. */
final class WintertodtSoloCapture
{
    static final String PREFIX = "solo_capture_v1 ";
    // Checkpoints deliberately bind replay to this controller revision. Bump on incompatible changes.
    private static final String REVISION = "phase3-ignore-warmth-5";
    private final Gson gson;
    @javax.inject.Inject
    WintertodtSoloCapture(Gson gson) { this.gson = gson; }
    enum Lifecycle { NONE, RESET, SUSPEND }

    JsonElement checkpoint(WintertodtSoloEngine engine) { return gson.toJsonTree(engine); }
    WintertodtSoloEngine restore(JsonElement checkpoint)
    { return gson.fromJson(checkpoint, WintertodtSoloEngine.class); }

    String encode(WintertodtSnapshot snapshot, PlannerSettings settings, int pointGoal,
        boolean requestFinish, Lifecycle lifecycle, boolean segmentStart, long sequence, JsonElement before,
        WintertodtObjective expected, SoloPhase phase, Client client)
    {
        Record r = new Record();
        r.revision = REVISION;
        r.snapshot = snapshot.toBuilder().interaction("None".equals(snapshot.getInteraction()) ? "None" : "Present").build();
        r.settings = settings; r.pointGoal = pointGoal; r.requestFinish = requestFinish;
        r.lifecycle = lifecycle; r.segmentStart = segmentStart; r.before = before;
        r.sequence = sequence;
        r.expected = expected; r.phase = phase;
        r.hud = hud(client);
        java.util.Map<WorkingCorner, BrazierState> hudStates = WintertodtBrazierHud.read(client);
        r.hudDecoded = hudStates;
        for (CornerObservation c : snapshot.getCorners())
        {
            BrazierState remote = hudStates.get(c.getCorner());
            if (c.getBrazierSource() == CornerObservation.Source.DIRECT_SCENE && c.brazierFresh(snapshot.getObservationTick())
                && remote != null && remote != BrazierState.UNKNOWN && remote != c.getBrazierState()) { r.hudSceneConflict = true; }
        }
        return PREFIX + gson.toJson(r);
    }

    Record decode(String line)
    {
        int start = line.indexOf(PREFIX);
        if (start < 0) { throw new IllegalArgumentException("Not a Solo capture line"); }
        if (line.length() > 1_000_000) { throw new IllegalArgumentException("Capture line is too large"); }
        Record r = gson.fromJson(line.substring(start + PREFIX.length()), Record.class);
        if (r == null || !REVISION.equals(r.revision) || r.snapshot == null || r.settings == null
            || r.before == null || !r.before.isJsonObject() || r.expected == null || r.phase == null || r.lifecycle == null)
        { throw new IllegalArgumentException("Unsupported or incomplete Solo capture"); }
        return r;
    }

    private static List<HudWidget> hud(Client client)
    {
        List<HudWidget> result = new ArrayList<>();
        if (client == null) { return result; }
        for (int id : new int[]{InterfaceID.WintStatus.BRAZIER1, InterfaceID.WintStatus.BRAZIER2,
            InterfaceID.WintStatus.BRAZIER3, InterfaceID.WintStatus.BRAZIER4})
        {
            HudWidget h = new HudWidget(); h.id = id;
            Widget w = client.getWidget(id);
            h.present = w != null;
            if (w != null)
            {
                h.hidden = w.isHidden(); h.sprite = w.getSpriteId();
                Rectangle b = w.getBounds();
                if (b != null) { h.x = b.x; h.y = b.y; h.width = b.width; h.height = b.height; }
            }
            result.add(h);
        }
        return result;
    }

    static final class Record
    {
        String revision;
        WintertodtSnapshot snapshot;
        PlannerSettings settings;
        int pointGoal;
        boolean requestFinish;
        Lifecycle lifecycle;
        boolean segmentStart;
        long sequence;
        JsonElement before;
        WintertodtObjective expected;
        SoloPhase phase;
        List<HudWidget> hud;
        java.util.Map<WorkingCorner, BrazierState> hudDecoded;
        boolean hudSceneConflict;
    }
    private static final class HudWidget
    {
        int id, sprite = -1, x, y, width, height;
        boolean present, hidden;
    }

    /** Replays consecutive decisions, seeding only at an explicitly marked capture boundary. */
    final class Replay
    {
        private WintertodtSoloEngine engine;
        private int decisions;
        private long previousSequence;
        int getDecisions() { return decisions; }
        void accept(Record r)
        {
            if (engine == null || r.segmentStart) { engine = restore(r.before); }
            else
            {
                if (r.sequence != previousSequence + 1)
                { throw new IllegalStateException("Missing or out-of-order capture record at tick " + r.snapshot.getObservationTick()); }
                if (r.lifecycle == Lifecycle.RESET) { engine.reset(); }
                else if (r.lifecycle == Lifecycle.SUSPEND) { engine.suspendObservations(); }
            }
            if (!checkpoint(engine).equals(r.before))
            { throw new IllegalStateException("Controller continuity mismatch at tick " + r.snapshot.getObservationTick()); }
            engine.configure(r.pointGoal, r.requestFinish);
            WintertodtObjective actual = engine.decide(r.snapshot, r.settings);
            if (!actual.equals(r.expected) || engine.getPhase() != r.phase)
            { throw new IllegalStateException("Decision mismatch at tick " + r.snapshot.getObservationTick()
                + ": expected " + r.expected + " in " + r.phase + ", got " + actual + " in " + engine.getPhase()); }
            decisions++;
            previousSequence = r.sequence;
        }
    }
}

package com.wintertodtautopilot;

import java.util.ArrayDeque;
import java.util.Deque;

/** Observed trend, independent of the mass countdown. Never predicts a recovery deadline. */
final class WintertodtSoloEnergyModel
{
    // Wiki advises avoiding relights around 8%; keep a two-point margin without waiting to 24%.
    static final int RECOVERY_TRIGGER = 10;
    static final int RECOVERY_EXIT = 12;
    enum Trend { UNKNOWN, DRAINING, RECOVERING, STABLE }
    private final Deque<int[]> samples = new ArrayDeque<>();
    private int lastTick = -1;
    private int recoverySince = -1;
    private int consecutiveRecoveryExit;
    private boolean recovering;
    private Trend trend = Trend.UNKNOWN;
    private boolean rapidDrop;

    void reset()
    {
        samples.clear(); lastTick = -1; recoverySince = -1; consecutiveRecoveryExit = 0;
        recovering = false; trend = Trend.UNKNOWN; rapidDrop = false;
    }
    /** Invalidate cadence without granting permission to leave an unfinished recovery. */
    void suspend()
    {
        invalidateTrend(); lastTick = -1; recoverySince = -1;
    }
    void observe(int tick, int energy)
    {
        if (tick < 0 || energy < 0 || energy > 100) { invalidateTrend(); return; }
        if (tick <= lastTick)
        {
            if (tick == lastTick) { return; }
            suspend();
        }
        if (lastTick >= 0 && tick - lastTick > 2) { invalidateTrend(); consecutiveRecoveryExit = 0; }
        lastTick = tick;
        samples.addLast(new int[]{tick, energy});
        while (!samples.isEmpty() && tick - samples.peekFirst()[0] > 17) { samples.removeFirst(); }
        trend = Trend.UNKNOWN; rapidDrop = false;
        if (!samples.isEmpty() && tick - samples.peekFirst()[0] >= 10)
        {
            int delta = energy - samples.peekFirst()[1];
            trend = delta < 0 ? Trend.DRAINING : delta > 0 ? Trend.RECOVERING : Trend.STABLE;
        }
        int recentPeak = energy;
        int previousEnergy = -1;
        for (int[] sample : samples)
        {
            if (tick - sample[0] > 6) { continue; }
            // A recovery increase ends the preceding drain episode.
            recentPeak = previousEnergy >= 0 && sample[1] > previousEnergy
                ? sample[1] : Math.max(recentPeak, sample[1]);
            previousEnergy = sample[1];
        }
        rapidDrop = recentPeak - energy > 2;
        if (energy <= RECOVERY_TRIGGER && !recovering)
        { recovering = true; recoverySince = tick; consecutiveRecoveryExit = 0; }
        if (recovering)
        {
            if (recoverySince < 0) { recoverySince = tick; }
            consecutiveRecoveryExit = energy >= RECOVERY_EXIT ? consecutiveRecoveryExit + 1 : 0;
            if (consecutiveRecoveryExit >= 3 && tick - recoverySince >= 3)
            { recovering = false; recoverySince = -1; consecutiveRecoveryExit = 0; }
        }
    }
    private void invalidateTrend() { samples.clear(); trend = Trend.UNKNOWN; rapidDrop = false; consecutiveRecoveryExit = 0; }
    boolean isRecovering() { return recovering; }
    boolean isRapidDrop() { return rapidDrop; }
    Trend getTrend() { return trend; }
}

package com.wintertodtautopilot;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/** Solo controller. Global evidence gates relighting; carried points never count as earned. */
public final class WintertodtSoloEngine implements WintertodtPlanner
{
    private final WintertodtSoloEnergyModel energy = new WintertodtSoloEnergyModel();
    private final WintertodtSoloSupplyPlan supplies = new WintertodtSoloSupplyPlan();
    @Getter private SoloPhase phase = SoloPhase.PREPARE;
    private SoloPhase lastOperationalPhase = SoloPhase.PREPARE;
    @Getter private String transitionReason = "initial";
    @Getter private boolean finishRequested;
    private boolean finishedRound;
    private boolean sawActive;
    private int pointGoal = 5000;
    private boolean reducingEnergy = true;
    private WorkingCorner route = WorkingCorner.AUTOMATIC;
    private WorkingCorner routeStop = WorkingCorner.AUTOMATIC;
    private ObjectiveType batch;
    private int batchTarget;
    private WorkingCorner home;
    private WorkingCorner finishAnchor = WorkingCorner.AUTOMATIC;
    private WorkingCorner finishSecondary = WorkingCorner.AUTOMATIC;
    private PlannerSettings previousSettings;
    @Getter private boolean awaitingObservations;
    private int lastEarnedPoints = -1;
    private WorkingCorner deferredRoute = WorkingCorner.AUTOMATIC;
    private boolean routeBlocked;
    private WorkingCorner healingDestination = WorkingCorner.AUTOMATIC;
    @Getter private String readiness = "Waiting for observations";
    public String getReserveDetail() { return supplies.detail(); }

    public void configure(int pointGoal, boolean requestFinish)
    {
        this.pointGoal = Math.max(500, Math.min(100000, pointGoal));
        if (requestFinish && !finishedRound) { finishRequested = true; }
    }
    @Override public int getPreparationDoseTarget() { return supplies.getTarget(); }
    public String getEnergyTrend() { return energy.getTrend().name(); }
    @Override public void reset()
    {
        readiness = "Waiting for observations"; healingDestination = WorkingCorner.AUTOMATIC;
        energy.reset(); supplies.reset(); phase = SoloPhase.PREPARE; transitionReason = "reset";
        lastOperationalPhase = SoloPhase.PREPARE;
        finishRequested = false; finishedRound = false; sawActive = false; reducingEnergy = true;
        route = WorkingCorner.AUTOMATIC; batch = null; batchTarget = 0; home = null; previousSettings = null;
        routeStop = WorkingCorner.AUTOMATIC;
        finishAnchor = WorkingCorner.AUTOMATIC; finishSecondary = WorkingCorner.AUTOMATIC;
        awaitingObservations = false; lastEarnedPoints = -1;
        deferredRoute = WorkingCorner.AUTOMATIC; routeBlocked = false;
    }

    /** Scene handles and cadence are disposable; encounter intent is not. */
    public void suspendObservations()
    {
        energy.suspend(); supplies.suspend(); healingDestination = WorkingCorner.AUTOMATIC;
        awaitingObservations = sawActive || finishRequested;
        if (awaitingObservations) { phase = SoloPhase.REASSESS; transitionReason = "solo_reacquiring"; }
    }

    String batchStage() { return batch == null ? "NONE" : batch.name(); }
    int batchTarget() { return batchTarget; }
    boolean recovering() { return energy.isRecovering(); }

    @Override public WintertodtObjective decide(WintertodtSnapshot s, PlannerSettings settings)
    {
        supplies.observe(s, settings);
        WintertodtObjective o = decideNext(s, settings);
        readiness = supplies.readiness(s, o);
        healingDestination = "solo_points_heal".equals(o.getReason()) || "solo_healing_pending".equals(o.getReason())
            ? o.getDestination() : WorkingCorner.AUTOMATIC;
        SoloAdvice.Reason why = null;
        String reason = o.getReason();
        if (deferredRoute != WorkingCorner.AUTOMATIC && (o.getType() == ObjectiveType.LIGHT
            || o.getType() == ObjectiveType.REPAIR || o.getType() == ObjectiveType.HEAL_PYROMANCER))
        {
            return o.withSoloAdvice(new SoloAdvice(SoloAdvice.Reason.ON_THE_WAY, pointGoal, s.getPoints(),
                s.getWintertodtEnergy(), s.observedGlobalLitBraziers(), finishRequested, deferredRoute));
        }
        if (reason.startsWith("solo_recovery")) { why = SoloAdvice.Reason.RECOVERY; }
        else if (reason.equals("solo_remote_lit") || reason.equals("solo_remote_feed")) { why = SoloAdvice.Reason.REMOTE_FIRE; }
        else if (reason.equals("solo_goal_feed")) { why = SoloAdvice.Reason.GOAL_FEED; }
        else if (phase == SoloPhase.FINISH && (reason.equals("solo_finish_feed") || reason.equals("solo_finish_drain")
            || reason.equals("solo_light") || reason.equals("solo_repair") || reason.equals("solo_heal") || reason.equals("solo_observe_corner")))
        { why = SoloAdvice.Reason.FINISH; }
        else if (phase == SoloPhase.REDUCE_ENERGY && (reason.equals("solo_light") || reason.equals("solo_repair") || reason.equals("solo_heal")))
        { why = SoloAdvice.Reason.OPENING; }
        else if (phase == SoloPhase.SUSTAIN && (reason.equals("solo_light") || reason.equals("solo_repair")))
        { why = SoloAdvice.Reason.LOCAL_MAINTENANCE; }
        if (o.getSoloAdvice() != null) { return o; }
        return why == null ? o : o.withSoloAdvice(new SoloAdvice(why, pointGoal, s.getPoints(), s.getWintertodtEnergy(), s.observedGlobalLitBraziers(),
            finishRequested, WorkingCorner.AUTOMATIC));
    }

    private WintertodtObjective decideNext(WintertodtSnapshot s, PlannerSettings settings)
    {
        deferredRoute = WorkingCorner.AUTOMATIC; routeBlocked = false;
        WorkingCorner selected = s.getWorkingCorner() == WorkingCorner.AUTOMATIC
            ? s.getPlayerLocation() == null ? WorkingCorner.SOUTHWEST : WorkingCorner.nearest(s.getPlayerLocation())
            : s.getWorkingCorner();
        if (previousSettings != null && (settings.getStrategy() != previousSettings.getStrategy()
            || settings.getFletchMode() != previousSettings.getFletchMode()))
        { batch = null; batchTarget = 0; healingDestination = WorkingCorner.AUTOMATIC; }
        if (previousSettings != null && settings.getSoloEffort() != previousSettings.getSoloEffort())
        { healingDestination = WorkingCorner.AUTOMATIC; route = WorkingCorner.AUTOMATIC; routeStop = WorkingCorner.AUTOMATIC; finishAnchor = WorkingCorner.AUTOMATIC; finishSecondary = WorkingCorner.AUTOMATIC; }
        previousSettings = settings;
        // Automatic working-corner changes must not discard an opening/finish destination mid-walk.
        if (home != selected) { home = selected; batch = null; }
        // Only explicit completion/countdown evidence ends a session. A missing HUD is not a new round.
        if (s.getRoundState() == RoundState.COMPLETE
            || sawActive && s.getRoundState() == RoundState.COUNTDOWN && s.getSecondsToStart() > 0)
        {
            finishedRound = true; finishRequested = false; sawActive = false;
            reducingEnergy = true; energy.reset(); supplies.nextRound(); batch = null; route = WorkingCorner.AUTOMATIC;
            routeStop = WorkingCorner.AUTOMATIC;
            batchTarget = 0; awaitingObservations = false; lastEarnedPoints = -1;
            finishAnchor = WorkingCorner.AUTOMATIC; finishSecondary = WorkingCorner.AUTOMATIC;
        }
        if (s.active() && finishedRound)
        {
            finishedRound = false; finishRequested = false;
        }
        // Observe low energy even when warmth temporarily preempts the productive loop.
        if (s.active())
        {
            sawActive = true;
            energy.observe(s.getObservationTick(), s.getWintertodtEnergy());
            if (s.getPoints() >= 0) { lastEarnedPoints = Math.max(lastEarnedPoints, s.getPoints()); }
        }
        WintertodtObjective safety = WintertodtSafety.objective(s, settings);
        if (safety != null) { return safety; }
        WintertodtObjective missing = WintertodtSafety.missingSupplies(s);
        if (missing != null) { setPhase(SoloPhase.REASSESS, "supplies_unobserved"); return missing; }
        if (!s.active())
        {
            if (s.getRoundState() == RoundState.OUTSIDE) { return waitFor("Waiting for Wintertodt", "outside"); }
            if (s.getRoundState() == RoundState.LOBBY)
            { return action(ObjectiveType.ENTER, "Enter the Wintertodt prison", "lobby", TargetKind.DOOR, home, 0, false); }
            if (s.getRoundState() == RoundState.COMPLETE)
            { setPhase(SoloPhase.PREPARE, "round_complete"); return action(ObjectiveType.ROUND_COMPLETE, "Round complete", "round_complete", TargetKind.NONE, home, 0, false); }
            if (sawActive && s.getSecondsToStart() <= 0)
            { awaitingObservations = true; setPhase(SoloPhase.REASSESS, "solo_hud_missing"); return waitFor("Waiting for current round observations", "solo_hud_missing"); }
            setPhase(SoloPhase.PREPARE, "solo_prepare");
            WintertodtObjective prep = supplies.prepare(s, settings, phase);
            return prep != null ? prep : action(ObjectiveType.POSITION, "Get ready at the " + home + " brazier",
                "countdown_position", TargetKind.BRAZIER, home, 0, false);
        }
        if (s.getWintertodtEnergy() < 1 || s.getWintertodtEnergy() > 100 || s.getWarmth() < 0 || s.getObservationTick() < 0
            || s.getPoints() < 0 && (!finishRequested || awaitingObservations))
        {
            energy.observe(s.getObservationTick(), -1);
            setPhase(SoloPhase.REASSESS, "solo_signals_unknown");
            return waitFor("Check energy, points and warmth observations", "solo_signals_unknown");
        }
        if (lastEarnedPoints >= 0 && s.getPoints() >= 0 && s.getPoints() < lastEarnedPoints)
        {
            // A disconnected client may have lost the round. Do not carry a finish
            // request into another encounter based on an unverified identity.
            awaitingObservations = true;
            setPhase(SoloPhase.REASSESS, "solo_score_changed");
            return waitFor("Round score changed - check the encounter before continuing", "solo_score_changed");
        }
        awaitingObservations = false;
        boolean finish = finishRequested || s.getPoints() >= pointGoal;
        if (finish) { setPhase(SoloPhase.FINISH, finishRequested ? "solo_finish_requested" : "solo_goal_earned"); }
        else if (energy.isRecovering()) { setPhase(SoloPhase.RECOVER_ENERGY, "solo_energy_low"); }
        else
        {
            if (s.getWintertodtEnergy() <= 28) { reducingEnergy = false; }
            else if (s.getWintertodtEnergy() > 35) { reducingEnergy = true; }
            setPhase(reducingEnergy ? SoloPhase.REDUCE_ENERGY : SoloPhase.SUSTAIN,
                reducingEnergy ? "solo_opening" : "solo_energy_band");
        }
        // Feed promptly on an unexplained rapid drop, without claiming another player is responsible.
        if (!finish && phase != SoloPhase.REDUCE_ENERGY && energy.isRapidDrop() && fuel(s) > 0
            && (!gathering(s, settings) || s.getWintertodtEnergy() <= WintertodtSoloEnergyModel.RECOVERY_TRIGGER))
        {
            WorkingCorner lit = nearestLit(s);
            if (lit != WorkingCorner.AUTOMATIC)
            {
                setPhase(SoloPhase.REASSESS, "solo_rapid_drain");
                return feed(s, lit, "solo_rapid_drain", true);
            }
        }
        // Converting fuel is separate from controlling energy. Feed an already lit home even during recovery.
        if (fuel(s) > 0 && (finish || s.projectedPoints() >= pointGoal))
        {
            WorkingCorner lit = nearestLit(s);
            if (lit != WorkingCorner.AUTOMATIC) { return feed(s, lit, finish ? "solo_finish_feed" : "solo_goal_feed", finish); }
        }
        WintertodtObjective prep = supplies.prepare(s, settings, phase);
        if (prep != null)
        {
            if ("supply_inventory_blocked".equals(prep.getReason()) && fuel(s) > 0 && nearestLit(s) != WorkingCorner.AUTOMATIC)
            { return feed(s, nearestLit(s), "solo_supply_space", false); }
            if ("supply_inventory_blocked".equals(prep.getReason()) && fuel(s) > 0
                && s.isHasHammer() && (s.isHasTinderbox() || s.isHasBrumaTorch()))
            {
                CornerObservation local = s.corner(home);
                if (local != null && local.getPyromancerState() == CornerObservation.PyromancerState.ALIVE)
                {
                    WintertodtObjective maintenance = maintain(s, home, finish);
                    if (maintenance != null)
                    {
                        if ("solo_recovery_wait".equals(maintenance.getReason()))
                        { return waitFor("Make space for potions - leave braziers unlit during recovery", "solo_recovery_space"); }
                        return maintenance;
                    }
                }
            }
            if (phase == SoloPhase.REDUCE_ENERGY) { setPhase(SoloPhase.PREPARE, "solo_prepare"); }
            return prep;
        }
        if (!finish && (phase == SoloPhase.RECOVER_ENERGY
            || s.getWintertodtEnergy() <= WintertodtSoloEnergyModel.RECOVERY_TRIGGER))
        {
            if (!gathering(s, settings) && fuel(s) > 0 && nearestLit(s) != WorkingCorner.AUTOMATIC
                && (batch == ObjectiveType.FEED || s.getBrumaRoots() == 0 && s.getBrumaKindling() > 0 || !settings.fletch(s)))
            { return feed(s, nearestLit(s), "solo_recovery_feed", false); }
            WintertodtObjective healing = pointsHealing(s, settings, true);
            if (healing != null) { return healing; }
            return productive(s, settings, true);
        }
        if (phase == SoloPhase.REDUCE_ENERGY || phase == SoloPhase.FINISH)
        {
            WorkingCorner destination = phase == SoloPhase.FINISH ? finishCorner(s) : maintenanceCorner(s);
            if (destination != WorkingCorner.AUTOMATIC)
            {
                WintertodtObjective maintenance = maintain(s, destination, true);
                if (maintenance != null) { return maintenance; }
            }
            if (routeBlocked) { return waitFor("No observed route to the required brazier", "solo_route_blocked"); }
            if (phase == SoloPhase.FINISH)
            {
                if (fuel(s) > 0 && nearestLit(s) != WorkingCorner.AUTOMATIC)
                { return feed(s, nearestLit(s), "solo_finish_feed", true); }
                return waitFor("Finish requested - maintain drain until the round ends", "solo_finish_drain");
            }
        }
        else
        {
            WintertodtObjective healing = pointsHealing(s, settings, false);
            if (healing != null) { return healing; }
            // An unlit/broken brazier cannot stop woodcutting. Finish gathering
            // before asking the player to run back for maintenance.
            if (gathering(s, settings)) { return productive(s, settings, false); }
            WintertodtObjective maintenance = maintain(s, home, false);
            if (maintenance != null) { return maintenance; }
        }
        return productive(s, settings, false);
    }

    private WintertodtObjective maintain(WintertodtSnapshot s, WorkingCorner destination, boolean multi)
    {
        CornerObservation c = s.corner(destination);
        if (c == null || !c.brazierFresh(s.getObservationTick()) || !c.isBrazierVisible()
            || c.getBrazierState() == BrazierState.UNKNOWN || c.getBrazierState() == BrazierState.UNAVAILABLE)
        { return position(destination, "Move to observe the " + destination + " brazier", "solo_observe_corner"); }
        boolean down = c.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED;
        if (c.getBrazierState() == BrazierState.LIT && !down) { return null; }
        ObjectiveType work = down ? ObjectiveType.HEAL_PYROMANCER
            : c.getBrazierState() == BrazierState.BROKEN ? ObjectiveType.REPAIR : ObjectiveType.LIGHT;
        WintertodtMaintenancePolicy.Verdict permit = WintertodtMaintenancePolicy.evaluate(s, destination, work,
            phase == SoloPhase.FINISH, energy.isRecovering(), multi, home);
        if (permit == WintertodtMaintenancePolicy.Verdict.RECOVERY)
        { return waitFor("Let energy recover - do not restore drain", "solo_recovery_wait"); }
        if (permit == WintertodtMaintenancePolicy.Verdict.COVERAGE)
        {
            setPhase(SoloPhase.REASSESS, "solo_coverage_unknown");
            return waitFor("Check all brazier indicators before restoring drain", "solo_coverage_unknown");
        }
        if (permit == WintertodtMaintenancePolicy.Verdict.REMOTE_FIRE) { return productiveRecovery(s); }
        if (permit == WintertodtMaintenancePolicy.Verdict.UNOBSERVED)
        { return position(destination, "Move closer to observe the " + destination + " pyromancer", "solo_observe_pyromancer"); }
        if (c.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED)
        { return healingPending(s, destination) ? pendingHealing(destination) : heal(s, destination); }
        if (c.getBrazierState() == BrazierState.BROKEN)
        { return action(ObjectiveType.REPAIR, "Repair the " + destination + " brazier", "solo_repair", TargetKind.BRAZIER, destination, 0, false, ItemID.HAMMER); }
        return action(ObjectiveType.LIGHT, "Light the " + destination + " brazier", "solo_light",
            TargetKind.BRAZIER, destination, 0, false, ItemID.TINDERBOX, ItemID.WINT_TORCH, ItemID.WINT_TORCH_OFFHAND);
    }

    private WintertodtObjective heal(WintertodtSnapshot s, WorkingCorner destination)
    {
        if (previousSettings.isIgnoreWarmthSupplies() && s.getRejuvenationDoses() == 0)
        { return supplies.prepareHealing(s); }
        if (!previousSettings.isIgnoreWarmthSupplies() && s.getRejuvenationDoses() <= 1)
        { return waitFor("Keep the last dose for warmth - prepare more potions", "solo_heal_reserve"); }
        return action(ObjectiveType.HEAL_PYROMANCER, "Heal the " + destination + " pyromancer", "solo_heal",
            TargetKind.PYROMANCER, destination, 1, false, s.getPotionItem());
    }
    private boolean gathering(WintertodtSnapshot s, PlannerSettings settings)
    {
        // Batch state survives animation gaps, warmth interruptions and relights.
        int carried = settings.fletch(s) ? s.potentialPointsIfFletched() : s.inventoryPoints();
        return batch == ObjectiveType.CHOP && s.getBrumaRoots() > 0 && fuel(s) < batchTarget && s.getFreeSlots() > 0
            && s.getCurrentActivity() != PlayerActivity.FEEDING && s.getCurrentActivity() != PlayerActivity.FLETCHING
            && s.getPoints() + carried < pointGoal;
    }

    private WintertodtObjective productiveRecovery(WintertodtSnapshot s)
    {
        WorkingCorner lit = nearestLit(s);
        if (!gathering(s, previousSettings) && fuel(s) > 0 && lit != WorkingCorner.AUTOMATIC
            && (batch == ObjectiveType.FEED || s.getBrumaRoots() == 0 && s.getBrumaKindling() > 0 || !previousSettings.fletch(s)))
        { return feed(s, lit, "solo_remote_feed", false); }
        return unlitWork(s, previousSettings, false);
    }
    private WintertodtObjective unlitWork(WintertodtSnapshot s, PlannerSettings settings, boolean recovery)
    {
        boolean fletching = settings.fletch(s);
        if (batch == ObjectiveType.FLETCH && (s.getBrumaRoots() == 0 || !fletching)) { batch = null; }
        int carried = fletching ? s.potentialPointsIfFletched() : s.inventoryPoints();
        int remainingPoints = Math.max(0, pointGoal - s.getPoints() - carried);
        boolean processRoots = s.getBrumaRoots() > 0 && fletching
            && (s.getFreeSlots() == 0 || (s.getBrumaKindling() > 0 && batch != ObjectiveType.CHOP) || remainingPoints == 0
                || batch == ObjectiveType.FLETCH || s.getCurrentActivity() == PlayerActivity.FLETCHING);
        if (processRoots)
        {
            batch = ObjectiveType.FLETCH;
            return fletch(s, recovery ? "solo_recovery_fletch" : "solo_remote_lit");
        }
        if (s.getFreeSlots() > 0 && remainingPoints > 0)
        {
            batch = ObjectiveType.CHOP;
            int unit = fletching ? 25 : 10;
            int count = Math.min(s.getFreeSlots(), (remainingPoints + unit - 1) / unit);
            // Recovery and remote-brazier work share the sustain batch. Carry its
            // total target across the relight so it cannot collapse to one root.
            batchTarget = fuel(s) + count;
            return chop(s, count,
                recovery ? "solo_recovery_chop" : "solo_remote_lit");
        }
        return waitFor(recovery ? "Let energy recover to 12% - do not relight" : "Remote brazier is lit - leave home unlit",
            recovery ? "solo_recovery_wait" : "solo_remote_lit");
    }

    private WintertodtObjective productive(WintertodtSnapshot s, PlannerSettings settings, boolean recovery)
    {
        if (recovery) { return unlitWork(s, settings, true); }
        if (batch == ObjectiveType.FEED && fuel(s) == 0) { batch = null; }
        if (batch == ObjectiveType.FLETCH && (s.getBrumaRoots() == 0 || !settings.fletch(s))) { batch = ObjectiveType.FEED; }
        if (batch == ObjectiveType.CHOP && (fuel(s) >= batchTarget || s.getFreeSlots() == 0))
        { batch = settings.fletch(s) && s.getBrumaRoots() > 0 ? ObjectiveType.FLETCH : ObjectiveType.FEED; }
        if (batch == null)
        {
            if (s.getBrumaKindling() > 0 || fuel(s) > 0 && (s.getFreeSlots() == 0
                || s.getPoints() >= 0 && s.getPoints() + (settings.fletch(s) ? s.potentialPointsIfFletched() : s.inventoryPoints()) >= pointGoal))
            { batch = settings.fletch(s) && s.getBrumaRoots() > 0 ? ObjectiveType.FLETCH : ObjectiveType.FEED; }
            else
            {
                batch = ObjectiveType.CHOP;
                int capacity = fuel(s) + s.getFreeSlots();
                int needed = s.getPoints() < 0 ? capacity : Math.max(1, (pointGoal - s.getPoints() + (settings.fletch(s) ? 24 : 9)) / (settings.fletch(s) ? 25 : 10));
                batchTarget = Math.min(capacity, needed);
            }
        }
        if (batch == ObjectiveType.FLETCH) { return fletch(s, "solo_batch_fletch"); }
        if (batch == ObjectiveType.FEED && fuel(s) > 0) { return feed(s, home, "solo_batch_feed", false); }
        if (s.getFreeSlots() == 0) { return waitFor("Make space for bruma roots", "inventory_blocked"); }
        return chop(s, Math.max(1, batchTarget - fuel(s)), "solo_batch_chop");
    }
    private WintertodtObjective fletch(WintertodtSnapshot s, String reason)
    {
        // Fletching is allowed at roots and while running; only the safe preparation area forbids it.
        if (s.getPlayerLocation() != null && s.getPlayerLocation().getY() < 3988)
        { return position(home, "Leave the preparation area to fletch", "solo_fletch_inside"); }
        return action(ObjectiveType.FLETCH, "Fletch " + s.getBrumaRoots() + " roots", reason,
            TargetKind.NONE, home, s.getBrumaRoots(), false, ItemID.KNIFE, ItemID.FLETCHING_KNIFE, ItemID.WINT_BRUMA_ROOT);
    }
    private WintertodtObjective chop(WintertodtSnapshot s, int count, String reason)
    { return action(ObjectiveType.CHOP, "Chop " + count + " bruma root" + (count == 1 ? "" : "s"), reason, TargetKind.ROOTS, home, count, false); }
    private WintertodtObjective feed(WintertodtSnapshot s, WorkingCorner destination, String reason, boolean urgent)
    {
        // Once a fuel trip starts, finish it instead of returning for a new root
        // as soon as feeding opens the first inventory slot.
        if (!"solo_supply_space".equals(reason)) { batch = ObjectiveType.FEED; }
        return action(ObjectiveType.FEED, "Feed fuel at the " + destination + " brazier", reason,
            TargetKind.BRAZIER, destination, fuel(s), urgent,
            s.getBrumaKindling() > 0 ? ItemID.WINT_BRUMA_KINDLING : ItemID.WINT_BRUMA_ROOT);
    }
    private WintertodtObjective position(WorkingCorner destination, String text, String reason)
    { return action(ObjectiveType.POSITION, text, reason, TargetKind.BRAZIER, destination, 0, false); }
    private WintertodtObjective waitFor(String text, String reason)
    { return action(ObjectiveType.WAIT, text, reason, TargetKind.NONE, home == null ? WorkingCorner.SOUTHWEST : home, 0, false); }
    private WintertodtObjective action(ObjectiveType type, String text, String reason, TargetKind target,
        WorkingCorner destination, int count, boolean urgent, int... items)
    { return new WintertodtObjective(type, text, reason, target, destination, count, urgent, items); }
    private void setPhase(SoloPhase next, String reason)
    {
        phase = next; transitionReason = reason;
        if (next != SoloPhase.REASSESS && next != lastOperationalPhase)
        {
            lastOperationalPhase = next; route = WorkingCorner.AUTOMATIC; routeStop = WorkingCorner.AUTOMATIC;
            if (next != SoloPhase.FINISH)
            { finishAnchor = WorkingCorner.AUTOMATIC; finishSecondary = WorkingCorner.AUTOMATIC; }
        }
    }
    private static int fuel(WintertodtSnapshot s) { return s.getBrumaRoots() + s.getBrumaKindling(); }
    private WorkingCorner nearestLit(WintertodtSnapshot s)
    {
        WorkingCorner result = WorkingCorner.AUTOMATIC;
        int distance = Integer.MAX_VALUE;
        for (CornerObservation c : s.getCorners())
        {
            if (c.getBrazierState() != BrazierState.LIT || !c.isBrazierVisible() || !c.brazierFresh(s.getObservationTick())) { continue; }
            int d = travelCost(s, c.getCorner());
            if (d < distance) { result = c.getCorner(); distance = d; }
        }
        return result;
    }
    private WintertodtObjective pendingHealing(WorkingCorner destination)
    {
        // Pending is not completed: keep the actual NPC outlined during approach and arrival.
        return action(ObjectiveType.WAIT, "Check the requested healing before clicking again", "solo_healing_pending",
            TargetKind.PYROMANCER, destination, 0, false);
    }
    private boolean healingPending(WintertodtSnapshot s, WorkingCorner destination)
    { return s.getActionActivity() == PlayerActivity.HEALING && s.getActionCorner() == destination
        && (s.getActionState() == WintertodtSnapshot.ActionState.REQUESTED || s.getActionState() == WintertodtSnapshot.ActionState.IN_PROGRESS); }
    private WintertodtObjective pointsHealing(WintertodtSnapshot s, PlannerSettings settings, boolean recovery)
    {
        if (settings.getSoloEffort() != SoloEffort.ACTIVE || settings.getStrategy() == WintertodtStrategy.MASS_XP
            || s.getRejuvenationDoses() <= supplies.personalMinimum()
            || gathering(s, settings)) { return null; }
        if (healingPending(s, s.getActionCorner()) && s.getActionCorner() != WorkingCorner.AUTOMATIC
            && WintertodtMaintenancePolicy.evaluate(s, s.getActionCorner(), ObjectiveType.HEAL_PYROMANCER,
                false, recovery || energy.isRecovering(), false, home) == WintertodtMaintenancePolicy.Verdict.ALLOW)
        { return pendingHealing(s.getActionCorner()); }
        // Optional remote healing fits the processing stage, not each newly chopped root.
        boolean roaming = s.getBrumaRoots() > 0 && (batch == ObjectiveType.FLETCH
            || s.getCurrentActivity() == PlayerActivity.FLETCHING || s.getFreeSlots() == 0);
        WorkingCorner target = WorkingCorner.AUTOMATIC;
        int distance = Integer.MAX_VALUE;
        for (CornerObservation c : s.getCorners())
        {
            if (!c.isPyromancerVisible() || !c.pyromancerFresh(s.getObservationTick())
                || !c.healthFresh(s.getObservationTick()) || c.getPyromancerHealthPercent() >= 100
                || c.getPyromancerState() == CornerObservation.PyromancerState.UNKNOWN) { continue; }
            if (WintertodtMaintenancePolicy.evaluate(s, c.getCorner(), ObjectiveType.HEAL_PYROMANCER,
                false, recovery || energy.isRecovering(), false, home) != WintertodtMaintenancePolicy.Verdict.ALLOW) { continue; }
            if (c.getCorner() != home && ((!roaming && c.getCorner() != healingDestination) || s.getRunEnergyPercent() <= 10)) { continue; }
            int d = c.getCorner() == home ? 0 : s.getPlayerLocation() == null ? 100
                : s.getPlayerLocation().distanceTo(c.getCorner().location());
            if (d < distance) { distance = d; target = c.getCorner(); }
        }
        return target == WorkingCorner.AUTOMATIC ? null : action(ObjectiveType.HEAL_PYROMANCER,
            "Heal the " + target + " pyromancer", "solo_points_heal", TargetKind.PYROMANCER, target, 1, false, s.getPotionItem());
    }

    private WorkingCorner finishCorner(WintertodtSnapshot s)
    {
        if (finishAnchor == WorkingCorner.AUTOMATIC)
        {
            finishAnchor = home;
            int best = Integer.MAX_VALUE;
            for (WorkingCorner c : WorkingCorner.values())
            {
                if (c == WorkingCorner.AUTOMATIC || c == finishAnchor
                    || c.location().getX() != finishAnchor.location().getX() && c.location().getY() != finishAnchor.location().getY()) { continue; }
                CornerObservation observation = s.corner(c);
                int distance = travelCost(s, c);
                if (distance == Integer.MAX_VALUE) { continue; }
                if (observation != null && observation.brazierFresh(s.getObservationTick()) && observation.getBrazierState() == BrazierState.LIT)
                { distance -= 1000; }
                if (distance < best) { best = distance; finishSecondary = c; }
            }
        }
        boolean lowRun = previousSettings.getSoloEffort() == SoloEffort.COMFORTABLE || s.getRunEnergyPercent() <= 10;
        WorkingCorner anchor = finishAnchor;
        return chooseMaintenance(s, lowRun ? new WorkingCorner[]{anchor} : new WorkingCorner[]{anchor, finishSecondary});
    }

    private WorkingCorner maintenanceCorner(WintertodtSnapshot s)
    {
        return chooseMaintenance(s, new WorkingCorner[]{WorkingCorner.NORTHWEST, WorkingCorner.NORTHEAST,
            WorkingCorner.SOUTHWEST, WorkingCorner.SOUTHEAST});
    }

    private WorkingCorner chooseMaintenance(WintertodtSnapshot s, WorkingCorner[] allowed)
    {
        boolean keep = java.util.Arrays.asList(allowed).contains(route) && needsMaintenance(s, route)
            && travelCost(s, route) != Integer.MAX_VALUE;
        if (!keep)
        {
            route = WorkingCorner.AUTOMATIC;
            int best = Integer.MAX_VALUE;
            for (WorkingCorner c : allowed)
            {
                if (!needsMaintenance(s, c)) { continue; }
                int cost = travelCost(s, c);
                if (cost == Integer.MAX_VALUE) { routeBlocked = true; continue; }
                int score = cost + serviceCost(s.corner(c));
                if (score < best) { best = score; route = c; }
            }
        }
        if (route == WorkingCorner.AUTOMATIC) { return route; }
        routeBlocked = false;
        if (routeStop != WorkingCorner.AUTOMATIC)
        {
            // Once a useful stop is selected, let the player finish it. Their
            // approach to the pyro can change the shortest onward path mid-walk.
            if (routeStop != route && java.util.Arrays.asList(allowed).contains(routeStop)
                && needsMaintenance(s, routeStop) && travelCost(s, routeStop) != Integer.MAX_VALUE)
            { deferredRoute = route; return routeStop; }
            routeStop = WorkingCorner.AUTOMATIC;
        }
        BrazierRoute intended = s.routeTo(route);
        if (intended == null || intended.getWalkingCost() < 0 || s.observedGlobalLitBraziers() < 0
            || phase != SoloPhase.FINISH && energy.isRecovering()) { return route; }
        WorkingCorner stop = WorkingCorner.AUTOMATIC; int bestStop = Integer.MAX_VALUE;
        for (WorkingCorner c : allowed)
        {
            if (c == route || !actionableMaintenance(s, c)) { continue; }
            BrazierRoute candidate = s.routeTo(c);
            if (candidate == null || candidate.getWalkingCost() < 0 || candidate.getWalkingCost() >= intended.getWalkingCost()
                || candidate.getPath().isEmpty()) { continue; }
            int score = candidate.getWalkingCost() + serviceCost(s.corner(c));
            if (intended.getOnTheWay().contains(c) && score < bestStop) { bestStop = score; stop = c; }
        }
        if (stop != WorkingCorner.AUTOMATIC) { routeStop = stop; deferredRoute = route; return stop; }
        return route;
    }

    private boolean needsMaintenance(WintertodtSnapshot s, WorkingCorner c)
    {
        if (c == WorkingCorner.AUTOMATIC) { return false; }
        CornerObservation o = s.corner(c);
        return o == null || !o.brazierFresh(s.getObservationTick()) || o.getBrazierState() != BrazierState.LIT
            || o.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED;
    }
    private boolean actionableMaintenance(WintertodtSnapshot s, WorkingCorner c)
    {
        CornerObservation o = s.corner(c);
        return needsMaintenance(s, c) && o != null && o.isBrazierVisible() && o.brazierFresh(s.getObservationTick())
            && o.getBrazierState() != BrazierState.UNKNOWN && o.getBrazierState() != BrazierState.UNAVAILABLE
            && o.isPyromancerVisible() && o.pyromancerFresh(s.getObservationTick())
            && o.getPyromancerState() != CornerObservation.PyromancerState.UNKNOWN
            && (o.getPyromancerState() != CornerObservation.PyromancerState.INCAPACITATED || s.getRejuvenationDoses() > 1);
    }
    private int travelCost(WintertodtSnapshot s, WorkingCorner c)
    {
        if (c == WorkingCorner.AUTOMATIC) { return Integer.MAX_VALUE; }
        BrazierRoute observed = s.routeTo(c);
        if (observed != null) { return observed.getWalkingCost() < 0 ? Integer.MAX_VALUE : observed.getWalkingCost(); }
        if (s.getPlayerLocation() == null) { return c == home ? 0 : 100; }
        return Math.abs(s.getPlayerLocation().getX() - c.location().getX())
            + Math.abs(s.getPlayerLocation().getY() - c.location().getY());
    }
    private static int serviceCost(CornerObservation o)
    {
        if (o == null || o.getBrazierState() == BrazierState.UNKNOWN) { return 12; }
        // Relative interaction penalties, not a prediction of server completion times.
        return (o.getBrazierState() == BrazierState.BROKEN ? 8 : o.getBrazierState() == BrazierState.UNLIT ? 4 : 0)
            + (o.getPyromancerState() == CornerObservation.PyromancerState.INCAPACITATED ? 4 : 0);
    }
}

package com.wintertodtautopilot;

/** Bounded diagnostics for the observed portion of a run, never a claim of full-session coverage. */
final class WintertodtSoloRunSummary
{
    private int firstTick = -1, lastTick = -1, observations, minWarmth = 101, earned = -1, switches, recoveries;
    private SoloPhase lastPhase;
    private ObjectiveType lastAction;
    private WorkingCorner lastDestination;

    String observe(WintertodtSnapshot s, WintertodtObjective o, SoloPhase phase)
    {
        if (!s.active())
        {
            if (s.getRoundState() == RoundState.COMPLETE || s.getSecondsToStart() > 0)
            { return end("verified_round_boundary"); }
            return null;
        }
        if (s.getObservationTick() < 0 || s.getObservationTick() == lastTick) { return null; }
        if (firstTick < 0) { firstTick = s.getObservationTick(); }
        lastTick = s.getObservationTick(); observations++;
        if (s.getWarmth() >= 0) { minWarmth = Math.min(minWarmth, s.getWarmth()); }
        earned = Math.max(earned, s.getPoints());
        if (lastAction != null && (lastAction != o.getType() || lastDestination != o.getDestination())) { switches++; }
        if (phase == SoloPhase.RECOVER_ENERGY && lastPhase != SoloPhase.RECOVER_ENERGY) { recoveries++; }
        lastPhase = phase; lastAction = o.getType(); lastDestination = o.getDestination();
        return null;
    }

    String end(String reason)
    {
        String line = observations == 0 ? null : "solo_run_v1 coverage=observed_only end=" + reason
            + " firstTick=" + firstTick + " lastTick=" + lastTick + " observations=" + observations
            + " minWarmth=" + (minWarmth > 100 ? -1 : minWarmth) + " maxEarned=" + earned
            + " actionSwitches=" + switches + " recoveryEntries=" + recoveries;
        reset(); return line;
    }
    void reset()
    {
        firstTick = -1; lastTick = -1; observations = 0; minWarmth = 101; earned = -1; switches = 0; recoveries = 0;
        lastPhase = null; lastAction = null; lastDestination = null;
    }
}

package com.wintertodtautopilot;

import net.runelite.api.gameval.ItemID;

/** A replenished working reserve, never a promise to cover an unlimited Solo session. */
final class WintertodtSoloSupplyPlan
{
    private int target;
    private boolean ignoreWarmthSupplies;
    private void configure(PlannerSettings settings)
    {
        if (ignoreWarmthSupplies != settings.isIgnoreWarmthSupplies())
        { reset(); ignoreWarmthSupplies = settings.isIgnoreWarmthSupplies(); }
    }
    private boolean restocking = true;
    private boolean mixing;
    // Engineering horizons, not an estimate of the remaining round or a survival guarantee.
    private int lastTick = -1, observedTicks, personalUsed, healingUsed;
    private int windowPersonal, windowHealing;
    private int personalRateTarget, healingRateTarget, personalFloor = 2;
    private int lastFiremaking = -1, lastWarmItems = -1;
    private SoloEffort lastEffort;
    private WintertodtStrategy lastStrategy;
    void suspend() { lastTick = -1; observedTicks = 0; windowPersonal = 0; windowHealing = 0; }
    void observe(WintertodtSnapshot s, PlannerSettings settings)
    {
        configure(settings);
        if (ignoreWarmthSupplies) { return; }
        if (s.getFiremakingLevel() != lastFiremaking || s.getWarmClothingCount() != lastWarmItems
            || settings.getSoloEffort() != lastEffort || settings.getStrategy() != lastStrategy)
        {
            suspend(); personalRateTarget = 0; healingRateTarget = 0; personalFloor = 2;
            lastFiremaking = s.getFiremakingLevel(); lastWarmItems = s.getWarmClothingCount();
            lastEffort = settings.getSoloEffort(); lastStrategy = settings.getStrategy();
        }
        int tick = s.getObservationTick();
        if (tick == lastTick) { return; }
        if (!s.active() || !s.isInventoryKnown() || !s.isEquipmentKnown() || s.getWarmth() < 0
            || lastTick < 0 || tick != lastTick + 1)
        { suspend(); lastTick = s.active() && s.isInventoryKnown() && s.isEquipmentKnown() && s.getWarmth() >= 0 ? tick : -1; return; }
        lastTick = tick; observedTicks++;
        int personal = Math.max(0, Math.min(1, s.getPersonalDosesUsed()));
        int healing = Math.max(0, Math.min(1, s.getHealingDosesUsed()));
        personalUsed += personal; healingUsed += healing;
        windowPersonal += personal; windowHealing += healing;
        // Require three minutes of consecutive valid samples and three attributed uses.
        // Unknown losses, missing frames, food and regeneration cannot shrink the baseline.
        if (observedTicks >= 300 && windowPersonal + windowHealing >= 3)
        {
            personalRateTarget = Math.max(personalRateTarget, ceiling(windowPersonal * 500, observedTicks) + 4);
            healingRateTarget = Math.max(healingRateTarget, ceiling(windowHealing * 500, observedTicks) + 2);
            personalFloor = Math.max(personalFloor, Math.min(8, Math.max(2, ceiling(windowPersonal * 100, observedTicks) + 2)));
        }
        if (observedTicks >= 500) { suspend(); lastTick = tick; }
    }
    private static int ceiling(int n, int d) { return (n + d - 1) / d; }
    int personalMinimum() { return ignoreWarmthSupplies ? 0 : personalFloor; }
    private int personalAllowance()
    { return Math.min(40, Math.max(activeHealing() ? 16 : 24, personalRateTarget)); }
    private boolean activeHealing() { return lastEffort == SoloEffort.ACTIVE && lastStrategy != WintertodtStrategy.MASS_XP; }
    private int healingAllowance() { return activeHealing() ? Math.min(40 - personalAllowance(), Math.max(8, healingRateTarget)) : 0; }
    private int reserve(PlannerSettings settings, SoloPhase phase)
    {
        if (phase == SoloPhase.FINISH) { return Math.min(16, Math.max(8, personalFloor + 4)); }
        boolean healing = settings.getSoloEffort() == SoloEffort.ACTIVE && settings.getStrategy() != WintertodtStrategy.MASS_XP;
        int personal = Math.min(40, Math.max(healing ? 16 : 24, personalRateTarget));
        return Math.min(40, personal + (healing ? Math.max(8, healingRateTarget) : 0));
    }
    String detail()
    {
        if (ignoreWarmthSupplies) { return "Warmth supplies ignored; potions only for pyromancer healing"; }
        return "Working allowance: " + personalAllowance() + " warmth + " + healingAllowance() + " healing. "
            + "Keep " + personalMinimum() + "+ personal; observed " + personalUsed + " personal / " + healingUsed + " healing";
    }
    String readiness(WintertodtSnapshot s, WintertodtObjective o)
    {
        if (!s.isInventoryKnown() || !s.isEquipmentKnown()) { return "Waiting for inventory and equipment"; }
        if (o.getType() == ObjectiveType.RESTORE_WARMTH) { return "Restore warmth first"; }
        if ("prepare_tools".equals(o.getReason())) { return "Missing tool"; }
        if ("supply_inventory_blocked".equals(o.getReason()) || "solo_recovery_space".equals(o.getReason())) { return "Make room for supplies"; }
        if (ignoreWarmthSupplies) { return "Warmth supplies ignored"; }
        if (target == 0) { return "Checking encounter and supplies"; }
        if (restocking) { return "Preparing potions: " + s.getRejuvenationDoses() + " / " + target + " doses"; }
        return "Supplies ready: " + s.getRejuvenationDoses() + " doses"
            + (s.getWarmClothingCount() < 0 ? "; clothing unknown" : s.getWarmClothingCount() < 4 ? "; " + s.getWarmClothingCount() + "/4 warm items" : "");
    }
    int getTarget() { return target; }
    void reset()
    {
        ignoreWarmthSupplies = false;
        target = 0; restocking = true; mixing = false; suspend(); personalUsed = 0; healingUsed = 0;
        personalRateTarget = 0; healingRateTarget = 0; personalFloor = 2;
        lastFiremaking = -1; lastWarmItems = -1; lastEffort = null; lastStrategy = null;
    }
    /** Inventory survives encounter boundaries, including an unfinished preparation batch. */
    void nextRound() { suspend(); if (!restocking && target > 0) { target = 24; } }

    WintertodtObjective prepare(WintertodtSnapshot s, PlannerSettings settings, SoloPhase phase)
    {
        configure(settings);
        TargetKind tool = phase != SoloPhase.FINISH && !s.isHasAxe() ? TargetKind.AXE_CRATE : !s.isHasHammer() ? TargetKind.HAMMER_CRATE
            : phase != SoloPhase.FINISH && WintertodtGuidance.needsKnife(settings) && !s.isHasKnife() ? TargetKind.KNIFE_CRATE
            : !s.isHasTinderbox() && !s.isHasBrumaTorch() ? TargetKind.TINDERBOX_CRATE : TargetKind.NONE;
        if (tool != TargetKind.NONE)
        {
            if (s.getFreeSlots() == 0) { return blocked("tools"); }
            return new WintertodtObjective(ObjectiveType.GET_TOOL, WintertodtGuidance.supplyInstruction(tool, 1),
                "prepare_tools", tool, 1, false);
        }
        if (ignoreWarmthSupplies) { target = 0; restocking = false; return null; }
        int reserve = reserve(settings, phase);
        int restockAt = phase != SoloPhase.FINISH && settings.getStrategy() != WintertodtStrategy.MASS_XP ? 8 : 4;
        restockAt = Math.max(restockAt, Math.min(12, personalFloor + 2));
        boolean carryingFuel = s.getBrumaRoots() + s.getBrumaKindling() > 0;
        boolean finishFuelFirst = s.active() && carryingFuel && s.getRejuvenationDoses() > 1;
        if (target == 0)
        {
            target = reserve;
            // Enabling mid-round with usable supplies must not force an opening
            // top-up merely because the reserve is below six full bottles.
            if (s.active() && (s.getRejuvenationDoses() >= restockAt || finishFuelFirst))
            { restocking = false; }
        }
        if (!restocking && s.getRejuvenationDoses() < restockAt)
        {
            // Defer a new trip until the fuel batch is fed. Once ingredients are
            // requested, complete that trip; the last personal dose cannot wait.
            if (finishFuelFirst) { return null; }
            restocking = true; target = reserve;
        }
        if (phase == SoloPhase.FINISH) { target = Math.min(target, reserve); }
        else if (!restocking) { target = reserve; }
        if (s.getRejuvenationDoses() >= target) { restocking = false; mixing = false; }
        if (!restocking) { return null; }
        return ingredients(s, Math.max(1, (target - s.getRejuvenationDoses() + 3) / 4));
    }
    WintertodtObjective prepareHealing(WintertodtSnapshot s) { return ingredients(s, 1); }

    private WintertodtObjective ingredients(WintertodtSnapshot s, int bottles)
    {
        int vials = s.getUnfinishedPotionCount(), herbs = s.getBrumaHerbCount(), free = s.getFreeSlots();
        int pairs = Math.min(vials, herbs);
        // Collect a complete feasible batch. Existing ingredients occupy slots;
        // a new pair needs two slots until mixing turns it into one bottle.
        int batch = Math.min(bottles, Math.min((vials + herbs + free) / 2,
            Math.min(vials + free, herbs + free)));
        if (pairs > 0 && (mixing || batch > 0 && vials >= batch && herbs >= batch))
        {
            mixing = true;
            int count = Math.min(bottles, pairs);
            return new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
                s.isCanMixPotion() ? "Mix " + count + " potion" + (count == 1 ? "" : "s")
                    : WintertodtGuidance.supplyInstruction(TargetKind.BREWMA, count),
                "mix_rejuvenation", s.isCanMixPotion() ? TargetKind.NONE : TargetKind.BREWMA,
                count, false, ItemID.WINT_HERB, ItemID.WINT_VIAL);
        }
        mixing = false;
        if (batch <= 0) { return blocked("potion ingredients"); }
        boolean vial = vials < batch;
        int count = vial ? batch - vials : batch - herbs;
        TargetKind target = vial ? TargetKind.POTION_CRATE : TargetKind.HERBS;
        return new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
            WintertodtGuidance.supplyInstruction(target, count), "solo_restock", target, count, false);
    }
    private WintertodtObjective blocked(String resource)
    {
        return new WintertodtObjective(ObjectiveType.WAIT, "Make space for " + resource,
            "supply_inventory_blocked", TargetKind.NONE, 0, false);
    }
}

package com.wintertodtautopilot;

import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;

@Singleton
public class WintertodtStateTracker
{
    @Inject private Client client;
    @Inject private WintertodtInventoryTracker inventory;
    @Inject private WintertodtObjectTracker objects;
    @Inject private WintertodtNpcTracker npcs;
    @Inject private WintertodtRoundTracker rounds;
    private final WintertodtCornerTracker corners = new WintertodtCornerTracker();
    private final WintertodtActionTracker actions = new WintertodtActionTracker();
    private PlayerActivity activity = PlayerActivity.IDLE;
    private int lastActionTick = -100;
    private int interruptedAt = -100;
    private boolean interrupted;
    private int warmthRequestedAt = -1;
    private int warmthRequestedItem = -1;
    private WorldPoint clickedCorner;
    private Boolean canMixPotion;
    private WintertodtSnapshot previous = WintertodtSnapshot.builder().build();

    public WintertodtSnapshot snapshot(WorkingCorner configured)
    {
        Player player = client.getLocalPlayer();
        if (player == null || player.getWorldLocation().getRegionID() != WintertodtConstants.REGION)
        {
            reset();
            return previous;
        }
        int tick = client.getTickCount();
        WorldPoint location = player.getWorldLocation();
        WorkingCorner corner = objects.select(location, configured, clickedCorner);
        clickedCorner = null;
        if (canMixPotion == null) { canMixPotion = Quest.DRUIDIC_RITUAL.getState(client) == QuestState.FINISHED; }
        WintertodtSnapshot.WintertodtSnapshotBuilder b = WintertodtSnapshot.builder().playerLocation(location)
            .workingCorner(corner).localBrazierState(objects.brazier(location))
            .brazierDistance(objects.brazierDistance(player))
            .canMixPotion(canMixPotion).firemakingLevel(client.getRealSkillLevel(Skill.FIREMAKING));
        int runEnergy = client.getEnergy();
        b.runEnergyPercent(runEnergy >= 0 && runEnergy <= 10000 ? runEnergy / 100 : -1);
        inventory.fill(b);
        // Region 6462 includes the safe preparation area INSIDE the Doors of Dinh.
        // Do not mistake that area for an outside lobby when joining mid-round.
        rounds.fill(b, true, objects.litCount());
        WintertodtSnapshot partial = b.build();
        boolean boundary = partial.active() != previous.active();
        if (boundary)
        {
            actions.reset();
            activity = PlayerActivity.IDLE;
            interrupted = false;
            lastActionTick = tick;
            warmthRequestedAt = -1;
        }
        if (boundary) { corners.reset(); }
        b.observationTick(tick).corners(corners.observe(tick, objects, npcs, partial.active() ? client : null));
        int rawWarmth = client.getVarbitValue(VarbitID.WINT_WARMTH);
        int warmth = rawWarmth >= 0 && rawWarmth <= 1000 && (partial.active() || rawWarmth > 0) ? rawWarmth / 10 : -1;
        NPC pyro = npcs.target(TargetKind.PYROMANCER, corner.location());
        b.warmth(warmth).rawWarmth(rawWarmth).localPyromancerKnown(pyro != null)
            .localPyromancerIncapacitated(pyro != null && WintertodtNpcTracker.id(pyro) == NpcID.WINT_WIZARD_DOWN);
        boolean moving = previous.getPlayerLocation() != null && !location.equals(previous.getPlayerLocation());
        PlayerActivity animation = WintertodtConstants.activity(player.getAnimation());
        if (tick - interruptedAt > 1 && animation != PlayerActivity.IDLE) { setActivity(animation); }
        boolean consumedRequestedItem = warmthRequestedAt >= 0 && inventory.quantityDecreased(warmthRequestedItem);
        boolean bagChanged = inventory.changed();
        if (activity == PlayerActivity.RESTORING_WARMTH) { activity = PlayerActivity.IDLE; }
        WintertodtSnapshot.WarmthAction warmthAction = WintertodtSnapshot.WarmthAction.NONE;
        if (warmthRequestedAt >= 0)
        {
            warmthAction = tick >= warmthRequestedAt && tick - warmthRequestedAt <= 1
                ? WintertodtSnapshot.WarmthAction.REQUESTED : WintertodtSnapshot.WarmthAction.UNCONFIRMED;
        }
        if (!boundary && partial.active() && partial.isInventoryKnown() && previous.isInventoryKnown())
        {
            if (partial.getBrumaRoots() > previous.getBrumaRoots()) { setActivity(PlayerActivity.CHOPPING); }
            else if (partial.getBrumaKindling() > previous.getBrumaKindling()
                && partial.getBrumaRoots() < previous.getBrumaRoots()) { setActivity(PlayerActivity.FLETCHING); }
            else if (partial.getPoints() > previous.getPoints()
                && partial.getBrumaRoots() + partial.getBrumaKindling() < previous.getBrumaRoots() + previous.getBrumaKindling())
            { setActivity(PlayerActivity.FEEDING); }
            if (partial.getRejuvenationDoses() > previous.getRejuvenationDoses()
                && partial.getUnfinishedPotionCount() < previous.getUnfinishedPotionCount()) { setActivity(PlayerActivity.MAKING_POTION); }
            boolean consumed = partial.getRejuvenationDoses() < previous.getRejuvenationDoses()
                || consumedRequestedItem;
            // Inventory change alone also covers healing a pyro or obtaining a root.
            // Only a consumption signal together with a real warmth rise confirms restoration.
            if (warmthAction == WintertodtSnapshot.WarmthAction.REQUESTED
                && previous.getWarmth() >= 0 && warmth > previous.getWarmth() && consumed && bagChanged)
            {
                setActivity(PlayerActivity.RESTORING_WARMTH);
                warmthAction = WintertodtSnapshot.WarmthAction.CONFIRMED;
                warmthRequestedAt = -1;
            }
        }
        if (moving) { lastActionTick = tick; }
        if (activity == PlayerActivity.FLETCHING && partial.getBrumaRoots() == 0
            || activity == PlayerActivity.FEEDING && partial.getBrumaRoots() + partial.getBrumaKindling() == 0
            || tick - lastActionTick >= 5)
        {
            activity = PlayerActivity.IDLE;
        }
        Actor interaction = player.getInteracting();
        boolean idle = !moving && activity == PlayerActivity.IDLE && interaction == null && tick - lastActionTick >= 5;
        b.warmthAction(warmthAction).currentActivity(moving ? PlayerActivity.MOVING : activity).playerIdle(idle).interrupted(interrupted)
            .inactiveTicks(Math.max(0, tick - lastActionTick))
            .interaction(interaction == null || interaction.getName() == null ? "None" : interaction.getName());
        WintertodtSnapshot observed = actions.observe(previous, b.build(), animation);
        if (observed.getActionActivity() == PlayerActivity.HEALING && observed.getActionCorner() != WorkingCorner.AUTOMATIC
            && observed.isInventoryKnown() && previous.isInventoryKnown()
            && observed.getRejuvenationDoses() < previous.getRejuvenationDoses())
        {
            WorkingCorner healed = observed.getActionCorner();
            corners.invalidateHealth(healed);
            java.util.List<CornerObservation> updated = new java.util.ArrayList<>();
            for (CornerObservation c : observed.getCorners())
            {
                updated.add(c.getCorner() != healed ? c : new CornerObservation(c.getCorner(), c.getBrazierState(),
                    c.getPyromancerState(), -1, c.getBrazierSource(), c.getPyromancerSource(), c.getBrazierObservedTick(),
                    c.getPyromancerObservedTick(), c.isBrazierVisible(), c.isPyromancerVisible(), -1));
            }
            observed = observed.toBuilder().clearCorners().corners(updated).build();
        }
        previous = observed;
        return previous;
    }
    public void animation(Actor actor)
    {
        if (actor != client.getLocalPlayer() || previous.getRoundState() == RoundState.OUTSIDE) { return; }
        PlayerActivity observed = WintertodtConstants.activity(actor.getAnimation());
        if (observed != PlayerActivity.IDLE && client.getTickCount() - interruptedAt > 1) { setActivity(observed); }
    }
    private void setActivity(PlayerActivity value)
    {
        activity = value;
        lastActionTick = client.getTickCount();
        interrupted = false;
    }
    public void clicked(MenuOptionClicked event)
    {
        if (previous.getRoundState() == RoundState.OUTSIDE) { return; }
        lastActionTick = client.getTickCount();
        String option = Text.removeTags(event.getMenuOption()).toLowerCase(Locale.ROOT);
        String target = Text.removeTags(event.getMenuTarget()).toLowerCase(Locale.ROOT);
        if (target.contains("bruma root") || target.contains("brazier"))
        {
            MenuAction action = event.getMenuAction();
            if (action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
                || action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION)
            {
                clickedCorner = WorldPoint.fromScene(client.getTopLevelWorldView(), event.getParam0(), event.getParam1(), client.getTopLevelWorldView().getPlane());
            }
        }
        if (option.equals("eat") || option.equals("drink") && target.contains("rejuvenation"))
        { warmthRequestedAt = client.getTickCount(); warmthRequestedItem = event.getItemId(); }
        else { warmthRequestedAt = -1; }
        PlayerActivity requested = PlayerActivity.IDLE;
        WorkingCorner destination = clickedCorner == null ? WorkingCorner.AUTOMATIC : WorkingCorner.nearest(clickedCorner);
        if (option.equals("eat") || option.equals("drink") && target.contains("rejuvenation")) { requested = PlayerActivity.RESTORING_WARMTH; }
        else if (target.contains("pyromancer") && (option.equals("help") || option.equals("use")))
        { requested = PlayerActivity.HEALING; destination = npcs.cornerForIndex(event.getId()); }
        else if (target.contains("brazier"))
        {
            if (option.equals("light")) { requested = PlayerActivity.LIGHTING; }
            else if (option.equals("fix") || option.equals("repair")) { requested = PlayerActivity.REPAIRING; }
            else if (option.equals("feed") || option.equals("use")) { requested = PlayerActivity.FEEDING; }
        }
        else if (target.contains("bruma root") && option.contains("chop")) { requested = PlayerActivity.CHOPPING; }
        else if (target.contains("bruma root") && option.equals("use")) { requested = PlayerActivity.FLETCHING; }
        else if (target.contains("brew'ma") || option.equals("use") && (target.contains("bruma herb") || target.contains("unfinished rejuvenation")))
        { requested = PlayerActivity.MAKING_POTION; }
        actions.request(requested, destination, previous, client.getTickCount());
    }
    public void chat(ChatMessage event)
    {
        if (!previous.active() || event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM) { return; }
        String text = Text.removeTags(event.getMessage());
        if (text.startsWith("You carefully fletch the root")) { setActivity(PlayerActivity.FLETCHING); return; }
        boolean damage = text.startsWith("The cold of") || text.startsWith("The freezing cold attack")
            || text.startsWith("The brazier is broken and shrapnel");
        boolean stopped = text.startsWith("You have run out of bruma roots") || text.startsWith("Your inventory is too full")
            || text.startsWith("The brazier has gone out.");
        if (stopped || damage && activity != PlayerActivity.CHOPPING && activity != PlayerActivity.IDLE)
        {
            activity = PlayerActivity.IDLE;
            interrupted = true;
            interruptedAt = client.getTickCount();
            // Grace period still protects idle emphasis from animation gaps.
            lastActionTick = interruptedAt - 3;
        }
        if (text.startsWith("You fix the brazier") || text.startsWith("You light the brazier"))
        {
            activity = PlayerActivity.IDLE; lastActionTick = client.getTickCount();
        }
    }
    public void reset()
    {
        activity = PlayerActivity.IDLE; lastActionTick = -100; interruptedAt = -100;
        interrupted = false; clickedCorner = null; canMixPotion = null;
        warmthRequestedAt = -1;
        warmthRequestedItem = -1;
        previous = WintertodtSnapshot.builder().build();
        actions.reset(); inventory.reset(); rounds.reset(); objects.resetCorner(); corners.reset();
    }
}

