package com.wintertodtautopilot;

/** A conservative mass-round reserve, not a prediction of every random attack. */
public final class WintertodtSupplyPlan
{
    private WintertodtSupplyPlan() { }
    public static int recommendedPotions(WintertodtSnapshot s, int restoreAt)
    {
        int fm = Math.max(50, Math.min(99, s.getFiremakingLevel()));
        int warm = s.getWarmClothingCount() < 0 ? 2 : Math.min(4, s.getWarmClothingCount());
        // Use three lit braziers for planning a mass round, not the currently unlit start state.
        int coldDamage = Math.max(1, (16 - warm - 6) * 100 / fm);
        double remaining = s.active() && s.getWintertodtEnergy() >= 0 ? s.getWintertodtEnergy() / 100.0 : 1;
        // About 20 ordinary hits over a typical mass round; likelihood falls with energy.
        double ordinary = 20 * remaining * remaining * coldDamage;
        double specials = 2 * coldDamage * remaining;
        double regeneration = (8 + warm) * 4 * remaining;
        int warmth = s.active() && s.getWarmth() >= 0 ? s.getWarmth() : 100;
        double available = Math.max(0, warmth - restoreAt) + s.getFoodCount() * 35;
        int drinkingDoses = (int) Math.ceil(Math.max(0, ordinary + specials - regeneration - available) / 30);
        int doses = drinkingDoses + 1; // One spare dose for the local pyromancer.
        return Math.max(1, Math.min(3, (doses + 3) / 4));
    }
}

package com.wintertodtautopilot;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/** Local equipment-name registry, avoiding guesses from an item's appearance. */
final class WintertodtWarmClothing
{
    private static final Set<String> NAMES = load();
    private WintertodtWarmClothing() { }
    private static Set<String> load()
    {
        Set<String> names = new HashSet<>();
        InputStream stream = WintertodtWarmClothing.class.getResourceAsStream("warm-clothing.txt");
        if (stream == null) { throw new IllegalStateException("Missing warm clothing registry"); }
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
        {
            String line;
            while ((line = reader.readLine()) != null)
            {
                if (!line.isEmpty() && !line.startsWith("#")) { names.add(line); }
            }
        }
        catch (IOException e) { throw new IllegalStateException("Cannot read warm clothing registry", e); }
        return names;
    }
    static boolean isWarm(String name)
    {
        if (name == null) { return false; }
        String normalized = name.toLowerCase(Locale.ROOT).trim();
        if (NAMES.contains(normalized)) { return true; }
        // Charged/empty and trimmed/imbued variants of listed items share warmth behavior.
        normalized = normalized.replaceAll(" \\((t|i|or|empty|uncharged)\\)$", "");
        return NAMES.contains(normalized);
    }
}

package com.wintertodtautopilot;

import net.runelite.api.coords.WorldPoint;

public enum WorkingCorner
{
    AUTOMATIC(0, 0), NORTHWEST(1621, 4016), NORTHEAST(1639, 4016),
    SOUTHWEST(1621, 3998), SOUTHEAST(1639, 3998);
    private final int x, y;
    WorkingCorner(int x, int y) { this.x = x; this.y = y; }
    @Override public String toString()
    {
        String name = name().toLowerCase(java.util.Locale.ROOT);
        return Character.toUpperCase(name.charAt(0)) + name.substring(1);
    }
    public WorldPoint location() { return new WorldPoint(x, y, 0); }
    public static WorkingCorner nearest(WorldPoint at)
    {
        WorkingCorner result = SOUTHWEST;
        int distance = Integer.MAX_VALUE;
        for (WorkingCorner corner : values())
        {
            if (corner == AUTOMATIC) { continue; }
            int d = corner.location().distanceTo(at);
            if (d < distance) { distance = d; result = corner; }
        }
        return result;
    }
}

