public class WintertodtBrazierHudTest
{
    private final Client client = mock(Client.class);
    private Widget widget(int id, int x, int y, int sprite)
    {
        Widget widget = mock(Widget.class);
        when(widget.getBounds()).thenReturn(new Rectangle(x, y, 20, 20));
        when(widget.getSpriteId()).thenReturn(sprite); when(client.getWidget(id)).thenReturn(widget);
        return widget;
    }
    private void hud()
    {
        // Deliberately scramble child order: layout establishes compass direction.
        widget(InterfaceID.WintStatus.BRAZIER1, 100, 200, 1399);
        widget(InterfaceID.WintStatus.BRAZIER2, 200, 100, 1398);
        widget(InterfaceID.WintStatus.BRAZIER3, 100, 100, 1397);
        widget(InterfaceID.WintStatus.BRAZIER4, 200, 200, 1398);
    }
    @Test public void usesNamedCurrentWidgetsAndCompassLayout()
    {
        hud(); Map<WorkingCorner, BrazierState> observed = WintertodtBrazierHud.read(client);
        assertEquals(BrazierState.LIT, observed.get(WorkingCorner.SOUTHWEST));
        assertEquals(BrazierState.BROKEN, observed.get(WorkingCorner.NORTHWEST));
        assertEquals(BrazierState.UNLIT, observed.get(WorkingCorner.NORTHEAST));
        assertEquals(BrazierState.UNLIT, observed.get(WorkingCorner.SOUTHEAST));
    }
    @Test public void unknownSpriteHiddenAndInvalidLayoutsNeverBecomeUnlit()
    {
        hud(); Widget ne = client.getWidget(InterfaceID.WintStatus.BRAZIER2);
        when(ne.getSpriteId()).thenReturn(99999);
        assertEquals(BrazierState.UNKNOWN, WintertodtBrazierHud.read(client).get(WorkingCorner.NORTHEAST));
        when(ne.isHidden()).thenReturn(true); assertTrue(WintertodtBrazierHud.read(client).isEmpty());
        when(ne.isHidden()).thenReturn(false); when(ne.getBounds()).thenReturn(new Rectangle());
        assertTrue(WintertodtBrazierHud.read(client).isEmpty());
        when(ne.getBounds()).thenReturn(new Rectangle(100, 200, 20, 20));
        assertTrue(WintertodtBrazierHud.read(client).isEmpty());
    }
    @Test public void sceneOverridesHudAndConflictInvalidatesRemoteReadings()
    {
        hud(); WintertodtObjectTracker objects = mock(WintertodtObjectTracker.class);
        WintertodtNpcTracker npcs = mock(WintertodtNpcTracker.class);
        when(objects.brazierAt(WorkingCorner.SOUTHWEST)).thenReturn(BrazierState.LIT);
        WintertodtCornerTracker tracker = new WintertodtCornerTracker();
        List<CornerObservation> first = tracker.observe(10, objects, npcs, client);
        WintertodtSnapshot s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(10).corners(first).build();
        assertEquals(1, s.observedGlobalLitBraziers());
        assertEquals(CornerObservation.Source.HUD_WIDGET, s.corner(WorkingCorner.NORTHWEST).getBrazierSource());
        assertFalse(s.corner(WorkingCorner.NORTHWEST).isBrazierVisible());
        when(objects.brazierAt(WorkingCorner.SOUTHWEST)).thenReturn(BrazierState.UNLIT);
        s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(11).corners(tracker.observe(11, objects, npcs, client)).build();
        assertEquals(BrazierState.UNLIT, s.corner(WorkingCorner.SOUTHWEST).getBrazierState());
        assertEquals(BrazierState.UNKNOWN, s.corner(WorkingCorner.NORTHWEST).getBrazierState());
        assertEquals(-1, s.observedGlobalLitBraziers());
        when(client.getWidget(InterfaceID.WintStatus.BRAZIER1).getSpriteId()).thenReturn(1398);
        s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(12).corners(tracker.observe(12, objects, npcs, client)).build();
        assertEquals(0, s.observedGlobalLitBraziers());
    }
    @Test public void disappearingHudDoesNotReuseRemoteState()
    {
        hud(); WintertodtCornerTracker tracker = new WintertodtCornerTracker();
        WintertodtObjectTracker objects = mock(WintertodtObjectTracker.class);
        WintertodtNpcTracker npcs = mock(WintertodtNpcTracker.class);
        tracker.observe(10, objects, npcs, client);
        when(client.getWidget(InterfaceID.WintStatus.BRAZIER1)).thenReturn(null);
        WintertodtSnapshot s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(11).corners(tracker.observe(11, objects, npcs, client)).build();
        assertEquals(BrazierState.UNKNOWN, s.corner(WorkingCorner.NORTHWEST).getBrazierState());
        assertEquals(10, s.corner(WorkingCorner.NORTHWEST).getBrazierObservedTick());
        assertEquals(-1, s.observedGlobalLitBraziers());
    }
}

package com.wintertodtautopilot;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WintertodtBrazierRouteTest
{
    @Test public void oneSearchAgreesWithExistingWalkingSearchAroundWallsAndUnreachableTargets()
    {
        int[][] flags = new int[60][60];
        for (int y = 0; y < 45; y++) { flags[30][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; }
        Map<WorkingCorner, Rectangle> goals = goals();
        Point start = new Point(40, 18);
        Map<WorkingCorner, WintertodtPathfinder.CostedPath> routes = WintertodtPathfinder.findBraziers(flags, start, goals, Collections.emptyList());
        for (Map.Entry<WorkingCorner, Rectangle> e : goals.entrySet())
        {
            Rectangle r = e.getValue();
            List<Point> reference = WintertodtPathfinder.find(flags, start, r.x, r.y, r.x, r.y, true);
            assertEquals(reference.size() - 1, routes.get(e.getKey()).getCost());
            List<Point> path = routes.get(e.getKey()).getPath();
            for (int i = 1; i < path.size(); i++)
            { assertTrue(WintertodtPathfinder.canStep(flags, path.get(i-1).getX(), path.get(i-1).getY(), path.get(i).getX(), path.get(i).getY())); }
        }
        assertTrue(routes.get(WorkingCorner.NORTHWEST).getCost() > routes.get(WorkingCorner.NORTHEAST).getCost());
        for (int y = 0; y < 60; y++) { flags[30][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; }
        routes = WintertodtPathfinder.findBraziers(flags, start, goals, Collections.emptyList());
        assertEquals(-1, routes.get(WorkingCorner.NORTHWEST).getCost());
        assertEquals(-1, routes.get(WorkingCorner.SOUTHWEST).getCost());
    }

    @Test public void weightedNorthernJumpsUseTheSameEligibilityEdgesAsDisplayedPaths()
    {
        int[][] flags = new int[24][32];
        for (int x = 8; x <= 12; x++) { for (int y = 5; y < 32; y++) { flags[x][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; } }
        List<Point> jumps = Arrays.asList(new Point(7, 23), new Point(9, 23), new Point(11, 23), new Point(13, 23));
        Map<WorkingCorner, Rectangle> goals = new EnumMap<>(WorkingCorner.class);
        goals.put(WorkingCorner.NORTHEAST, new Rectangle(14, 23, 1, 1));
        WintertodtPathfinder.CostedPath shortcut = WintertodtPathfinder.findBraziers(flags, new Point(7, 23), goals, jumps).get(WorkingCorner.NORTHEAST);
        assertEquals(12, shortcut.getCost()); assertEquals(jumps, shortcut.getPath());
        WintertodtPathfinder.CostedPath walk = WintertodtPathfinder.findBraziers(flags, new Point(7, 23), goals, Collections.emptyList()).get(WorkingCorner.NORTHEAST);
        assertTrue(walk.getCost() > shortcut.getCost());
        flags[9][23] = 0x1000000;
        assertEquals(walk.getCost(), WintertodtPathfinder.findBraziers(flags, new Point(7, 23), goals, jumps).get(WorkingCorner.NORTHEAST).getCost());
    }

    @Test public void nearbyButWallSeparatedBrazierIsNotAnOnTheWayInteraction()
    {
        int[][] flags = new int[8][10]; flags[3][4] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        List<Point> path = Arrays.asList(new Point(1, 3), new Point(1, 4), new Point(1, 5));
        Rectangle brazier = new Rectangle(3, 4, 1, 1);
        assertTrue(WintertodtPathfinder.passesBrazier(flags, path, brazier));
        for (int y = 0; y < 10; y++) { flags[2][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; }
        assertFalse(WintertodtPathfinder.passesBrazier(flags, path, brazier));
    }

    @Test public void missingOrInvalidSceneGeometryRemainsUnknownRatherThanUnreachable()
    {
        Map<WorkingCorner, Rectangle> targets = new EnumMap<>(WorkingCorner.class);
        targets.put(WorkingCorner.NORTHWEST, new Rectangle(20, 20, 1, 1));
        assertTrue(WintertodtPathfinder.findBraziers(new int[8][8], new Point(1, 1), targets, Collections.emptyList()).isEmpty());
        assertTrue(WintertodtPathfinder.findBraziers(null, new Point(1, 1), targets, Collections.emptyList()).isEmpty());
        assertTrue(WintertodtPathfinder.findBraziers(new int[][]{new int[2], null}, new Point(1, 1), targets, Collections.emptyList()).isEmpty());
    }

    @Test public void navigationWorksWithWalkingLineDisabledAndCacheRespondsToCollisionInvalidation() throws Exception
    {
        Client client = mock(Client.class); WorldView view = mock(WorldView.class);
        Player player = mock(Player.class); CollisionData collision = mock(CollisionData.class);
        WintertodtObjectTracker objects = mock(WintertodtObjectTracker.class);
        when(client.getLocalPlayer()).thenReturn(player); when(client.getTopLevelWorldView()).thenReturn(view);
        when(view.getBaseX()).thenReturn(1600); when(view.getBaseY()).thenReturn(3980);
        when(view.getSizeX()).thenReturn(60); when(view.getSizeY()).thenReturn(60);
        when(view.getCollisionMaps()).thenReturn(new CollisionData[]{collision});
        int[][] flags = new int[60][60]; when(collision.getFlags()).thenReturn(flags);
        when(player.getWorldLocation()).thenReturn(new WorldPoint(1640, 3998, 0));
        LocalPoint location = LocalPoint.fromScene(40, 18, view);
        when(player.getLocalLocation()).thenReturn(location);
        WintertodtPathTracker tracker = new WintertodtPathTracker();
        TrackerTestSupport.inject(tracker, "client", client);
        TrackerTestSupport.inject(tracker, "config", new WintertodtAutopilotConfig() {
            @Override public WintertodtMode mode() { return WintertodtMode.SOLO; }
        });
        WintertodtSnapshot s = WintertodtSoloReliabilityTest.observed(1, 100, 100, 0, BrazierState.LIT).toBuilder()
            .playerLocation(player.getWorldLocation()).build();
        List<BrazierRoute> first = tracker.observeBrazierRoutes(s, objects);
        assertEquals(4, first.size());
        tracker.update(null, null, null, false); // Optional rendering must not throw away navigation evidence.
        assertSame(first, tracker.observeBrazierRoutes(s, objects));
        for (int y = 0; y < 60; y++) { flags[30][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL; }
        tracker.invalidate();
        List<BrazierRoute> second = tracker.observeBrazierRoutes(s, objects);
        assertNotSame(first, second);
        assertEquals(-1, second.stream().filter(r -> r.getDestination() == WorkingCorner.NORTHWEST).findFirst().get().getWalkingCost());
        java.util.List<CornerObservation> observed = new java.util.ArrayList<>();
        for (CornerObservation c : s.getCorners())
        {
            observed.add(c.getCorner() != WorkingCorner.SOUTHEAST ? c : new CornerObservation(c.getCorner(), BrazierState.LIT,
                c.getPyromancerState(), c.getPyromancerHealthPercent(), c.getBrazierSource(), c.getPyromancerSource(),
                c.getBrazierObservedTick(), c.getPyromancerObservedTick(), c.isBrazierVisible(), c.isPyromancerVisible()));
        }
        WintertodtSnapshot routed = s.toBuilder().clearCorners().corners(observed).brazierRoutes(second).build();
        WintertodtObjective next = new WintertodtSoloEngine().decide(routed, WintertodtSoloReliabilityTest.SETTINGS);
        assertEquals(ObjectiveType.LIGHT, next.getType());
        assertEquals(WorkingCorner.NORTHEAST, next.getDestination()); // Actual collision evidence reaches the planner.
        tracker.reset();
        assertNotSame(second, tracker.observeBrazierRoutes(s, objects));
    }

    private Map<WorkingCorner, Rectangle> goals()
    {
        Map<WorkingCorner, Rectangle> result = new EnumMap<>(WorkingCorner.class);
        result.put(WorkingCorner.NORTHWEST, new Rectangle(21, 36, 1, 1));
        result.put(WorkingCorner.NORTHEAST, new Rectangle(39, 36, 1, 1));
        result.put(WorkingCorner.SOUTHWEST, new Rectangle(21, 18, 1, 1));
        result.put(WorkingCorner.SOUTHEAST, new Rectangle(39, 18, 1, 1));
        return result;
    }
}

package com.wintertodtautopilot;

import org.junit.Test;
import static org.junit.Assert.*;
import static com.wintertodtautopilot.WintertodtEffortPolicyTest.*;

public class WintertodtConsumptionReserveTest
{
    private final WintertodtSoloSupplyPlan plan = new WintertodtSoloSupplyPlan();
    private WintertodtSnapshot sample(int tick, int personal, int healing)
    { return scene(tick, 25, 24).toBuilder().personalDosesUsed(personal).healingDosesUsed(healing).build(); }
    @Test public void baselineNeverShrinksFromLowConsumptionOrUnattributedLosses()
    {
        for (int t = 0; t <= 500; t++) { plan.observe(sample(t, 0, 0).toBuilder().rejuvenationDoses(t % 24).build(), COMFORTABLE); }
        plan.prepare(scene(501, 25, 24), COMFORTABLE, SoloPhase.SUSTAIN);
        assertEquals(24, plan.getTarget()); assertEquals(2, plan.personalMinimum());
        assertTrue(plan.detail().contains("0 personal / 0 healing"));
    }
    @Test public void confirmedSustainedConsumptionIncreasesReserveWithinABoundAndProtectsPersonalDoses()
    {
        for (int t = 0; t <= 310; t++) { plan.observe(sample(t, t % 10 == 0 ? 1 : 0, 0), ACTIVE); }
        plan.prepare(scene(311, 25, 24), ACTIVE, SoloPhase.SUSTAIN);
        assertEquals(40, plan.getTarget()); assertEquals(8, plan.personalMinimum());
        assertTrue(plan.detail().contains("31 personal"));
    }
    @Test public void sparseEvidenceAndDuplicatesCannotCalibrateAReserve()
    {
        for (int t = 0; t <= 600; t += 2)
        { plan.observe(sample(t, 1, 1), ACTIVE); plan.observe(sample(t, 1, 1), ACTIVE); }
        plan.prepare(scene(601, 25, 24), ACTIVE, SoloPhase.SUSTAIN);
        assertEquals(24, plan.getTarget()); assertTrue(plan.detail().contains("0 personal / 0 healing"));
    }
    @Test public void missingContainersLoadingAndEquipmentChangesBreakTheCalibrationWindow()
    {
        for (int t = 0; t <= 200; t++) { plan.observe(sample(t, t % 10 == 0 ? 1 : 0, 0), ACTIVE); }
        plan.suspend();
        for (int t = 201; t <= 400; t++) { plan.observe(sample(t, 1, 0), ACTIVE); }
        plan.observe(sample(401, 1, 0).toBuilder().inventoryKnown(false).build(), ACTIVE);
        for (int t = 402; t <= 500; t++) { plan.observe(sample(t, 1, 0).toBuilder().warmClothingCount(4).build(), ACTIVE); }
        plan.prepare(scene(501, 25, 24), ACTIVE, SoloPhase.SUSTAIN);
        assertEquals(24, plan.getTarget());
    }
    @Test public void optionalHealingAllowanceIsIndependentOfPersonalConsumptionAndEffort()
    {
        for (int t = 0; t <= 310; t++) { plan.observe(sample(t, 0, t % 10 == 0 ? 1 : 0), ACTIVE); }
        plan.prepare(scene(311, 25, 24), ACTIVE, SoloPhase.SUSTAIN);
        assertEquals(40, plan.getTarget()); assertEquals(2, plan.personalMinimum());
        plan.observe(sample(312, 0, 0), COMFORTABLE);
        plan.prepare(scene(312, 25, 24), COMFORTABLE, SoloPhase.SUSTAIN);
        assertEquals(24, plan.getTarget()); // Old effort's calibration does not leak into the new preference.
    }
    @Test public void preparationTargetIsLatchedAndFinishDoesNotDemandAFullWorkingReserve()
    {
        plan.prepare(scene(0, 25, 0), ACTIVE, SoloPhase.PREPARE);
        for (int t = 0; t <= 310; t++) { plan.observe(sample(t, 1, 0), ACTIVE); }
        plan.prepare(scene(311, 25, 4), ACTIVE, SoloPhase.PREPARE);
        assertEquals(24, plan.getTarget());
        plan.prepare(scene(312, 25, 24), ACTIVE, SoloPhase.SUSTAIN);
        plan.prepare(scene(313, 25, 24), ACTIVE, SoloPhase.SUSTAIN);
        assertEquals(40, plan.getTarget());
        assertNull(plan.prepare(scene(314, 25, 16), ACTIVE, SoloPhase.FINISH));
        assertTrue(plan.getTarget() <= 16);
    }
    @Test public void readinessDistinguishesUnknownDataMissingToolsAndReusablePartialReserve()
    {
        WintertodtSoloEngine e = new WintertodtSoloEngine();
        e.decide(scene(10, 25, 12).toBuilder().inventoryKnown(false).build(), COMFORTABLE);
        assertTrue(e.getReadiness().contains("Waiting"));
        e.decide(scene(11, 25, 12).toBuilder().hasAxe(false).build(), COMFORTABLE);
        assertEquals("Missing tool", e.getReadiness());
        e.decide(scene(12, 25, 12).toBuilder().warmClothingCount(2).build(), COMFORTABLE);
        assertTrue(e.getReadiness().contains("Supplies ready: 12 doses")); assertTrue(e.getReadiness().contains("2/4 warm items"));
    }
}

package com.wintertodtautopilot;

import java.util.List;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WintertodtCornerTrackerTest
{
    private final WintertodtObjectTracker objects = mock(WintertodtObjectTracker.class);
    private final WintertodtNpcTracker npcs = mock(WintertodtNpcTracker.class);
    private final WintertodtCornerTracker tracker = new WintertodtCornerTracker();

    private CornerObservation corner(List<CornerObservation> observations, WorkingCorner corner)
    {
        return observations.stream().filter(c -> c.getCorner() == corner).findFirst().get();
    }

    @Test public void partialCoverageNeverEstablishesGlobalUnlitState()
    {
        when(objects.brazierAt(WorkingCorner.SOUTHWEST)).thenReturn(BrazierState.UNLIT);
        List<CornerObservation> observations = tracker.observe(10, objects, npcs);
        assertEquals(4, observations.size());
        assertEquals(BrazierState.UNLIT, corner(observations, WorkingCorner.SOUTHWEST).getBrazierState());
        CornerObservation remote = corner(observations, WorkingCorner.NORTHEAST);
        assertEquals(BrazierState.UNKNOWN, remote.getBrazierState());
        assertEquals(-1, remote.getBrazierObservedTick());
        assertFalse(remote.brazierFresh(10));
        assertEquals(-1, WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(10).corners(observations).build().observedGlobalLitBraziers());
    }

    @Test public void losingVisibilityImmediatelyClearsStateAndHistoryExpiresAfterEightTicks()
    {
        when(objects.brazierAt(WorkingCorner.SOUTHWEST)).thenReturn(BrazierState.LIT);
        List<CornerObservation> first = tracker.observe(10, objects, npcs);
        when(objects.brazierAt(WorkingCorner.SOUTHWEST)).thenReturn(BrazierState.UNKNOWN);
        CornerObservation lost = corner(tracker.observe(11, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(BrazierState.UNKNOWN, lost.getBrazierState());
        assertFalse(lost.isBrazierVisible());
        assertEquals(CornerObservation.Source.NONE, lost.getBrazierSource());
        assertEquals(10, lost.getBrazierObservedTick());
        assertTrue(lost.brazierFresh(18));
        assertFalse(lost.brazierFresh(19));
        assertFalse(lost.brazierFresh(9));
        assertEquals(BrazierState.LIT, corner(first, WorkingCorner.SOUTHWEST).getBrazierState());
        tracker.reset();
        assertEquals(-1, corner(tracker.observe(20, objects, npcs), WorkingCorner.SOUTHWEST).getBrazierObservedTick());
    }

    @Test public void globalCountRequiresFourFreshDistinctCorners()
    {
        for (WorkingCorner c : WorkingCorner.values())
        {
            if (c != WorkingCorner.AUTOMATIC) { when(objects.brazierAt(c)).thenReturn(BrazierState.UNLIT); }
        }
        when(objects.brazierAt(WorkingCorner.NORTHEAST)).thenReturn(BrazierState.LIT);
        WintertodtSnapshot snapshot = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(10)
            .corners(tracker.observe(10, objects, npcs)).build();
        assertEquals(1, snapshot.observedGlobalLitBraziers());
        assertEquals(-1, snapshot.toBuilder().observationTick(19).build().observedGlobalLitBraziers());
        when(objects.brazierAt(WorkingCorner.NORTHEAST)).thenReturn(BrazierState.UNLIT);
        assertEquals(0, WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(11)
            .corners(tracker.observe(11, objects, npcs)).build().observedGlobalLitBraziers());
    }

    @Test public void pyromancerHealthAndVisibilityAreIndependentOfBrazier()
    {
        NPC npc = mock(NPC.class); NPCComposition composition = mock(NPCComposition.class);
        when(npc.getTransformedComposition()).thenReturn(composition);
        when(composition.getId()).thenReturn(NpcID.WINT_WIZARD);
        when(npc.getHealthRatio()).thenReturn(3); when(npc.getHealthScale()).thenReturn(4);
        when(npcs.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location())).thenReturn(npc);
        CornerObservation alive = corner(tracker.observe(10, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(75, alive.getPyromancerHealthPercent());
        assertEquals(BrazierState.UNKNOWN, alive.getBrazierState());
        when(npc.getHealthScale()).thenReturn(-1);
        assertEquals(-1, corner(tracker.observe(11, objects, npcs), WorkingCorner.SOUTHWEST).getPyromancerHealthPercent());
        when(composition.getId()).thenReturn(NpcID.WINT_WIZARD_DOWN);
        CornerObservation down = corner(tracker.observe(12, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(CornerObservation.PyromancerState.INCAPACITATED, down.getPyromancerState());
        assertEquals(0, down.getPyromancerHealthPercent());
        when(npcs.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location())).thenReturn(null);
        CornerObservation lost = corner(tracker.observe(13, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(CornerObservation.PyromancerState.UNKNOWN, lost.getPyromancerState());
        assertEquals(-1, lost.getPyromancerHealthPercent());
        assertEquals(12, lost.getPyromancerObservedTick());
        assertFalse(lost.isPyromancerVisible());
        // Tick regression invalidates observations from a previous client timeline.
        assertEquals(-1, corner(tracker.observe(1, objects, npcs), WorkingCorner.SOUTHWEST).getPyromancerObservedTick());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void observationListIsImmutable() { tracker.observe(1, objects, npcs).clear(); }

    @Test public void traceKeepsEarnedAndCarriedSeparateAndLabelsPlannerHonestly()
    {
        WintertodtSnapshot snapshot = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(10).points(400)
            .brumaRoots(3).brumaKindling(2).workingCorner(WorkingCorner.SOUTHWEST)
            .corners(tracker.observe(10, objects, npcs)).build();
        WintertodtObjective objective = new WintertodtObjective(ObjectiveType.LIGHT, "Relight", "brazier_unlit",
            TargetKind.BRAZIER, 0, false);
        String trace = WintertodtObservationTrace.format(snapshot, objective);
        assertTrue(trace.contains("tick=10 planner=MASS soloPhase=NOT_RUNNING"));
        assertTrue(trace.contains("destination=SOUTHWEST action=LIGHT reason=brazier_unlit"));
        assertTrue(trace.contains("earned=400 carried=80"));
        assertTrue(trace.contains("observedGlobalLit=-1"));
        assertTrue(trace.contains("NORTHEAST.brazier=UNKNOWN"));
    }

    @Test public void unchangedCachedHealthExpiresWhileStandingStateRemainsFresh()
    {
        NPC npc = mock(NPC.class); NPCComposition composition = mock(NPCComposition.class);
        when(npc.getTransformedComposition()).thenReturn(composition);
        when(composition.getId()).thenReturn(NpcID.WINT_WIZARD);
        when(npc.getHealthRatio()).thenReturn(3); when(npc.getHealthScale()).thenReturn(4);
        when(npcs.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location())).thenReturn(npc);
        assertTrue(corner(tracker.observe(10, objects, npcs), WorkingCorner.SOUTHWEST).healthFresh(10));
        for (int t = 11; t <= 19; t++) { tracker.observe(t, objects, npcs); }
        CornerObservation stale = corner(tracker.observe(20, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(-1, stale.getPyromancerHealthPercent()); assertFalse(stale.healthFresh(20));
        assertTrue(stale.pyromancerFresh(20));
        assertEquals(CornerObservation.PyromancerState.ALIVE, stale.getPyromancerState());
        when(npc.getHealthRatio()).thenReturn(2);
        CornerObservation updated = corner(tracker.observe(21, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(50, updated.getPyromancerHealthPercent()); assertTrue(updated.healthFresh(21));
    }
    @Test public void replacingTheNpcOrLosingItsHealthDoesNotReusePreviousInjuryEvidence()
    {
        NPC npc = mock(NPC.class), replacement = mock(NPC.class); NPCComposition composition = mock(NPCComposition.class);
        when(composition.getId()).thenReturn(NpcID.WINT_WIZARD);
        for (NPC n : new NPC[]{npc, replacement})
        {
            when(n.getTransformedComposition()).thenReturn(composition);
            when(n.getHealthRatio()).thenReturn(3); when(n.getHealthScale()).thenReturn(4);
        }
        when(npcs.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location())).thenReturn(npc);
        tracker.observe(10, objects, npcs);
        when(npcs.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location())).thenReturn(replacement);
        assertEquals(20, corner(tracker.observe(20, objects, npcs), WorkingCorner.SOUTHWEST).getHealthObservedTick());
        when(replacement.getHealthRatio()).thenReturn(-1);
        CornerObservation missing = corner(tracker.observe(21, objects, npcs), WorkingCorner.SOUTHWEST);
        assertEquals(-1, missing.getPyromancerHealthPercent()); assertFalse(missing.healthFresh(21));
    }

    @Test public void aSpentHealingDoseInvalidatesCachedInjuryUntilNewHealthEvidence()
    {
        NPC npc = mock(NPC.class); NPCComposition composition = mock(NPCComposition.class);
        when(npc.getTransformedComposition()).thenReturn(composition); when(composition.getId()).thenReturn(NpcID.WINT_WIZARD);
        when(npc.getHealthRatio()).thenReturn(2); when(npc.getHealthScale()).thenReturn(4);
        when(npcs.target(TargetKind.PYROMANCER, WorkingCorner.SOUTHWEST.location())).thenReturn(npc);
        tracker.observe(10, objects, npcs); tracker.invalidateHealth(WorkingCorner.SOUTHWEST);
        assertFalse(corner(tracker.observe(11, objects, npcs), WorkingCorner.SOUTHWEST).healthFresh(11));
        when(npc.getHealthRatio()).thenReturn(3);
        assertTrue(corner(tracker.observe(12, objects, npcs), WorkingCorner.SOUTHWEST).healthFresh(12));
    }
}

package com.wintertodtautopilot;

import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtDecisionEngineTest
{
    private WintertodtDecisionEngine engine;
    private PlannerSettings settings;
    @Before public void setup()
    {
        engine = new WintertodtDecisionEngine();
        settings = new PlannerSettings(WintertodtStrategy.MASS_BALANCED, PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 35, 20);
    }
    private WintertodtSnapshot.WintertodtSnapshotBuilder active()
    {
        return WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE).wintertodtEnergy(80).warmth(90).points(0)
            .localBrazierState(BrazierState.LIT).localPyromancerKnown(true)
            .firemakingLevel(99).warmClothingCount(4).rejuvenationDoses(4).potionItem(ItemID.WINT_POTION4)
            .brazierDistance(0).hasHammer(true).hasKnife(true).hasTinderbox(true).hasAxe(true).freeSlots(24).workingCorner(WorkingCorner.SOUTHEAST);
    }
    private WintertodtObjective decide(WintertodtSnapshot.WintertodtSnapshotBuilder s) { return engine.decide(s.build(), settings); }
    @Test public void warmthPreemptsBrokenBrazier()
    {
        WintertodtObjective result = decide(active().warmth(18).warmthItem(ItemID.CAKE).localBrazierState(BrazierState.BROKEN));
        assertEquals(ObjectiveType.RESTORE_WARMTH, result.getType());
        assertTrue(result.isUrgent()); assertTrue(result.getItemIds().contains(ItemID.CAKE));
    }
    @Test public void noWarmthSuppliesRequiresSafeLobby()
    {
        WintertodtObjective result = decide(active().warmth(18));
        assertEquals(TargetKind.DOOR, result.getTarget()); assertTrue(result.isUrgent());
    }
    @Test public void consumingCannotClearWarningBeforeWarmthRecovers()
    {
        assertEquals(ObjectiveType.RESTORE_WARMTH, decide(active().warmth(18).warmthItem(ItemID.CAKE)
            .currentActivity(PlayerActivity.RESTORING_WARMTH)).getType());
    }
    @Test public void brokenBrazierRequiresRepair()
    {
        assertEquals(ObjectiveType.REPAIR, decide(active().localBrazierState(BrazierState.BROKEN)).getType());
    }
    @Test public void missingHammerGuidesToCrate()
    {
        assertEquals(TargetKind.HAMMER_CRATE, decide(active().localBrazierState(BrazierState.BROKEN).hasHammer(false)).getTarget());
    }
    @Test public void imminentRewardsFeedBeforeChoppingOrFletching()
    {
        WintertodtObjective result = decide(active().points(450).brumaKindling(3).wintertodtEnergy(2).endUrgency(EndUrgency.IMMINENT));
        assertEquals(ObjectiveType.FEED, result.getType()); assertTrue(result.isUrgent());
    }
    @Test public void enoughKindlingDoesNotChop()
    {
        settings = new PlannerSettings(WintertodtStrategy.MASS_POINTS, PointGoal.POINTS_1000, FletchMode.AUTOMATIC, 35, 20);
        assertEquals(ObjectiveType.FEED, decide(active().points(700).brumaKindling(12)).getType());
    }
    @Test public void fletchingResumesAfterColdAndRepairAndWarmth()
    {
        WintertodtSnapshot.WintertodtSnapshotBuilder s = active().points(25).brumaRoots(19).freeSlots(5);
        assertEquals(ObjectiveType.FLETCH, decide(s).getType());
        assertEquals(ObjectiveType.FLETCH, decide(s.playerIdle(true).interrupted(true)).getType());
        assertEquals(ObjectiveType.REPAIR, decide(s.localBrazierState(BrazierState.BROKEN)).getType());
        assertEquals(ObjectiveType.FLETCH, decide(s.localBrazierState(BrazierState.LIT)).getType());
        assertEquals(ObjectiveType.RESTORE_WARMTH, decide(s.warmth(30).warmthItem(ItemID.CAKE)).getType());
        assertEquals(ObjectiveType.FLETCH, decide(s.warmth(65)).getType());
    }
    @Test public void fletchingHighlightsEitherKnife()
    {
        WintertodtObjective result = decide(active().points(25).brumaRoots(19).freeSlots(5));
        assertEquals(ObjectiveType.FLETCH, result.getType());
        assertTrue(result.getItemIds().contains(ItemID.KNIFE));
        assertTrue(result.getItemIds().contains(ItemID.FLETCHING_KNIFE));
        assertTrue(result.getItemIds().contains(ItemID.WINT_BRUMA_ROOT));
    }
    @Test public void downPyromancerBeforeRelight()
    {
        WintertodtSnapshot s = active().localBrazierState(BrazierState.UNLIT)
            .localPyromancerIncapacitated(true).rejuvenationDoses(2).potionItem(ItemID.WINT_POTION2)
            .brumaRoots(3).brumaKindling(5).currentActivity(PlayerActivity.FEEDING).build();
        WintertodtObjective heal = engine.decide(s, settings);
