            for (int irrelevant : new int[]{ItemID.WINT_BRUMA_ROOT, ItemID.WINT_BRUMA_KINDLING, ItemID.WINT_VIAL, ItemID.WINT_HERB})
            { assertFalse(WintertodtHighlight.inventoryItem(s, heal, irrelevant)); }
        }
    }

}

package com.wintertodtautopilot;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtEffortPolicyTest
{
    static final PlannerSettings COMFORTABLE = new PlannerSettings(WintertodtStrategy.MASS_POINTS,
        PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 50, 20, SoloEffort.COMFORTABLE);
    static final PlannerSettings ACTIVE = new PlannerSettings(WintertodtStrategy.MASS_POINTS,
        PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 50, 20, SoloEffort.ACTIVE);
    static WintertodtSnapshot scene(int tick, int energy, int doses)
    {
        return WintertodtSoloReliabilityTest.observed(tick, energy, 100, 0, BrazierState.LIT).toBuilder()
            .rejuvenationDoses(doses).runEnergyPercent(100).build();
    }
    static WintertodtSnapshot corner(WintertodtSnapshot s, WorkingCorner target, BrazierState fire,
        CornerObservation.PyromancerState pyro, int health, int healthTick)
    {
        List<CornerObservation> result = new ArrayList<>();
        for (CornerObservation c : s.getCorners())
        {
            result.add(c.getCorner() != target ? c : new CornerObservation(target, fire, pyro, health,
                CornerObservation.Source.DIRECT_SCENE, CornerObservation.Source.DIRECT_SCENE,
                s.getObservationTick(), s.getObservationTick(), true, true, healthTick));
        }
        return s.toBuilder().clearCorners().corners(result).build();
    }
    @Test public void newPreferenceDefaultsToComfortableWithoutChangingSavedStrategyOrGoal()
    {
        WintertodtAutopilotConfig config = new WintertodtAutopilotConfig() {
            public WintertodtMode mode() { return WintertodtMode.SOLO; }
            public SoloStrategy soloStrategy() { return SoloStrategy.FIREMAKING_XP; }
            public int soloPointGoal() { return 13500; }
        };
        assertEquals(SoloEffort.COMFORTABLE, PlannerSettings.from(config).getSoloEffort());
        assertEquals(WintertodtStrategy.MASS_XP, PlannerSettings.from(config).getStrategy());
        assertEquals(13500, config.soloPointGoal());
    }
    @Test public void comfortableSkipsOptionalHealingButStillHealsADownedWorkingPyromancer()
    {
        WintertodtSnapshot hurt = corner(scene(10, 25, 24), WorkingCorner.SOUTHWEST, BrazierState.LIT,
            CornerObservation.PyromancerState.ALIVE, 50, 10).toBuilder().brumaKindling(6).build();
        assertEquals(ObjectiveType.FEED, new WintertodtSoloEngine().decide(hurt, COMFORTABLE).getType());
        assertEquals("solo_points_heal", new WintertodtSoloEngine().decide(hurt, ACTIVE).getReason());
        WintertodtSnapshot down = corner(hurt, WorkingCorner.SOUTHWEST, BrazierState.UNLIT,
            CornerObservation.PyromancerState.INCAPACITATED, 0, 10);
        assertEquals(ObjectiveType.HEAL_PYROMANCER, new WintertodtSoloEngine().decide(down, COMFORTABLE).getType());
    }
    @Test public void comfortableFinishesAtOneStableFireAndActiveUsesOnlyAnAdjacentPair()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine(); engine.configure(5000, true);
        assertEquals("solo_finish_drain", engine.decide(scene(10, 8, 24), COMFORTABLE).getReason());
        WintertodtObjective extra = engine.decide(scene(11, 8, 24), ACTIVE);
        assertEquals(ObjectiveType.LIGHT, extra.getType());
        WorkingCorner second = extra.getDestination(); assertNotEquals(WorkingCorner.SOUTHWEST, second);
        assertTrue(second == WorkingCorner.NORTHWEST || second == WorkingCorner.SOUTHEAST);
        WintertodtSnapshot paired = corner(scene(12, 8, 24), second, BrazierState.LIT,
            CornerObservation.PyromancerState.ALIVE, -1, -1);
        assertEquals("solo_finish_drain", engine.decide(paired, ACTIVE).getReason());
        assertEquals("solo_finish_drain", engine.decide(paired.toBuilder().workingCorner(WorkingCorner.NORTHEAST).build(), ACTIVE).getReason());
    }
    @Test public void unknownAndExhaustedRunNeverAddASecondFinishFire()
    {
        for (int run : new int[]{-1, 0, 10})
        {
            WintertodtSoloEngine e = new WintertodtSoloEngine(); e.configure(5000, true);
            assertEquals("solo_finish_drain", e.decide(scene(10, 8, 24).toBuilder().runEnergyPercent(run).build(), ACTIVE).getReason());
        }
    }
    @Test public void staleInjuryEvidenceCannotTriggerOptionalHealing()
    {
        WintertodtSnapshot stale = corner(scene(20, 25, 24), WorkingCorner.SOUTHWEST, BrazierState.LIT,
            CornerObservation.PyromancerState.ALIVE, 50, 10).toBuilder().brumaKindling(6).build();
        assertEquals(ObjectiveType.FEED, new WintertodtSoloEngine().decide(stale, ACTIVE).getType());
    }
    @Test public void effortChangePreservesTheBatchAndManualFinishStillPreempts()
    {
        WintertodtSoloEngine e = new WintertodtSoloEngine();
        assertEquals(6, e.decide(scene(10, 25, 24), COMFORTABLE).getQuantity());
        assertEquals(5, e.decide(scene(11, 25, 24).toBuilder().brumaRoots(1).freeSlots(5).build(), ACTIVE).getQuantity());
        e.configure(5000, true);
        assertEquals(ObjectiveType.FEED, e.decide(scene(12, 25, 24).toBuilder().brumaRoots(1).freeSlots(5).build(), ACTIVE).getType());
        assertTrue(e.isFinishRequested());
    }
    @Test public void sharedPolicyRejectsEveryDrainRestoringWorkDuringRecovery()
    {
        for (BrazierState fire : new BrazierState[]{BrazierState.LIT, BrazierState.UNLIT, BrazierState.BROKEN})
        {
            WintertodtSnapshot s = corner(scene(10, 11, 24), WorkingCorner.SOUTHWEST, fire,
                CornerObservation.PyromancerState.INCAPACITATED, 0, 10);
            for (ObjectiveType work : new ObjectiveType[]{ObjectiveType.LIGHT, ObjectiveType.REPAIR, ObjectiveType.HEAL_PYROMANCER})
            {
                WintertodtMaintenancePolicy.Verdict result = WintertodtMaintenancePolicy.evaluate(s, WorkingCorner.SOUTHWEST,
                    work, false, true, false, WorkingCorner.SOUTHWEST);
                assertEquals(fire != BrazierState.LIT && work == ObjectiveType.HEAL_PYROMANCER
                    ? WintertodtMaintenancePolicy.Verdict.ALLOW : WintertodtMaintenancePolicy.Verdict.RECOVERY, result);
            }
        }
    }
    @Test public void finishingDoesNotBypassUnknownCoverageAndSustainDoesNotAddRemoteDrain()
    {
        WintertodtSnapshot s = scene(10, 8, 24).toBuilder().clearCorners()
            .corner(scene(10, 8, 24).corner(WorkingCorner.SOUTHWEST)).build();
        assertEquals(WintertodtMaintenancePolicy.Verdict.COVERAGE, WintertodtMaintenancePolicy.evaluate(s,
            WorkingCorner.SOUTHWEST, ObjectiveType.LIGHT, true, true, true, WorkingCorner.SOUTHWEST));
        s = corner(scene(10, 25, 24), WorkingCorner.NORTHWEST, BrazierState.LIT, CornerObservation.PyromancerState.ALIVE, -1, -1);
        s = corner(s, WorkingCorner.SOUTHWEST, BrazierState.LIT, CornerObservation.PyromancerState.INCAPACITATED, 0, 10);
        assertEquals(WintertodtMaintenancePolicy.Verdict.REMOTE_FIRE, WintertodtMaintenancePolicy.evaluate(s,
            WorkingCorner.SOUTHWEST, ObjectiveType.HEAL_PYROMANCER, false, false, false, WorkingCorner.SOUTHWEST));
    }
    @Test public void warmthStillPreemptsBothEffortPreferencesAndFinishing()
    {
        for (PlannerSettings settings : new PlannerSettings[]{COMFORTABLE, ACTIVE})
        {
            WintertodtSoloEngine e = new WintertodtSoloEngine(); e.configure(5000, true);
            assertEquals(ObjectiveType.RESTORE_WARMTH, e.decide(scene(10, 8, 24).toBuilder().warmth(10).build(), settings).getType());
        }
    }

    @Test public void aPendingHealingRequestWaitsForItsResultAndExpiresWithoutPretendingSuccess()
    {
        WintertodtSnapshot down = corner(scene(10, 25, 24), WorkingCorner.SOUTHWEST, BrazierState.UNLIT,
            CornerObservation.PyromancerState.INCAPACITATED, 0, 10).toBuilder()
            .actionActivity(PlayerActivity.HEALING).actionCorner(WorkingCorner.SOUTHWEST)
            .actionState(WintertodtSnapshot.ActionState.REQUESTED).build();
        assertEquals("solo_healing_pending", new WintertodtSoloEngine().decide(down, COMFORTABLE).getReason());
        assertEquals(ObjectiveType.HEAL_PYROMANCER, new WintertodtSoloEngine().decide(down.toBuilder()
            .actionState(WintertodtSnapshot.ActionState.UNCONFIRMED).build(), COMFORTABLE).getType());
        WintertodtSnapshot recovering = down.toBuilder().wintertodtEnergy(9).build();
        assertNotEquals(ObjectiveType.HEAL_PYROMANCER, new WintertodtSoloEngine().decide(recovering, COMFORTABLE).getType());
    }
    @Test public void missingTargetEvidenceNeverPermitsMaintenanceOrOptionalHealing()
    {
        WintertodtSnapshot unknown = corner(scene(10, 25, 24), WorkingCorner.SOUTHWEST, BrazierState.UNKNOWN,
            CornerObservation.PyromancerState.ALIVE, 50, 10);
        for (ObjectiveType action : new ObjectiveType[]{ObjectiveType.LIGHT, ObjectiveType.REPAIR, ObjectiveType.HEAL_PYROMANCER})
        {
            assertEquals(WintertodtMaintenancePolicy.Verdict.UNOBSERVED, WintertodtMaintenancePolicy.evaluate(unknown,
                WorkingCorner.SOUTHWEST, action, false, false, false, WorkingCorner.SOUTHWEST));
        }
    }
}

package com.wintertodtautopilot;

import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtFinishPlanTest
{
    private static WintertodtSnapshot.WintertodtSnapshotBuilder timed(int budget)
    {
        return WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE).brazierDistance(0).roundBudgetSeconds(budget);
    }

    @Test public void fletchingKnifeFitsMoreFletchesBeforeTheRoundEnds()
    {
        // 56s budget - 1.2s travel - 20 feeds * 1.8s leaves 18.8s to fletch.
        WintertodtSnapshot.WintertodtSnapshotBuilder s = timed(56).brumaRoots(20);
        assertEquals(10, WintertodtFinishPlan.fletchCapacity(s.build()));
        // The first root still takes 1.8s; each later root takes 1.2s.
        assertEquals(15, WintertodtFinishPlan.fletchCapacity(s.hasFletchingKnife(true).build()));
    }

    @Test public void fletchingKnifeFitsMoreRootsOnlyWhenFletching()
    {
        WintertodtSnapshot.WintertodtSnapshotBuilder s = timed(100);
        assertEquals(13, WintertodtFinishPlan.additionalRoots(s.build(), true));
        assertEquals(14, WintertodtFinishPlan.additionalRoots(s.hasFletchingKnife(true).build(), true));
        assertEquals(WintertodtFinishPlan.additionalRoots(s.hasFletchingKnife(false).build(), false),
            WintertodtFinishPlan.additionalRoots(s.hasFletchingKnife(true).build(), false));
    }
    @Test public void firstRootStillNeedsThreeTicksWithTheFletchingKnife()
    {
        // 5 seconds minus 1.8 walking and 1.8 feeding leaves only 1.4 for the first fletch.
        WintertodtSnapshot s = timed(5).brazierDistance(1).brumaRoots(1).hasFletchingKnife(true).build();
        assertEquals(0, WintertodtFinishPlan.fletchCapacity(s));
        assertEquals(1, WintertodtFinishPlan.fletchCapacity(s.toBuilder().roundBudgetSeconds(6).build()));
    }

    @Test public void capacityNeverExceedsBudgetOrLeavesRoomForAnotherFletch()
    {
        for (boolean knife : new boolean[]{false, true})
        {
            for (int budget = 0; budget <= 120; budget++)
            {
                for (int roots = 1; roots <= 28; roots++)
                {
                    WintertodtSnapshot s = timed(budget).brumaRoots(roots).hasFletchingKnife(knife).build();
                    int count = WintertodtFinishPlan.fletchCapacity(s);
                    double spare = budget - WintertodtFinishPlan.travelSeconds(s) - roots * WintertodtFinishPlan.FEED_SECONDS;
                    double first = knife ? .6 : 0;
                    double each = WintertodtFinishPlan.fletchSeconds(s);
                    if (count > 0) { assertTrue(count * each + first <= spare + 1e-9); }
                    if (count < roots) { assertTrue("Missed a viable fletch: budget=" + budget + ", roots=" + roots,
                        (count + 1) * each + first > spare - 1e-9); }
                }
            }
        }
    }
}

package com.wintertodtautopilot;

import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtGuidanceTest
{
    private final WintertodtSnapshot active = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE).build();
    private final WintertodtObjective fletch = new WintertodtObjective(ObjectiveType.FLETCH,
        "Fletch 12 roots", "batch_fletch", TargetKind.NONE, 12, false);

    @Test public void acknowledgesOnlyTheRequestedActivity()
    {
        assertEquals("NEXT ACTION", WintertodtGuidance.status(active, fletch));
        assertEquals("IN PROGRESS", WintertodtGuidance.status(active.toBuilder()
            .currentActivity(PlayerActivity.FLETCHING).interrupted(true).playerIdle(true).build(), fletch));
        assertEquals("RESUME", WintertodtGuidance.status(active.toBuilder().interrupted(true).build(), fletch));
        assertEquals("NEXT ACTION", WintertodtGuidance.status(active.toBuilder()
            .currentActivity(PlayerActivity.CHOPPING).build(), fletch));
    }

    @Test public void safetyOverridesRoutineActivityAndBlockedInventoryIsNotStandby()
    {
        WintertodtObjective drink = new WintertodtObjective(ObjectiveType.RESTORE_WARMTH,
            "Drink", "warmth_low", TargetKind.NONE, 1, true);
        assertEquals("ACT NOW", WintertodtGuidance.status(active.toBuilder()
            .currentActivity(PlayerActivity.FLETCHING).build(), drink));
        WintertodtObjective blocked = new WintertodtObjective(ObjectiveType.WAIT,
            "Make space", "inventory_blocked", TargetKind.NONE, 0, false);
        assertEquals("ACTION NEEDED", WintertodtGuidance.status(active, blocked));
        assertEquals("Free an inventory slot to continue.", WintertodtGuidance.reassurance(active, blocked));
    }

    @Test public void gatheringIngredientsDoesNotClaimMixingIsInProgress()
    {
        WintertodtSnapshot mixing = active.toBuilder().currentActivity(PlayerActivity.MAKING_POTION).build();
        WintertodtObjective gather = new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
            "Pick herbs", "prepare_supply", TargetKind.HERBS, 1, false);
        assertFalse(WintertodtGuidance.performing(mixing, gather));
        assertTrue(WintertodtGuidance.performing(mixing, new WintertodtObjective(ObjectiveType.MAKE_REJUVENATION,
            "Combine ingredients", "mix_rejuvenation", TargetKind.NONE, 1, false)));
    }
}

package com.wintertodtautopilot;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import static com.wintertodtautopilot.WintertodtEffortPolicyTest.*;

public class WintertodtHealingCueTest
{
    private WintertodtSnapshot down(int tick, PlayerActivity activity, WintertodtSnapshot.ActionState request)
    {
        return corner(scene(tick, 25, 24), WorkingCorner.SOUTHWEST, BrazierState.UNLIT,
            CornerObservation.PyromancerState.INCAPACITATED, 0, tick).toBuilder()
            .currentActivity(activity).actionActivity(PlayerActivity.HEALING).actionCorner(WorkingCorner.SOUTHWEST)
            .actionState(request).build();
    }
    @Test public void comfortableKeepsTheNpcOutlinedDuringPendingApproachArrivalAndFailedRequest()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        WintertodtAutopilotPlugin plugin = mock(WintertodtAutopilotPlugin.class);
        ModelOutlineRenderer outlines = mock(ModelOutlineRenderer.class);
        NPC npc = mock(NPC.class);
        WintertodtSceneOverlay overlay = new WintertodtSceneOverlay(mock(Client.class), plugin,
            new WintertodtAutopilotConfig() { }, outlines);
        when(plugin.getTargetNpc()).thenReturn(npc);
        Graphics2D graphics = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB).createGraphics();
        try
        {
            for (int tick = 10; tick <= 12; tick++)
            {
                WintertodtSnapshot s = down(tick, tick == 10 ? PlayerActivity.MOVING : PlayerActivity.IDLE,
                    tick == 12 ? WintertodtSnapshot.ActionState.UNCONFIRMED : WintertodtSnapshot.ActionState.REQUESTED);
                WintertodtObjective o = engine.decide(s, COMFORTABLE);
                assertEquals(TargetKind.PYROMANCER, o.getTarget()); assertEquals(WorkingCorner.SOUTHWEST, o.getDestination());
                assertFalse(WintertodtGuidance.performing(s, o));
                assertEquals(tick == 12 ? ObjectiveType.HEAL_PYROMANCER : ObjectiveType.WAIT, o.getType());
                when(plugin.getSnapshot()).thenReturn(s); when(plugin.getObjective()).thenReturn(o);
                overlay.render(graphics);
            }
            verify(outlines, times(3)).drawOutline(eq(npc), eq(1), any(java.awt.Color.class), eq(1));
            // Once the observed transformation confirms recovery, normal work replaces this target.
            WintertodtSnapshot healed = scene(13, 25, 23).toBuilder().actionActivity(PlayerActivity.HEALING)
                .actionCorner(WorkingCorner.SOUTHWEST).actionState(WintertodtSnapshot.ActionState.CONFIRMED).build();
            WintertodtObjective next = engine.decide(healed, COMFORTABLE);
            assertNotEquals(TargetKind.PYROMANCER, next.getTarget());
        }
        finally { graphics.dispose(); }
    }
    private WintertodtSnapshot injury(int tick, PlayerActivity activity, int health, int healthTick)
    {
        return corner(scene(tick, 25, 24), WorkingCorner.NORTHEAST, BrazierState.UNLIT,
            CornerObservation.PyromancerState.ALIVE, health, healthTick).toBuilder()
            .brumaRoots(3).freeSlots(3).currentActivity(activity).build();
    }
    @Test public void anOptionalHealingTargetSurvivesMovementAndArrivalWithoutStartingNewDetours()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        assertEquals("solo_points_heal", engine.decide(injury(10, PlayerActivity.FLETCHING, 50, 10), ACTIVE).getReason());
        for (PlayerActivity activity : new PlayerActivity[]{PlayerActivity.MOVING, PlayerActivity.IDLE})
        {
            WintertodtObjective o = engine.decide(injury(activity == PlayerActivity.MOVING ? 11 : 12, activity, 50, 10), ACTIVE);
            assertEquals("solo_points_heal", o.getReason()); assertEquals(WorkingCorner.NORTHEAST, o.getDestination());
        }
        WintertodtSoloEngine fresh = new WintertodtSoloEngine();
        assertNotEquals("solo_points_heal", fresh.decide(injury(10, PlayerActivity.MOVING, 50, 10), ACTIVE).getReason());
    }
    @Test public void approachDoesNotOverrideExpiredHealthSafetyOrObservedHealing()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        engine.decide(injury(10, PlayerActivity.FLETCHING, 50, 10), ACTIVE);
        assertNotEquals(TargetKind.PYROMANCER, engine.decide(injury(19, PlayerActivity.MOVING, 50, 10), ACTIVE).getTarget());
        engine.decide(injury(20, PlayerActivity.FLETCHING, 50, 20), ACTIVE);
        assertEquals(ObjectiveType.RESTORE_WARMTH, engine.decide(injury(21, PlayerActivity.MOVING, 50, 20)
            .toBuilder().warmth(10).build(), ACTIVE).getType());
        assertNotEquals(TargetKind.PYROMANCER, engine.decide(injury(22, PlayerActivity.MOVING, 50, 20), ACTIVE).getTarget());
        engine.decide(injury(23, PlayerActivity.FLETCHING, 50, 23), ACTIVE);
        assertNotEquals(TargetKind.PYROMANCER, engine.decide(injury(24, PlayerActivity.MOVING, 100, 24), ACTIVE).getTarget());
    }
}

package com.wintertodtautopilot;

import org.junit.Test;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.*;

public class WintertodtHighlightTest
{
    @Test public void healingLeavesAllInventoryItemsQuietEvenWithPotionsAndFuelInTheObjective()
    {
        int[] potions = {ItemID.WINT_POTION1, ItemID.WINT_POTION2, ItemID.WINT_POTION3, ItemID.WINT_POTION4};
        for (int potion : potions)
        {
            WintertodtObjective heal = new WintertodtObjective(ObjectiveType.HEAL_PYROMANCER, "Heal", "local_pyromancer_down",
                TargetKind.PYROMANCER, 1, false, potion, ItemID.WINT_BRUMA_ROOT, ItemID.WINT_BRUMA_KINDLING, ItemID.WINT_VIAL);
            for (PlayerActivity activity : new PlayerActivity[]{PlayerActivity.IDLE, PlayerActivity.FEEDING, PlayerActivity.FLETCHING, PlayerActivity.HEALING})
            {
                WintertodtSnapshot s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE)
                    .brumaRoots(5).brumaKindling(5).currentActivity(activity).build();
                assertFalse(WintertodtHighlight.inventoryItem(s, heal, potion));
                assertFalse(WintertodtHighlight.inventoryItem(s, heal, ItemID.WINT_BRUMA_ROOT));
                assertFalse(WintertodtHighlight.inventoryItem(s, heal, ItemID.WINT_BRUMA_KINDLING));
                assertFalse(WintertodtHighlight.inventoryItem(s, heal, ItemID.WINT_VIAL));
            }
        }
    }

    @Test public void inventoryBorderWidthStaysFixedWhilePulsingAndCanBeAdjusted()
    {
        assertEquals(1, new WintertodtAutopilotConfig() { }.highlightBorderWidth());
        int thin = paintedBorderPixels(1, 1);
        assertEquals(thin, paintedBorderPixels(1, .25f));
        assertTrue(paintedBorderPixels(4, 1) > thin);
        assertEquals(thin, paintedBorderPixels(0, 1));
        assertEquals(paintedBorderPixels(4, 1), paintedBorderPixels(100, 1));
    }

    private int paintedBorderPixels(int width, float strength)
    {
        java.awt.image.BufferedImage image = new java.awt.image.BufferedImage(80, 80, java.awt.image.BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D graphics = image.createGraphics();
        WintertodtHighlight.inventory(graphics, new java.awt.Rectangle(20, 20, 40, 40), java.awt.Color.ORANGE, strength, width);
        graphics.dispose();
        int count = 0;
        // Count pixels outside the item bounds, excluding the interior fill.
        for (int y = 0; y < 20; y++)
        {
            if ((image.getRGB(40, y) >>> 24) != 0) { count++; }
        }
        return count;
    }

    @Test public void interruptionCuePersistsUntilResumingAndExcludesMovementAndWaiting()
    {
        WintertodtSnapshot s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE).interrupted(true).build();
        WintertodtObjective o = new WintertodtObjective(ObjectiveType.FLETCH, "Continue fletching", "batch_fletch", TargetKind.NONE, 12, false);
        assertTrue(WintertodtHighlight.needsRestart(s, o));
        assertFalse(WintertodtHighlight.needsRestart(s.toBuilder().currentActivity(PlayerActivity.FLETCHING).build(), o));
        assertFalse(WintertodtHighlight.needsRestart(s.toBuilder().currentActivity(PlayerActivity.MOVING).build(), o));
        assertFalse(WintertodtHighlight.needsRestart(s.toBuilder().roundState(RoundState.COMPLETE).build(), o));
        assertFalse(WintertodtHighlight.needsRestart(s,
            new WintertodtObjective(ObjectiveType.WAIT, "Wait", "countdown", TargetKind.NONE, 0, false)));
    }
    @Test public void extinguishedBrazierPulsesWithoutChatOrIdleDetection()
    {
        WintertodtSnapshot s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE).currentActivity(PlayerActivity.FEEDING).build();
        WintertodtObjective light = new WintertodtObjective(ObjectiveType.LIGHT, "Relight", "brazier_unlit", TargetKind.BRAZIER, 0, false);
        assertTrue(WintertodtHighlight.needsAttention(s, light));
        float bright = WintertodtHighlight.strengthAt(s, light, true, 300_000_000L);
        float dim = WintertodtHighlight.strengthAt(s, light, true, 900_000_000L);
        assertEquals(1f, bright, .001f); assertEquals(.25f, dim, .001f);
        assertEquals(1f, WintertodtHighlight.strengthAt(s, light, false, 900_000_000L), 0);
        assertFalse(WintertodtHighlight.needsAttention(s.toBuilder().currentActivity(PlayerActivity.LIGHTING).build(), light));
        assertFalse(WintertodtHighlight.needsAttention(s.toBuilder().currentActivity(PlayerActivity.MOVING).build(), light));
    }
    @Test public void warmthAndUrgentFeedDemandAttentionUntilTheirActionStarts()
    {
        WintertodtSnapshot s = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).roundState(RoundState.ACTIVE).currentActivity(PlayerActivity.CHOPPING).build();
        WintertodtObjective drink = new WintertodtObjective(ObjectiveType.RESTORE_WARMTH, "Drink", "warmth_low", TargetKind.NONE, 1, true);
        assertTrue(WintertodtHighlight.needsAttention(s, drink));
        assertTrue(WintertodtHighlight.needsAttention(s.toBuilder().currentActivity(PlayerActivity.MOVING).build(), drink));
        assertFalse(WintertodtHighlight.needsAttention(s.toBuilder().currentActivity(PlayerActivity.RESTORING_WARMTH).build(), drink));
