package com.wintertodtautopilot;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WintertodtIgnoreWarmthSuppliesTest
{
    private WintertodtAutopilotConfig config(boolean ignore)
    {
        return new WintertodtAutopilotConfig() {
            @Override public boolean ignoreWarmthSupplies() { return ignore; }
        };
    }
    private PlannerSettings settings(boolean ignore) { return PlannerSettings.from(config(ignore)); }
    private WintertodtSnapshot snapshot(int tick, RoundState state, int warmth, boolean down)
    {
        List<CornerObservation> corners = new ArrayList<>();
        for (WorkingCorner c : WorkingCorner.values())
        {
            if (c == WorkingCorner.AUTOMATIC) { continue; }
            boolean incapacitated = down && c == WorkingCorner.SOUTHWEST;
            corners.add(new CornerObservation(c, c == WorkingCorner.SOUTHWEST && !down ? BrazierState.LIT : BrazierState.UNLIT,
                incapacitated ? CornerObservation.PyromancerState.INCAPACITATED : CornerObservation.PyromancerState.ALIVE,
                incapacitated ? 0 : 100, CornerObservation.Source.DIRECT_SCENE, CornerObservation.Source.DIRECT_SCENE,
                tick, tick, true, true));
        }
        return WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).observationTick(tick).roundState(state)
            .secondsToStart(5).wintertodtEnergy(26).points(0).warmth(warmth).rawWarmth(warmth * 10)
            .hasAxe(true).hasHammer(true).hasKnife(true).hasTinderbox(true).freeSlots(20).canMixPotion(true)
            .workingCorner(WorkingCorner.SOUTHWEST).playerLocation(WorkingCorner.SOUTHWEST.location()).brazierDistance(0)
            .localBrazierState(down ? BrazierState.UNLIT : BrazierState.LIT).localPyromancerKnown(true)
            .localPyromancerIncapacitated(down).corners(corners).build();
    }
    @Test public void defaultsPreserveWarmthRecoveryAndPotionPreparation()
    {
        assertFalse(new WintertodtAutopilotConfig() { }.ignoreWarmthSupplies());
        WintertodtSnapshot cold = snapshot(1, RoundState.ACTIVE, 5, false);
        assertEquals(ObjectiveType.RESTORE_WARMTH, new WintertodtDecisionEngine().decide(cold, settings(false)).getType());
        assertEquals(ObjectiveType.RESTORE_WARMTH, new WintertodtSoloEngine().decide(cold, settings(false)).getType());
        for (WintertodtPlanner planner : new WintertodtPlanner[]{new WintertodtDecisionEngine(), new WintertodtSoloEngine()})
        { assertEquals(ObjectiveType.MAKE_REJUVENATION, planner.decide(snapshot(1, RoundState.COUNTDOWN, 80, false), settings(false)).getType()); }
    }
    @Test public void bothModesWorkWithoutWarmthSuppliesAtEveryWarmthLevel()
    {
        for (int warmth : new int[]{0, 5, 20, 50, 80, 100})
        {
            for (WintertodtPlanner planner : new WintertodtPlanner[]{new WintertodtDecisionEngine(), new WintertodtSoloEngine()})
            {
                assertEquals(ObjectiveType.POSITION, planner.decide(snapshot(1, RoundState.COUNTDOWN, warmth, false), settings(true)).getType());
                assertEquals(ObjectiveType.CHOP, planner.decide(snapshot(2, RoundState.ACTIVE, warmth, false), settings(true)).getType());
                assertEquals(0, planner.getPreparationDoseTarget());
            }
        }
    }
    @Test public void togglingCancelsPreparationAndRestoresNormalPreparationInBothModes()
    {
        for (WintertodtPlanner planner : new WintertodtPlanner[]{new WintertodtDecisionEngine(), new WintertodtSoloEngine()})
        {
            assertEquals(ObjectiveType.MAKE_REJUVENATION, planner.decide(snapshot(1, RoundState.ACTIVE, 80, false), settings(false)).getType());
            assertEquals(ObjectiveType.CHOP, planner.decide(snapshot(2, RoundState.ACTIVE, 80, false), settings(true)).getType());
            assertEquals(0, planner.getPreparationDoseTarget());
            assertEquals(ObjectiveType.MAKE_REJUVENATION, planner.decide(snapshot(3, RoundState.ACTIVE, 80, false), settings(false)).getType());
            assertEquals(ObjectiveType.RESTORE_WARMTH, planner.decide(snapshot(4, RoundState.ACTIVE, 5, false), settings(false)).getType());
        }
    }
    @Test public void ignoringWarmthDoesNotSkipToolsOrUnknownInventory()
    {
        for (WintertodtPlanner planner : new WintertodtPlanner[]{new WintertodtDecisionEngine(), new WintertodtSoloEngine()})
        {
            WintertodtSnapshot s = snapshot(1, RoundState.COUNTDOWN, 5, false);
            assertEquals(ObjectiveType.GET_TOOL, planner.decide(s.toBuilder().hasAxe(false).build(), settings(true)).getType());
            assertEquals("supplies_unobserved", planner.decide(s.toBuilder().inventoryKnown(false).build(), settings(true)).getReason());
        }
    }
    @Test public void soloOnlyMakesAPotionWhenHealingIsRequiredAndCanUseTheLastDose()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        WintertodtSnapshot down = snapshot(1, RoundState.ACTIVE, 5, true);
        assertEquals(TargetKind.POTION_CRATE, engine.decide(down, settings(true)).getTarget());
        assertEquals(TargetKind.HERBS, engine.decide(snapshot(2, RoundState.ACTIVE, 5, true).toBuilder()
            .unfinishedPotionCount(1).build(), settings(true)).getTarget());
        WintertodtObjective mix = engine.decide(snapshot(3, RoundState.ACTIVE, 5, true).toBuilder()
            .unfinishedPotionCount(1).brumaHerbCount(1).build(), settings(true));
        assertEquals("mix_rejuvenation", mix.getReason()); assertEquals(1, mix.getQuantity());
        WintertodtObjective heal = engine.decide(snapshot(4, RoundState.ACTIVE, 5, true).toBuilder()
            .rejuvenationDoses(1).potionItem(ItemID.WINT_POTION1).build(), settings(true));
        assertEquals(ObjectiveType.HEAL_PYROMANCER, heal.getType());
        assertTrue(heal.getItemIds().contains(ItemID.WINT_POTION1));
        assertEquals(ObjectiveType.CHOP, engine.decide(snapshot(5, RoundState.ACTIVE, 5, false), settings(true)).getType());
    }
    @Test public void massStillPreparesForAnIncapacitatedPyromancer()
    {
        WintertodtObjective o = new WintertodtDecisionEngine().decide(snapshot(1, RoundState.ACTIVE, 5, true), settings(true));
        assertEquals(ObjectiveType.MAKE_REJUVENATION, o.getType()); assertEquals("heal_supply", o.getReason());
    }
    @Test public void ignoredWarmthDoesNotSuppressOtherNotificationsOrLatchWarnings()
    {
        WintertodtAttentionTracker tracker = new WintertodtAttentionTracker();
        WintertodtObjective chop = new WintertodtObjective(ObjectiveType.CHOP, "Chop", "batch_chop", TargetKind.ROOTS, 6, false);
        WintertodtSnapshot cold = snapshot(1, RoundState.ACTIVE, 5, false);
        assertNull(tracker.notification(cold, chop, config(true), 100));
        assertNotNull(tracker.notification(cold, chop, config(false), 101));
        assertNull(tracker.notification(cold, chop, config(true), 200));
        assertNotNull(tracker.notification(cold, chop, config(false), 201));
        WintertodtAutopilotConfig ignore = new WintertodtAutopilotConfig() {
            @Override public boolean ignoreWarmthSupplies() { return true; }
            @Override public boolean notifyRoundStart() { return true; }
        };
        assertEquals("Wintertodt round starts in 5 seconds", tracker.notification(snapshot(2, RoundState.COUNTDOWN, 5, false), chop, ignore, 202));
    }
    @Test public void settingChangeImmediatelyRetiresPotionCuesAndPreservesSoloFinish() throws Exception
    {
        WintertodtAutopilotPlugin plugin = new WintertodtAutopilotPlugin();
        net.runelite.client.callback.ClientThread thread = mock(net.runelite.client.callback.ClientThread.class);
        TrackerTestSupport.inject(plugin, "clientThread", thread);
        TrackerTestSupport.inject(plugin, "config", config(true));
        TrackerTestSupport.inject(plugin, "arrow", mock(WintertodtHintArrow.class));
        TrackerTestSupport.inject(plugin, "paths", mock(WintertodtPathTracker.class));
        java.lang.reflect.Field field = WintertodtAutopilotPlugin.class.getDeclaredField("solo");
        field.setAccessible(true);
        WintertodtSoloEngine solo = (WintertodtSoloEngine) field.get(plugin);
        solo.configure(5000, true);
        WintertodtSnapshot s = snapshot(1, RoundState.ACTIVE, 5, false).toBuilder().warmthItem(ItemID.WINT_POTION4).build();
        TrackerTestSupport.inject(plugin, "snapshot", s);
        TrackerTestSupport.inject(plugin, "objective", WintertodtSafety.objective(s, settings(false)));
        doAnswer(call -> { call.getArgument(0, Runnable.class).run(); return null; }).when(thread).invoke(any(Runnable.class));
        net.runelite.client.events.ConfigChanged change = new net.runelite.client.events.ConfigChanged();
        change.setGroup("wintertodtautopilot"); change.setKey("ignoreWarmthSupplies");
        plugin.onConfigChanged(change);
        assertEquals(ObjectiveType.WAIT, plugin.getObjective().getType());
        assertFalse(WintertodtHighlight.inventoryItem(s, plugin.getObjective(), ItemID.WINT_POTION4));
        assertTrue(solo.isFinishRequested());
    }

}

package com.wintertodtautopilot;

