import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class WintertodtRoundTrackerTest
{
    private Client client;
    private WintertodtRoundTracker tracker;
    private Widget energy, points;
    @Before public void setup() throws Exception
    {
        client = mock(Client.class); tracker = new WintertodtRoundTracker();
        TrackerTestSupport.inject(tracker, "client", client);
        energy = mock(Widget.class); points = mock(Widget.class);
        when(client.getWidget(InterfaceID.WintStatus.ENERGY)).thenReturn(energy);
        when(client.getWidget(InterfaceID.WintStatus.POINTS)).thenReturn(points);
    }
    private WintertodtSnapshot observe(int tick, int e, int p, int delay)
    {
        when(client.getTickCount()).thenReturn(tick);
        when(energy.getText()).thenReturn("Wintertodt's Energy: " + e + "%");
        when(points.getText()).thenReturn("Points: " + p);
        when(client.getVarbitValue(VarbitID.WINT_TRANSMIT_RESPAWNDELAY)).thenReturn(delay);
        WintertodtSnapshot.WintertodtSnapshotBuilder b = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true);
        tracker.fill(b, true, 4); return b.build();
    }
    @Test public void readsCurrentWidgetAndTimerSources()
    {
        WintertodtSnapshot s = observe(1, 0, 0, 20);
        assertEquals(RoundState.COUNTDOWN, s.getRoundState()); assertEquals(12, s.getSecondsToStart());
        assertEquals(RoundState.ACTIVE, observe(2, 100, 0, 0).getRoundState());
    }
    @Test public void endThenCountdownThenNewRound()
    {
        observe(1, 30, 500, 0);
        assertEquals(RoundState.ENDING, observe(2, 2, 550, 0).getRoundState());
        assertEquals(RoundState.COMPLETE, observe(3, 0, 575, 75).getRoundState());
        assertEquals(575, observe(4, 0, 0, 74).getPoints());
        assertEquals(RoundState.COUNTDOWN, observe(8, 0, 0, 70).getRoundState());
        assertEquals(RoundState.ACTIVE, observe(100, 100, 0, 0).getRoundState());
    }
    @Test public void missingWidgetIsUnknownRatherThanZero()
    {
        when(client.getWidget(InterfaceID.WintStatus.ENERGY)).thenReturn(null);
        WintertodtSnapshot.WintertodtSnapshotBuilder b = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true);
        tracker.fill(b, true, 0);
        assertEquals(-1, b.build().getWintertodtEnergy()); assertFalse(b.build().active());
    }
    @Test public void joiningMidRoundReadsVisibleBarTitleWhenLegacyEnergyIsHidden()
    {
        Widget title = mock(Widget.class);
        when(client.getWidget(InterfaceID.WintStatus.ENERGY_TITLE)).thenReturn(title);
        when(title.getText()).thenReturn("<col=00ff00>Wintertodt's Energy: 70%</col>");
        when(energy.isHidden()).thenReturn(true);
        WintertodtSnapshot s = observe(100, 0, 0, 0);
        assertEquals(70, s.getWintertodtEnergy());
        assertEquals(RoundState.ACTIVE, s.getRoundState());
        WintertodtObjective objective = new WintertodtDecisionEngine().decide(s,
            new PlannerSettings(WintertodtStrategy.MASS_BALANCED, PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 35, 20));
        assertNotEquals(ObjectiveType.ENTER, objective.getType());
    }
    @Test public void hiddenHudOutsideDoesNotStartRoundFromStaleText()
    {
        Widget title = mock(Widget.class);
        when(client.getWidget(InterfaceID.WintStatus.ENERGY_TITLE)).thenReturn(title);
        when(title.getText()).thenReturn("Wintertodt's Energy: 70%");
        when(title.isHidden()).thenReturn(true);
        when(energy.isHidden()).thenReturn(true);
        when(energy.getText()).thenReturn("Wintertodt's Energy: 70%");
        WintertodtSnapshot.WintertodtSnapshotBuilder b = WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true);
        tracker.fill(b, false, 0);
        assertEquals(-1, b.build().getWintertodtEnergy());
        assertEquals(RoundState.LOBBY, b.build().getRoundState());
    }
    @Test public void parserHandlesTagsCommasAndMalformedValues()
    {
        assertEquals(1025, WintertodtRoundTracker.parseNumber("<col=ff0000>Points: 1,025</col>"));
        assertEquals(-1, WintertodtRoundTracker.parseNumber("Waiting for Wintertodt"));
        assertEquals(-1, WintertodtRoundTracker.parseNumber(null));
        assertEquals(-1, WintertodtRoundTracker.parseNumber("99999999999999999999"));
    }
    @Test public void classificationsUseObservedRateWithoutExactCountdown()
    {
        assertEquals(EndUrgency.NORMAL, tracker.classify(70, 1, 4));
        assertEquals(EndUrgency.NORMAL, tracker.classify(40, 21, 4)); // A single burst is not a reliable pace.
        assertEquals(EndUrgency.IMMINENT, tracker.classify(3, 22, 4));
        tracker.reset();
        assertEquals(EndUrgency.NORMAL, tracker.classify(100, 100, 4));
    }
    @Test public void observedDrainFeedsIntoDeadlinePlannerAndClearsBetweenRounds()
    {
        WintertodtSnapshot observed = null;
        for (int t = 100; t <= 170; t++) { observed = observe(t, 10 - (t - 100) / 10, 450, 0); }
        assertTrue(observed.getEstimatedSecondsLeft() >= 17 && observed.getEstimatedSecondsLeft() <= 21);
        assertEquals((int) (observed.getEstimatedSecondsLeft() * .9) - 3, observed.getRoundBudgetSeconds());
        WintertodtSnapshot s = observed.toBuilder().warmth(90).brumaRoots(5).brazierDistance(0)
            .workingCorner(WorkingCorner.SOUTHEAST).localBrazierState(BrazierState.LIT)
            .localPyromancerKnown(true).hasAxe(true).hasKnife(true).hasHammer(true).hasTinderbox(true)
            .rejuvenationDoses(4).freeSlots(19).currentActivity(PlayerActivity.CHOPPING).build();
        WintertodtObjective objective = new WintertodtDecisionEngine().decide(s,
            new PlannerSettings(WintertodtStrategy.MASS_BALANCED, PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 35, 20));
        assertEquals(ObjectiveType.FEED, objective.getType());
        assertEquals("finish_feed", objective.getReason());
        assertEquals(-1, observe(171, 0, 500, 75).getEstimatedSecondsLeft());
        assertEquals(-1, observe(300, 100, 0, 0).getRoundBudgetSeconds());
    }

}

package com.wintertodtautopilot;

import com.google.gson.JsonElement;
import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtSoloCaptureTest
{
    private final WintertodtSoloCapture capture = new WintertodtSoloCapture(net.runelite.http.api.RuneLiteAPI.GSON);
    private final WintertodtSoloEngine source = new WintertodtSoloEngine();
    private final WintertodtSoloCapture.Replay replay = capture.new Replay();
    private boolean first = true;
    private long sequence;

    private String record(int tick, int energy, int roots, WintertodtSoloCapture.Lifecycle event, boolean finish)
    {
        if (event == WintertodtSoloCapture.Lifecycle.SUSPEND) { source.suspendObservations(); }
        if (event == WintertodtSoloCapture.Lifecycle.RESET) { source.reset(); }
        WintertodtSnapshot s = WintertodtSoloReliabilityTest.observed(tick, energy, 100, roots, BrazierState.UNLIT)
            .toBuilder().interaction("Private player name").build();
        JsonElement before = capture.checkpoint(source);
        source.configure(5000, finish);
        WintertodtObjective o = source.decide(s, WintertodtSoloReliabilityTest.SETTINGS);
        String encoded = capture.encode(s, WintertodtSoloReliabilityTest.SETTINGS, 5000, finish,
            event, first, sequence++, before, o, source.getPhase(), null);
        first = false;
        replay.accept(capture.decode("client-log-prefix " + encoded));
        return encoded;
    }

    @Test public void checkpointAndSequentialReplayRetainRecoveryBatchesAndLifecycle()
    {
        record(1, 28, 0, WintertodtSoloCapture.Lifecycle.NONE, false);
        record(2, 9, 1, WintertodtSoloCapture.Lifecycle.NONE, false);
        record(2, 9, 1, WintertodtSoloCapture.Lifecycle.NONE, false); // Duplicate tick retained.
        record(10, 11, 2, WintertodtSoloCapture.Lifecycle.SUSPEND, false);
        record(11, 12, 3, WintertodtSoloCapture.Lifecycle.NONE, false);
        record(12, 12, 4, WintertodtSoloCapture.Lifecycle.NONE, false);
        record(13, 12, 4, WintertodtSoloCapture.Lifecycle.NONE, true);
        record(14, 12, 4, WintertodtSoloCapture.Lifecycle.NONE, false); // Finish stays latched.
        record(15, 100, 0, WintertodtSoloCapture.Lifecycle.RESET, false);
        assertEquals(9, replay.getDecisions());
    }

    @Test public void captureCanStartMidRoundAndDoesNotRecordInteractionNames()
    {
        source.decide(WintertodtSoloReliabilityTest.observed(1, 9, 100, 0, BrazierState.UNLIT), WintertodtSoloReliabilityTest.SETTINGS);
        String line = record(3, 11, 2, WintertodtSoloCapture.Lifecycle.NONE, false);
        assertFalse(line.contains("Private player name"));
        assertEquals(1, replay.getDecisions());
    }

    @Test(expected = IllegalStateException.class) public void missingDecisionIsDetectedRatherThanReseedingEveryTick()
    {
        record(1, 28, 0, WintertodtSoloCapture.Lifecycle.NONE, false);
        // A missing observation enters recovery; replay must detect the state discontinuity.
        source.decide(WintertodtSoloReliabilityTest.observed(2, 9, 100, 1, BrazierState.UNLIT), WintertodtSoloReliabilityTest.SETTINGS);
        record(3, 11, 2, WintertodtSoloCapture.Lifecycle.NONE, false);
    }

    @Test(expected = IllegalArgumentException.class) public void incompatibleOrIncompleteCaptureIsRejected()
    { capture.decode(WintertodtSoloCapture.PREFIX + "{\"revision\":\"unknown\"}"); }

    @Test(expected = IllegalStateException.class) public void droppedDuplicateTickRecordIsDetectedEvenWithUnchangedControllerState()
    {
        record(1, 28, 0, WintertodtSoloCapture.Lifecycle.NONE, false);
        sequence++; // A dropped log record, even if it caused no controller mutation.
        record(1, 28, 0, WintertodtSoloCapture.Lifecycle.NONE, false);
    }

    @Test public void summaryReportsObservedCoverageAndEmitsOnceAtVerifiedBoundary()
    {
        WintertodtSoloRunSummary summary = new WintertodtSoloRunSummary();
        WintertodtSnapshot s = WintertodtSoloReliabilityTest.observed(1, 28, 100, 0, BrazierState.LIT);
        WintertodtObjective o = source.decide(s, WintertodtSoloReliabilityTest.SETTINGS);
        assertNull(summary.observe(s, o, source.getPhase()));
        assertNull(summary.observe(s, o, source.getPhase()));
        String end = summary.observe(s.toBuilder().roundState(RoundState.COMPLETE).build(), o, SoloPhase.PREPARE);
        assertTrue(end.contains("coverage=observed_only"));
        assertTrue(end.contains("observations=1"));
        assertNull(summary.end("reset"));
    }

    @Test public void writesAnExplicitlySyntheticFixtureForTheReplayCommand() throws Exception
    {
        java.util.List<String> lines = new java.util.ArrayList<>();
        lines.add("Synthetic planner observations. This is not a live gameplay capture.");
        lines.add(record(1, 100, 0, WintertodtSoloCapture.Lifecycle.NONE, false));
        lines.add(record(2, 28, 1, WintertodtSoloCapture.Lifecycle.NONE, false));
        lines.add(record(3, 9, 2, WintertodtSoloCapture.Lifecycle.NONE, false));
        lines.add(record(10, 11, 3, WintertodtSoloCapture.Lifecycle.SUSPEND, false));
        lines.add(record(11, 12, 4, WintertodtSoloCapture.Lifecycle.NONE, false));
        lines.add(record(12, 12, 4, WintertodtSoloCapture.Lifecycle.NONE, false));
        lines.add(record(13, 12, 4, WintertodtSoloCapture.Lifecycle.NONE, true));
        java.nio.file.Path fixture = java.nio.file.Path.of("build/reports/solo-replay/synthetic.log");
        java.nio.file.Files.createDirectories(fixture.getParent());
        java.nio.file.Files.write(fixture, lines, java.nio.charset.StandardCharsets.UTF_8);
    }

    @Test public void replayRetainsLearnedReservesAndEffortChangesWithoutReseeding()
    {
        for (int tick = 0; tick <= 315; tick++)
        {
            PlannerSettings settings = tick < 312 ? WintertodtEffortPolicyTest.ACTIVE : WintertodtEffortPolicyTest.COMFORTABLE;
            WintertodtSnapshot s = WintertodtEffortPolicyTest.scene(tick, 25, 24).toBuilder()
                .personalDosesUsed(tick % 10 == 0 ? 1 : 0).build();
            JsonElement before = capture.checkpoint(source);
            source.configure(5000, tick >= 313);
            WintertodtObjective chosen = source.decide(s, settings);
            String line = capture.encode(s, settings, 5000, tick >= 313,
                WintertodtSoloCapture.Lifecycle.NONE, tick == 0, tick, before, chosen, source.getPhase(), null);
            replay.accept(capture.decode(line));
            if (tick == 311) { assertEquals(40, source.getPreparationDoseTarget()); }
        }
        assertEquals(316, replay.getDecisions()); assertTrue(source.isFinishRequested());
    }
    @Test public void replayRetainsWarmthPolicyTogglesAndFinishRequest()
    {
        for (int tick = 0; tick < 5; tick++)
        {
            final boolean ignore = tick > 0 && tick < 4;
            PlannerSettings settings = PlannerSettings.from(new WintertodtAutopilotConfig() {
                @Override public boolean ignoreWarmthSupplies() { return ignore; }
            });
            WintertodtSnapshot s = WintertodtSoloReliabilityTest.observed(tick, 25, 100, tick, BrazierState.LIT)
                .toBuilder().rejuvenationDoses(0).build();
            JsonElement before = capture.checkpoint(source);
            source.configure(5000, tick == 2);
            WintertodtObjective chosen = source.decide(s, settings);
            replay.accept(capture.decode(capture.encode(s, settings, 5000, tick == 2,
                WintertodtSoloCapture.Lifecycle.NONE, tick == 0, tick, before, chosen, source.getPhase(), null)));
        }
        assertEquals(5, replay.getDecisions()); assertTrue(source.isFinishRequested());
    }

}

package com.wintertodtautopilot;

import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtSoloEnergyModelTest
{
    @Test public void trendAllowsRecoveryAndNeverProducesMassDeadline()
    {
        WintertodtSoloEnergyModel model = new WintertodtSoloEnergyModel();
        for (int tick = 1; tick <= 18; tick++) { model.observe(tick, 30 - tick / 10); }
        assertEquals(WintertodtSoloEnergyModel.Trend.DRAINING, model.getTrend());
        for (int tick = 19; tick <= 40; tick++) { model.observe(tick, 29 + (tick - 19) / 10); }
        assertEquals(WintertodtSoloEnergyModel.Trend.RECOVERING, model.getTrend());
        model.observe(41, -1); assertEquals(WintertodtSoloEnergyModel.Trend.UNKNOWN, model.getTrend());
        model.observe(42, 9); assertTrue(model.isRecovering());
    }
    @Test public void duplicateTicksCannotSatisfyRecoveryExitAndGapsResetConfirmation()
    {
        WintertodtSoloEnergyModel model = new WintertodtSoloEnergyModel();
        model.observe(1, 9); model.observe(2, 12);
        for (int i = 0; i < 10; i++) { model.observe(2, 12); }
        assertTrue(model.isRecovering());
        model.observe(3, 12); assertTrue(model.isRecovering());
        model.observe(8, 12); assertTrue(model.isRecovering());
        model.observe(9, 12); model.observe(10, 12); assertFalse(model.isRecovering());
    }
    @Test public void recoveryIncreaseClearsAnEarlierRapidDrainEpisode()
    {
        WintertodtSoloEnergyModel model = new WintertodtSoloEnergyModel();
        model.observe(1, 28); model.observe(2, 14); assertTrue(model.isRapidDrop());
        model.observe(3, 25); assertFalse(model.isRapidDrop());
        model.observe(4, 25); assertFalse(model.isRapidDrop());
    }

}

