            for (int irrelevant : new int[]{ItemID.WINT_BRUMA_ROOT, ItemID.WINT_BRUMA_KINDLING, ItemID.WINT_VIAL, ItemID.WINT_HERB})
            { assertFalse(WintertodtHighlight.inventoryItem(s, heal, irrelevant)); }
        }
    }

