public class WintertodtSoloRefinementTest
{
    private final WintertodtSoloEngine engine = new WintertodtSoloEngine();
    private final PlannerSettings settings = WintertodtSoloReliabilityTest.SETTINGS;
    private final Map<WorkingCorner, BrazierState> states = new EnumMap<>(WorkingCorner.class);

    private WintertodtSnapshot scene(int tick, WorkingCorner player)
    {
        List<CornerObservation> corners = new ArrayList<>();
        for (WorkingCorner c : WorkingCorner.values())
        {
            if (c == WorkingCorner.AUTOMATIC) { continue; }
            corners.add(new CornerObservation(c, states.getOrDefault(c, BrazierState.LIT), CornerObservation.PyromancerState.ALIVE,
                -1, CornerObservation.Source.DIRECT_SCENE, CornerObservation.Source.DIRECT_SCENE, tick, tick, true, true));
        }
        return WintertodtSoloReliabilityTest.observed(tick, 80, 100, 0, BrazierState.LIT).toBuilder()
            .playerLocation(player.location()).workingCorner(player).clearCorners().corners(corners).build();
    }
    private BrazierRoute route(WorkingCorner c, int cost, WorkingCorner... onWay)
    { return new BrazierRoute(c, cost, Collections.singletonList(c.location()), Arrays.asList(onWay)); }

    @Test public void oppositeCornersNoLongerTieAdjacentOpeningBraziers()
    {
        for (WorkingCorner player : new WorkingCorner[]{WorkingCorner.SOUTHEAST, WorkingCorner.NORTHEAST})
        {
            engine.reset(); states.clear();
            for (WorkingCorner c : WorkingCorner.values()) { states.put(c, BrazierState.UNLIT); }
            states.put(player, BrazierState.LIT);
            WorkingCorner opposite = player == WorkingCorner.SOUTHEAST ? WorkingCorner.NORTHWEST : WorkingCorner.SOUTHWEST;
            WintertodtObjective o = engine.decide(scene(1, player), settings);
            assertEquals(ObjectiveType.LIGHT, o.getType());
            assertNotEquals(opposite, o.getDestination());
        }
    }

    @Test public void passedBrazierIsServicedThenOriginalDestinationResumesInBothDiagonalDirections()
    {
        for (WorkingCorner player : new WorkingCorner[]{WorkingCorner.SOUTHEAST, WorkingCorner.NORTHEAST})
        {
            engine.reset(); states.clear(); engine.configure(13500, false);
            WorkingCorner primary = player == WorkingCorner.SOUTHEAST ? WorkingCorner.NORTHWEST : WorkingCorner.SOUTHWEST;
            WorkingCorner stop = player == WorkingCorner.SOUTHEAST ? WorkingCorner.SOUTHWEST : WorkingCorner.SOUTHEAST;
            states.put(primary, BrazierState.UNLIT);
            WintertodtSnapshot first = scene(1, player).toBuilder().brazierRoute(route(primary, 30, stop)).brazierRoute(route(stop, 3)).build();
            assertEquals(primary, engine.decide(first, settings).getDestination());
            states.put(stop, BrazierState.UNLIT);
            WintertodtSnapshot second = scene(2, player).toBuilder().brazierRoutes(first.getBrazierRoutes()).build();
            WintertodtObjective intermediate = engine.decide(second, settings);
            assertEquals(stop, intermediate.getDestination());
            assertEquals(SoloAdvice.Reason.ON_THE_WAY, intermediate.getSoloAdvice().getReason());
            assertEquals(primary, intermediate.getSoloAdvice().getDeferredDestination());
            assertTrue(WintertodtGuidance.reassurance(second, intermediate).contains("13,500"));
            WintertodtSnapshot approaching = scene(3, player).toBuilder()
                .brazierRoute(route(primary, 28)).brazierRoute(route(stop, 1)).build();
            assertEquals(stop, engine.decide(approaching, settings).getDestination()); // Keep the stop through path changes while approaching.
            states.put(stop, BrazierState.LIT);
            assertEquals(primary, engine.decide(scene(4, player).toBuilder().brazierRoutes(first.getBrazierRoutes()).build(), settings).getDestination());
        }
    }

    @Test public void observedWalkingCostAndInteractionCostDetermineOpeningOrder()
    {
        states.put(WorkingCorner.NORTHWEST, BrazierState.BROKEN); states.put(WorkingCorner.NORTHEAST, BrazierState.UNLIT);
        WintertodtSnapshot s = scene(1, WorkingCorner.SOUTHEAST).toBuilder()
            .brazierRoute(route(WorkingCorner.NORTHWEST, 5)).brazierRoute(route(WorkingCorner.NORTHEAST, 5)).build();
        assertEquals(WorkingCorner.NORTHEAST, engine.decide(s, settings).getDestination());
        engine.reset();
        assertEquals(WorkingCorner.NORTHWEST, engine.decide(s.toBuilder().clearBrazierRoutes()
            .brazierRoute(route(WorkingCorner.NORTHWEST, 0)).brazierRoute(route(WorkingCorner.NORTHEAST, 20)).build(), settings).getDestination());
    }

    @Test public void opportunisticStopRequiresFreshPhysicalEvidenceAndAnActualPathOpportunity()
    {
        states.put(WorkingCorner.NORTHWEST, BrazierState.UNLIT);
        WintertodtSnapshot first = scene(1, WorkingCorner.SOUTHEAST).toBuilder()
            .brazierRoute(route(WorkingCorner.NORTHWEST, 30, WorkingCorner.SOUTHWEST))
            .brazierRoute(route(WorkingCorner.SOUTHWEST, 3)).build();
        engine.decide(first, settings);
        states.put(WorkingCorner.SOUTHWEST, BrazierState.UNLIT);
        WintertodtSnapshot second = scene(2, WorkingCorner.SOUTHEAST).toBuilder().brazierRoutes(first.getBrazierRoutes()).build();
        List<CornerObservation> unknownPyro = new ArrayList<>();
        for (CornerObservation c : second.getCorners())
        {
            unknownPyro.add(c.getCorner() != WorkingCorner.SOUTHWEST ? c : new CornerObservation(c.getCorner(), c.getBrazierState(),
                CornerObservation.PyromancerState.UNKNOWN, -1, c.getBrazierSource(), CornerObservation.Source.NONE, 2, -1, true, false));
        }
        assertEquals(WorkingCorner.NORTHWEST, engine.decide(second.toBuilder().clearCorners().corners(unknownPyro).build(), settings).getDestination());
        WintertodtSnapshot offRoute = second.toBuilder().clearBrazierRoutes().brazierRoute(route(WorkingCorner.NORTHWEST, 30))
            .brazierRoute(route(WorkingCorner.SOUTHWEST, 3)).build();
        assertEquals(WorkingCorner.NORTHWEST, engine.decide(offRoute, settings).getDestination());
    }

    @Test public void knownUnreachableRequiredFireProducesAnHonestWait()
    {
        states.put(WorkingCorner.NORTHWEST, BrazierState.UNLIT);
        WintertodtObjective o = engine.decide(scene(1, WorkingCorner.SOUTHEAST).toBuilder()
            .brazierRoute(route(WorkingCorner.NORTHWEST, -1)).build(), settings);
        assertEquals("solo_route_blocked", o.getReason()); assertEquals(ObjectiveType.WAIT, o.getType());
    }

    @Test public void finishNeverLightsAnUnselectedThirdFireJustBecauseTheRoutePassesIt()
    {
        states.put(WorkingCorner.NORTHEAST, BrazierState.UNLIT); states.put(WorkingCorner.SOUTHWEST, BrazierState.UNLIT);
        states.put(WorkingCorner.NORTHWEST, BrazierState.UNLIT);
        engine.configure(13500, false);
        WintertodtSnapshot s = scene(1, WorkingCorner.SOUTHEAST).toBuilder().wintertodtEnergy(8).points(13500)
            .brazierRoute(route(WorkingCorner.NORTHEAST, 10, WorkingCorner.NORTHWEST))
            .brazierRoute(route(WorkingCorner.SOUTHWEST, 30)).brazierRoute(route(WorkingCorner.NORTHWEST, 2)).build();
        PlannerSettings active = new PlannerSettings(settings.getStrategy(), settings.getPointGoal(), settings.getFletchMode(),
            settings.getRestoreWarmth(), settings.getEmergencyWarmth(), SoloEffort.ACTIVE);
        WintertodtObjective o = engine.decide(s.toBuilder().runEnergyPercent(100).build(), active);
        assertEquals(WorkingCorner.NORTHEAST, o.getDestination());
        assertEquals(SoloAdvice.Reason.FINISH, o.getSoloAdvice().getReason());
        assertTrue(WintertodtGuidance.reassurance(s, o).contains("goal reached"));
        assertTrue(WintertodtGuidance.reassurance(s, o).contains("leave other braziers alone"));
    }

    @Test public void recoveryAndLocalSustainIgnoreOtherUnlitRouteOpportunities()
    {
        states.put(WorkingCorner.NORTHWEST, BrazierState.UNLIT); states.put(WorkingCorner.SOUTHEAST, BrazierState.UNLIT);
        engine.configure(13500, false);
        WintertodtSnapshot recovery = scene(1, WorkingCorner.SOUTHEAST).toBuilder().wintertodtEnergy(9)
            .brazierRoute(route(WorkingCorner.NORTHWEST, 10)).build();
        WintertodtObjective o = engine.decide(recovery, settings);
        assertEquals(ObjectiveType.CHOP, o.getType());
        assertEquals(SoloAdvice.Reason.RECOVERY, o.getSoloAdvice().getReason());
        assertTrue(WintertodtGuidance.reassurance(recovery, o).contains("100 / 13,500 points"));
        assertTrue(WintertodtGuidance.reassurance(recovery, o).contains("remaining fires"));
        engine.reset();
        states.put(WorkingCorner.SOUTHEAST, BrazierState.LIT);
        WintertodtSnapshot local = scene(2, WorkingCorner.SOUTHEAST).toBuilder().wintertodtEnergy(26).build();
        assertEquals(ObjectiveType.CHOP, engine.decide(local, settings).getType());
    }

    @Test public void manualFinishBelowTheGoalNeverClaimsGoalReachedAndSafetyHasNoStrategicOverlay()
    {
        engine.configure(13500, true);
        WintertodtSnapshot s = scene(1, WorkingCorner.SOUTHEAST).toBuilder().wintertodtEnergy(9).build();
        WintertodtObjective o = engine.decide(s, settings);
        assertTrue(WintertodtGuidance.reassurance(s, o).contains("Finish requested at 100 / 13,500 points"));
        assertFalse(WintertodtGuidance.reassurance(s, o).contains("goal reached"));
        assertNull(engine.decide(s.toBuilder().observationTick(2).warmth(15).build(), settings).getSoloAdvice());
    }

    @Test public void completeRoundAndNewCountdownReuseUnconsumedSupplies()
    {
        WintertodtSnapshot active = scene(1, WorkingCorner.SOUTHWEST).toBuilder().wintertodtEnergy(26).rejuvenationDoses(12).build();
        assertEquals(ObjectiveType.CHOP, engine.decide(active, settings).getType());
        assertEquals(ObjectiveType.ROUND_COMPLETE, engine.decide(active.toBuilder().observationTick(2)
            .roundState(RoundState.COMPLETE).wintertodtEnergy(0).build(), settings).getType());
        for (int tick = 3; tick < 8; tick++)
        {
            assertEquals(ObjectiveType.POSITION, engine.decide(active.toBuilder().observationTick(tick)
                .roundState(RoundState.COUNTDOWN).secondsToStart(60 - tick).wintertodtEnergy(-1).build(), settings).getType());
        }
        assertNotEquals(ObjectiveType.MAKE_REJUVENATION, engine.decide(active.toBuilder().observationTick(8).wintertodtEnergy(100).build(), settings).getType());
    }

    @Test public void earningGoalWhileTravelingCancelsTheOpeningCircuit()
    {
        engine.configure(500, false); states.put(WorkingCorner.NORTHWEST, BrazierState.UNLIT);
        WintertodtSnapshot opening = scene(1, WorkingCorner.SOUTHEAST).toBuilder()
            .brazierRoute(route(WorkingCorner.NORTHWEST, 30)).build();
        assertEquals(WorkingCorner.NORTHWEST, engine.decide(opening, settings).getDestination());
        WintertodtSnapshot goal = scene(2, WorkingCorner.SOUTHEAST).toBuilder().points(500).wintertodtEnergy(20).build();
        WintertodtObjective finish = engine.decide(goal, settings);
        assertEquals(SoloPhase.FINISH, engine.getPhase());
        assertEquals("solo_finish_drain", finish.getReason());
        assertTrue(WintertodtGuidance.reassurance(goal, finish).contains("goal reached"));
        assertNotEquals(WorkingCorner.NORTHWEST, finish.getDestination());
    }
}

package com.wintertodtautopilot;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtSoloReliabilityTest
{
    static final PlannerSettings SETTINGS = PlannerSettings.from(new WintertodtAutopilotConfig() { });

    static WintertodtSnapshot observed(int tick, int energy, int points, int roots, BrazierState fire)
    {
        List<CornerObservation> corners = new ArrayList<>();
        for (WorkingCorner c : WorkingCorner.values())
        {
            if (c == WorkingCorner.AUTOMATIC) { continue; }
            corners.add(new CornerObservation(c, c == WorkingCorner.SOUTHWEST ? fire : BrazierState.UNLIT,
                CornerObservation.PyromancerState.ALIVE, -1, CornerObservation.Source.DIRECT_SCENE,
                CornerObservation.Source.DIRECT_SCENE, tick, tick, true, true));
        }
        return WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true)
            .observationTick(tick).roundState(RoundState.ACTIVE).wintertodtEnergy(energy).points(points)
            .warmth(80).rawWarmth(800).brumaRoots(roots).freeSlots(6 - roots).rejuvenationDoses(24)
            .warmthItem(ItemID.WINT_POTION4).potionItem(ItemID.WINT_POTION4).hasKnife(true).hasHammer(true)
            .hasTinderbox(true).hasAxe(true).workingCorner(WorkingCorner.SOUTHWEST)
            .playerLocation(WorkingCorner.SOUTHWEST.location()).corners(corners).build();
    }

    @Test public void loadingAtEveryRecoveryBoundaryRequiresNewExitConfirmation()
    {
        for (int resumedEnergy : new int[]{9, 11, 12})
        {
            WintertodtSoloEngine engine = new WintertodtSoloEngine();
            engine.decide(observed(10, 9, 100, 0, BrazierState.UNLIT), SETTINGS);
            engine.decide(observed(11, 12, 100, 1, BrazierState.UNLIT), SETTINGS);
            engine.suspendObservations();
            assertTrue(engine.isAwaitingObservations());
            WintertodtSnapshot resumed = observed(20, resumedEnergy, 100, 2, BrazierState.UNLIT);
            assertEquals(ObjectiveType.CHOP, engine.decide(resumed, SETTINGS).getType());
            assertEquals(SoloPhase.RECOVER_ENERGY, engine.getPhase());
            assertEquals(6, engine.batchTarget());
            engine.decide(resumed, SETTINGS); // Duplicate observation cannot confirm recovery twice.
            engine.decide(observed(21, 12, 100, 3, BrazierState.UNLIT), SETTINGS);
            assertEquals(SoloPhase.RECOVER_ENERGY, engine.getPhase());
            engine.decide(observed(22, 12, 100, 4, BrazierState.UNLIT), SETTINGS);
            assertEquals(SoloPhase.RECOVER_ENERGY, engine.getPhase());
            WintertodtObjective relight = engine.decide(observed(23, 12, 100, 4, BrazierState.UNLIT), SETTINGS);
            assertEquals(SoloPhase.SUSTAIN, engine.getPhase());
            assertEquals(ObjectiveType.CHOP, relight.getType()); // Finish the original batch first.
            assertEquals(2, relight.getQuantity());
        }
    }

    @Test public void backwardsClientTickCannotClearRecovery()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        engine.decide(observed(20, 9, 100, 0, BrazierState.UNLIT), SETTINGS);
        engine.decide(observed(1, 11, 100, 1, BrazierState.UNLIT), SETTINGS);
        assertTrue(engine.recovering());
        assertNotEquals(ObjectiveType.LIGHT, engine.decide(observed(2, 11, 100, 2, BrazierState.UNLIT), SETTINGS).getType());
    }

    @Test public void missingScoreAfterReloadCannotApplyLatchedFinishToAnUnverifiedRound()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        engine.configure(5000, true);
        engine.decide(observed(1, 25, 1000, 0, BrazierState.UNLIT), SETTINGS);
        engine.suspendObservations();
        assertEquals(ObjectiveType.WAIT, engine.decide(observed(5, 25, -1, 0, BrazierState.UNLIT), SETTINGS).getType());
        assertTrue(engine.isFinishRequested()); assertTrue(engine.isAwaitingObservations());
        assertEquals(ObjectiveType.LIGHT, engine.decide(observed(6, 25, 1000, 0, BrazierState.UNLIT), SETTINGS).getType());
    }

    @Test public void lowEnergyObservedDuringWarmthRestorationStillLatchesRecovery()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        WintertodtSnapshot cold = observed(10, 9, 100, 0, BrazierState.UNLIT).toBuilder().warmth(15).build();
        assertEquals(ObjectiveType.RESTORE_WARMTH, engine.decide(cold, SETTINGS).getType());
        engine.decide(observed(11, 11, 100, 1, BrazierState.UNLIT), SETTINGS);
        assertTrue(engine.recovering());
        assertEquals(SoloPhase.RECOVER_ENERGY, engine.getPhase());
    }

    @Test public void reloadPreservesPartialFletchingAndFeedingCommitments()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        assertEquals(ObjectiveType.FLETCH, engine.decide(observed(1, 28, 100, 6, BrazierState.LIT), SETTINGS).getType());
        engine.suspendObservations();
        WintertodtSnapshot partial = observed(5, 26, 100, 3, BrazierState.LIT).toBuilder().brumaKindling(3).freeSlots(0).build();
        assertEquals(ObjectiveType.FLETCH, engine.decide(partial, SETTINGS).getType());
        WintertodtSnapshot fletched = observed(6, 26, 100, 0, BrazierState.LIT).toBuilder().brumaKindling(6).freeSlots(0).build();
        assertEquals(ObjectiveType.FEED, engine.decide(fletched, SETTINGS).getType());
        engine.suspendObservations();
        assertEquals(ObjectiveType.FEED, engine.decide(fletched.toBuilder().observationTick(8)
            .brumaKindling(5).points(125).freeSlots(1).build(), SETTINGS).getType());
    }

    @Test public void observationLossDoesNotChangeAnOpeningDestinationMidWalk()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        WintertodtObjective original = engine.decide(observed(1, 100, 100, 0, BrazierState.LIT), SETTINGS);
        assertNotEquals(WorkingCorner.SOUTHWEST, original.getDestination());
        engine.suspendObservations();
        WintertodtObjective resumed = engine.decide(observed(5, 99, 100, 0, BrazierState.LIT).toBuilder()
            .playerLocation(WorkingCorner.NORTHEAST.location()).build(), SETTINGS);
        assertEquals(original.getDestination(), resumed.getDestination());
    }

    @Test public void irrelevantMassSettingsAndWarmthThresholdsDoNotBreakSoloBatch()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        engine.decide(observed(1, 28, 100, 0, BrazierState.LIT), SETTINGS);
        PlannerSettings changed = new PlannerSettings(SETTINGS.getStrategy(), PointGoal.NEXT_THRESHOLD,
            SETTINGS.getFletchMode(), 60, 25);
        WintertodtSnapshot partial = observed(2, 26, 100, 2, BrazierState.LIT).toBuilder().brumaKindling(1).freeSlots(3).build();
        assertEquals(ObjectiveType.CHOP, engine.decide(partial, changed).getType());
        assertEquals(6, engine.batchTarget());
    }

    @Test public void regressedScoreCannotApplyOldFinishIntentToAnUnverifiedRound()
    {
        WintertodtSoloEngine engine = new WintertodtSoloEngine();
        engine.configure(5000, true);
        engine.decide(observed(1, 25, 1000, 0, BrazierState.UNLIT), SETTINGS);
        engine.suspendObservations();
        for (int tick = 3; tick < 7; tick++)
        {
            WintertodtObjective o = engine.decide(observed(tick, 90, 0, 0, BrazierState.UNLIT), SETTINGS);
            assertEquals("solo_score_changed", o.getReason());
            assertEquals(ObjectiveType.WAIT, o.getType());
        }
        assertTrue(engine.isFinishRequested());
        engine.decide(observed(7, 0, 0, 0, BrazierState.UNLIT).toBuilder().roundState(RoundState.COUNTDOWN).secondsToStart(50).build(), SETTINGS);
        assertFalse(engine.isFinishRequested());
        assertEquals(ObjectiveType.LIGHT, engine.decide(observed(8, 100, 0, 0, BrazierState.UNLIT), SETTINGS).getType());
    }

    @Test public void unknownContainersCannotInventMissingToolsOrCauseRoutineWork()
    {
        WintertodtSnapshot unknown = observed(1, 28, 100, 0, BrazierState.UNLIT).toBuilder()
            .inventoryKnown(false).hasAxe(false).hasKnife(false).hasHammer(false).build();
        assertEquals("supplies_unobserved", new WintertodtSoloEngine().decide(unknown, SETTINGS).getReason());
        assertEquals("supplies_unobserved", new WintertodtDecisionEngine().decide(unknown, SETTINGS).getReason());
        assertEquals("warmth_supplies_unknown", new WintertodtSoloEngine().decide(unknown.toBuilder().warmth(15).build(), SETTINGS).getReason());
        assertEquals("supplies_unobserved", new WintertodtSoloEngine().decide(unknown.toBuilder()
            .inventoryKnown(true).equipmentKnown(false).build(), SETTINGS).getReason());
    }

    @Test public void loadedFireCountDoesNotBecomeAnExactDrainCount()
    {
        WintertodtSnapshot all = observed(1, 28, 100, 0, BrazierState.LIT);
        assertEquals(1, all.observedFunctionalBraziers());
        CornerObservation home = all.corner(WorkingCorner.SOUTHWEST);
        WintertodtSnapshot unknown = all.toBuilder().clearCorners().corner(new CornerObservation(home.getCorner(),
            home.getBrazierState(), CornerObservation.PyromancerState.UNKNOWN, -1, home.getBrazierSource(),
            CornerObservation.Source.NONE, 1, -1, true, false)).build();
        assertEquals(-1, unknown.observedFunctionalBraziers());
    }
}

package com.wintertodtautopilot;

import java.io.BufferedReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/** Local developer tool: ./gradlew replaySolo -PtraceFile=/absolute/path/to/client.log */
public final class WintertodtSoloReplay
{
    public static void main(String[] args) throws Exception
    {
        if (args.length != 1) { throw new IllegalArgumentException("Provide one trace file path"); }
        WintertodtSoloCapture capture = new WintertodtSoloCapture(net.runelite.http.api.RuneLiteAPI.GSON);
        WintertodtSoloCapture.Replay replay = capture.new Replay();
        try (BufferedReader reader = Files.newBufferedReader(Path.of(args[0]), StandardCharsets.UTF_8))
        {
            String line; int number = 0;
            while ((line = reader.readLine()) != null)
            {
                number++;
                if (!line.contains(WintertodtSoloCapture.PREFIX)) { continue; }
                try { replay.accept(capture.decode(line)); }
                catch (RuntimeException e) { throw new IllegalStateException("Replay failed on line " + number, e); }
            }
        }
        if (replay.getDecisions() == 0) { throw new IllegalArgumentException("No Solo capture records found"); }
        System.out.println("Replayed " + replay.getDecisions() + " Solo decisions with matching state, objectives and phases.");
    }
}

package com.wintertodtautopilot;

import org.junit.Test;
import static org.junit.Assert.*;

public class WintertodtSoloSupplyPlanTest
{
    private final WintertodtSoloSupplyPlan plan = new WintertodtSoloSupplyPlan();
    private final PlannerSettings points = new PlannerSettings(WintertodtStrategy.MASS_POINTS,
        PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 50, 20);
    private final PlannerSettings xp = new PlannerSettings(WintertodtStrategy.MASS_XP,
        PointGoal.MINIMUM_500, FletchMode.AUTOMATIC, 50, 20);
    private WintertodtSnapshot supplies(int doses)
    {
        return WintertodtSnapshot.builder().inventoryKnown(true).equipmentKnown(true).hasAxe(true).hasHammer(true).hasTinderbox(true).hasKnife(true)
            .canMixPotion(true).freeSlots(20).rejuvenationDoses(doses).build();
    }
    @Test public void openingPreparesSixBottlesAndLeavesRoomForHerbs()
    {
        WintertodtObjective o = plan.prepare(supplies(0), points, SoloPhase.PREPARE);
        assertEquals(TargetKind.POTION_CRATE, o.getTarget()); assertEquals(6, o.getQuantity());
        assertEquals(24, plan.getTarget());
        o = plan.prepare(supplies(0).toBuilder().freeSlots(2).build(), points, SoloPhase.PREPARE);
        assertEquals(1, o.getQuantity());
        assertNull(plan.prepare(supplies(24), points, SoloPhase.PREPARE));
    }
    @Test public void pointsRestocksBeforeHealingExhaustsItsSpareBottles()
    {
        assertNull(plan.prepare(supplies(24), points, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(supplies(8), points, SoloPhase.SUSTAIN));
        assertNotNull(plan.prepare(supplies(7), points, SoloPhase.SUSTAIN));
        assertEquals(24, plan.getTarget());
        assertNotNull(plan.prepare(supplies(12), points, SoloPhase.SUSTAIN)); // Complete the ongoing trip.
        assertNull(plan.prepare(supplies(24), points, SoloPhase.SUSTAIN));
    }
    @Test public void xpConservesDosesAndFinishingKeepsTwoBottles()
    {
        assertNull(plan.prepare(supplies(24), xp, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(supplies(7), xp, SoloPhase.SUSTAIN));
        assertNotNull(plan.prepare(supplies(3), xp, SoloPhase.SUSTAIN));
        assertEquals(24, plan.getTarget());
        assertNotNull(plan.prepare(supplies(3), xp, SoloPhase.FINISH));
        assertEquals(8, plan.getTarget());
        assertNull(plan.prepare(supplies(8), xp, SoloPhase.FINISH));
    }
    @Test public void routineRestockWaitsUntilCarriedFuelIsFed()
    {
        assertNull(plan.prepare(supplies(24), points, SoloPhase.SUSTAIN));
        WintertodtSnapshot working = supplies(7).toBuilder().roundState(RoundState.ACTIVE)
            .brumaRoots(5).build();
        assertNull(plan.prepare(working, points, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(working.toBuilder().brumaRoots(0).brumaKindling(5).build(), points, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(working.toBuilder().brumaRoots(1).build(), points, SoloPhase.SUSTAIN));
        assertNotNull(plan.prepare(working.toBuilder().brumaRoots(0).build(), points, SoloPhase.SUSTAIN));
        assertNotNull(plan.prepare(supplies(12), points, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(supplies(24), points, SoloPhase.SUSTAIN));
    }

    @Test public void lastDoseCannotDeferRestockingBehindAFuelBatch()
    {
        assertNull(plan.prepare(supplies(24), points, SoloPhase.SUSTAIN));
        assertNotNull(plan.prepare(supplies(1).toBuilder().roundState(RoundState.ACTIVE)
            .brumaRoots(5).build(), points, SoloPhase.SUSTAIN));
    }

    @Test public void joiningMidRoundAcceptsAUsablePartialReserve()
    {
        assertNull(plan.prepare(supplies(12).toBuilder().roundState(RoundState.ACTIVE).build(), points, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(supplies(11).toBuilder().roundState(RoundState.ACTIVE).build(), points, SoloPhase.SUSTAIN));
        assertNotNull(plan.prepare(supplies(7).toBuilder().roundState(RoundState.ACTIVE).build(), points, SoloPhase.SUSTAIN));
    }

    @Test public void sixBottlePreparationCollectsAllVialsAndHerbsBeforeMixing()
    {
        for (int vials = 0; vials < 6; vials++)
        {
            WintertodtObjective o = plan.prepare(supplies(0).toBuilder().unfinishedPotionCount(vials).freeSlots(20 - vials).build(), points, SoloPhase.PREPARE);
            assertEquals(TargetKind.POTION_CRATE, o.getTarget()); assertEquals(6 - vials, o.getQuantity());
        }
        for (int herbs = 0; herbs < 6; herbs++)
        {
            WintertodtObjective o = plan.prepare(supplies(0).toBuilder().unfinishedPotionCount(6).brumaHerbCount(herbs).freeSlots(14 - herbs).build(), points, SoloPhase.PREPARE);
            assertEquals(TargetKind.HERBS, o.getTarget()); assertEquals(6 - herbs, o.getQuantity());
        }
        for (int mixed = 0; mixed < 6; mixed++)
        {
            WintertodtObjective o = plan.prepare(supplies(mixed * 4).toBuilder().unfinishedPotionCount(6 - mixed)
                .brumaHerbCount(6 - mixed).freeSlots(8 + mixed).build(), points, SoloPhase.PREPARE);
            assertEquals("mix_rejuvenation", o.getReason()); assertEquals(6 - mixed, o.getQuantity());
        }
        assertNull(plan.prepare(supplies(24), points, SoloPhase.PREPARE));
    }

    @Test public void existingDosesAndIngredientsReduceOnlyTheirOwnDeficits()
    {
        WintertodtSnapshot s = supplies(7).toBuilder().unfinishedPotionCount(2).brumaHerbCount(1).freeSlots(12).build();
        WintertodtObjective o = plan.prepare(s, points, SoloPhase.PREPARE);
        assertEquals(TargetKind.POTION_CRATE, o.getTarget()); assertEquals(3, o.getQuantity());
        o = plan.prepare(s.toBuilder().unfinishedPotionCount(5).freeSlots(9).build(), points, SoloPhase.PREPARE);
        assertEquals(TargetKind.HERBS, o.getTarget()); assertEquals(4, o.getQuantity());
        o = plan.prepare(s.toBuilder().unfinishedPotionCount(5).brumaHerbCount(5).freeSlots(5).build(), points, SoloPhase.PREPARE);
        assertEquals("mix_rejuvenation", o.getReason()); assertEquals(5, o.getQuantity());
        assertNull(plan.prepare(supplies(27), points, SoloPhase.PREPARE)); // Rounded up to full four-dose bottles.
    }

    @Test public void constrainedInventoryUsesFeasibleSubBatchesAndNeverRequestsAnUnpairableVial()
    {
        WintertodtObjective o = plan.prepare(supplies(0).toBuilder().freeSlots(1).build(), points, SoloPhase.PREPARE);
        assertEquals("supply_inventory_blocked", o.getReason());
        o = plan.prepare(supplies(0).toBuilder().freeSlots(1).unfinishedPotionCount(6).build(), points, SoloPhase.PREPARE);
        assertEquals(TargetKind.HERBS, o.getTarget()); assertEquals(1, o.getQuantity());
        o = plan.prepare(supplies(0).toBuilder().freeSlots(0).unfinishedPotionCount(6).brumaHerbCount(1).build(), points, SoloPhase.PREPARE);
        assertEquals("mix_rejuvenation", o.getReason()); assertEquals(1, o.getQuantity());
        o = plan.prepare(supplies(4).toBuilder().freeSlots(1).unfinishedPotionCount(5).build(), points, SoloPhase.PREPARE);
        assertEquals(TargetKind.HERBS, o.getTarget()); assertEquals(1, o.getQuantity());
    }

    @Test public void newRoundPreservesAUsableReserveAndRestocksOnlyAfterItFallsBelowThreshold()
    {
        assertNull(plan.prepare(supplies(12).toBuilder().roundState(RoundState.ACTIVE).build(), points, SoloPhase.SUSTAIN));
        for (int round = 0; round < 3; round++)
        {
            plan.nextRound();
            assertNull(plan.prepare(supplies(12).toBuilder().roundState(RoundState.COUNTDOWN).build(), points, SoloPhase.PREPARE));
        }
        assertNull(plan.prepare(supplies(8), points, SoloPhase.PREPARE));
        WintertodtObjective deficit = plan.prepare(supplies(7), points, SoloPhase.PREPARE);
        assertEquals(TargetKind.POTION_CRATE, deficit.getTarget()); assertEquals(5, deficit.getQuantity());
    }

    @Test public void unusedFullReserveAndSurplusIngredientsNeverCauseExtraPreparation()
    {
        WintertodtSnapshot full = supplies(24).toBuilder().unfinishedPotionCount(3).brumaHerbCount(3).build();
        assertNull(plan.prepare(full, points, SoloPhase.SUSTAIN));
        plan.nextRound();
        assertNull(plan.prepare(full, points, SoloPhase.PREPARE));
    }

    @Test public void interruptedMixingAndFinishReserveSurviveTheEncounterBoundary()
    {
        WintertodtSnapshot ingredients = supplies(0).toBuilder().unfinishedPotionCount(6).brumaHerbCount(6).freeSlots(0).build();
        assertEquals(6, plan.prepare(ingredients, points, SoloPhase.PREPARE).getQuantity());
        plan.nextRound();
        WintertodtObjective remainder = plan.prepare(supplies(4).toBuilder().unfinishedPotionCount(5).brumaHerbCount(5).freeSlots(1).build(), points, SoloPhase.PREPARE);
        assertEquals("mix_rejuvenation", remainder.getReason()); assertEquals(5, remainder.getQuantity());
        assertNull(plan.prepare(supplies(24), points, SoloPhase.SUSTAIN));
        assertNull(plan.prepare(supplies(8), points, SoloPhase.FINISH));
        plan.nextRound();
        assertNull(plan.prepare(supplies(8), points, SoloPhase.PREPARE));
        assertEquals(24, plan.getTarget());
    }

    @Test public void simulatedPreparationCompletesAcrossCapacityLimitsAndRoundInterruptions()
    {
        for (int capacity = 7; capacity <= 20; capacity++)
        {
            plan.reset(); int vials = 0, herbs = 0, doses = 0, free = capacity;
            for (int action = 0; action < 60 && doses < 24; action++)
            {
                if (action % 5 == 4) { plan.nextRound(); }
                WintertodtObjective o = plan.prepare(supplies(doses).toBuilder().unfinishedPotionCount(vials)
                    .brumaHerbCount(herbs).freeSlots(free).build(), points, SoloPhase.PREPARE);
                assertNotNull(o); assertTrue(o.getQuantity() > 0);
                // Apply one actual player action, not the entire requested batch.
                if (o.getTarget() == TargetKind.POTION_CRATE) { assertTrue(free > 0); vials++; free--; }
                else if (o.getTarget() == TargetKind.HERBS) { assertTrue(free > 0); herbs++; free--; }
                else { assertEquals("mix_rejuvenation", o.getReason()); assertTrue(vials > 0 && herbs > 0); vials--; herbs--; doses += 4; free++; }
            }
            assertEquals("Capacity " + capacity, 24, doses);
            assertNull(plan.prepare(supplies(doses).toBuilder().unfinishedPotionCount(vials).brumaHerbCount(herbs).freeSlots(free).build(), points, SoloPhase.PREPARE));
        }
    }

    @Test public void brewmaAlsoWaitsForTheRequestedHerbBatch()
    {
        WintertodtSnapshot s = supplies(0).toBuilder().canMixPotion(false).unfinishedPotionCount(6)
            .brumaHerbCount(1).freeSlots(13).build();
        WintertodtObjective gather = plan.prepare(s, points, SoloPhase.PREPARE);
        assertEquals(TargetKind.HERBS, gather.getTarget()); assertEquals(5, gather.getQuantity());
        WintertodtObjective brew = plan.prepare(s.toBuilder().brumaHerbCount(6).freeSlots(8).build(), points, SoloPhase.PREPARE);
        assertEquals(TargetKind.BREWMA, brew.getTarget()); assertEquals(6, brew.getQuantity());
    }

}

package com.wintertodtautopilot;

