    {
        when(player.getWorldLocation()).thenReturn(new WorldPoint(1630, 3975, 0));
        WintertodtSnapshot s = tick(10);
        verify(rounds).fill(any(), eq(true), anyInt());
        assertTrue(s.active());
        assertEquals(78, s.getWarmth());
    }
