    {
        tick(10);
        when(player.getWorldLocation()).thenReturn(new WorldPoint(1638, 3998, 0));
        assertEquals(PlayerActivity.MOVING, tick(20).getCurrentActivity());
        assertFalse(tick(21).isPlayerIdle()); assertTrue(tick(25).isPlayerIdle());
